@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;450;500;550;600;650;700;750;800&family=JetBrains+Mono:wght@400;500;600;700&display=swap");

/* 1. Reset / Base */
:root {
  --font-ui: Inter, "Plus Jakarta Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono", "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-family: var(--font-ui);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --ease-emphasized: cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast: 120ms;
  --duration-normal: 180ms;
  --duration-slow: 240ms;

  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-7: 28px;
  --space-8: 32px;
  --radius-xs: 10px;
  --radius-sm: 12px;
  --radius-md: 16px;
  --radius-lg: 20px;
  --radius-xl: 24px;
}

* { box-sizing: border-box; min-width: 0; }
*::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--bg);
  color: var(--text-primary);
}
button, input, textarea, select { font: inherit; }
button { border: 0; cursor: pointer; }
button:disabled { cursor: not-allowed; }
a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
svg { flex: 0 0 auto; }

/* 2. Theme tokens */
html[data-theme="dark"], .app-shell[data-theme="dark"] {
  --bg: #071014;
  --bg-soft: #0B1720;
  --surface-1: #101D27;
  --surface-2: #132532;
  --surface-3: #182B38;
  --surface-elevated: #1B3040;
  --border-subtle: rgba(148, 163, 184, 0.16);
  --border-medium: rgba(148, 163, 184, 0.24);
  --border-accent: rgba(45, 212, 191, 0.32);
  --text-primary: #F8FAFC;
  --text-secondary: #CBD5E1;
  --text-muted: #94A3B8;
  --text-faint: #64748B;
  --accent: #2DD4BF;
  --accent-strong: #14B8A6;
  --accent-blue: #38BDF8;
  --warning: #F59E0B;
  --danger: #EF4444;
  --success: #22C55E;
  --info: #60A5FA;
  --violet: #A78BFA;
  --sky: #38BDF8;
  --lime: #84CC16;
  --shadow-card: 0 1px 2px rgba(0, 0, 0, 0.22);
  --shadow-elevated: 0 12px 30px rgba(0, 0, 0, 0.18);
  --shadow-hover: 0 0 0 1px rgba(45, 212, 191, 0.22), 0 16px 36px rgba(0, 0, 0, 0.28);
}

html[data-theme="light"], .app-shell[data-theme="light"] {
  --bg: #F6F8FA;
  --bg-soft: #EEF3F6;
  --surface-1: #FFFFFF;
  --surface-2: #F8FAFC;
  --surface-3: #F1F5F9;
  --surface-elevated: #FFFFFF;
  --border-subtle: #E2E8F0;
  --border-medium: #CBD5E1;
  --border-accent: rgba(15, 118, 110, 0.26);
  --text-primary: #0F172A;
  --text-secondary: #334155;
  --text-muted: #64748B;
  --text-faint: #94A3B8;
  --accent: #0F766E;
  --accent-strong: #115E59;
  --accent-blue: #0284C7;
  --warning: #D97706;
  --danger: #DC2626;
  --success: #16A34A;
  --info: #2563EB;
  --violet: #7C3AED;
  --sky: #0284C7;
  --lime: #65A30D;
  --shadow-card: 0 1px 2px rgba(15, 23, 42, 0.08);
  --shadow-elevated: 0 12px 28px rgba(15, 23, 42, 0.10);
  --shadow-hover: 0 10px 26px rgba(15, 23, 42, 0.10);
}

/* 3. Layout */
.app-shell {
  min-height: 100vh;
  background:
    radial-gradient(circle at top right, color-mix(in srgb, var(--accent) 18%, transparent) 0, transparent 360px),
    radial-gradient(circle at 0 20%, color-mix(in srgb, var(--accent-blue) 12%, transparent) 0, transparent 320px),
    linear-gradient(180deg, var(--bg), var(--bg-soft));
  color: var(--text-primary);
  padding-top: 86px;
}

.app-shell::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: 0.08;
  background-image:
    linear-gradient(var(--text-muted) 1px, transparent 1px),
    linear-gradient(90deg, var(--text-muted) 1px, transparent 1px);
  background-size: 34px 34px;
  mask-image: linear-gradient(to bottom, #000 0, transparent 70%);
}

.page-shell {
  width: min(1280px, calc(100% - 32px));
  margin: 0 auto;
  padding: 24px 0 64px;
  position: relative;
  z-index: 1;
}

.home-page-shell { display: grid; gap: 28px; }
.card-surface {
  background: linear-gradient(180deg, color-mix(in srgb, var(--surface-1) 94%, transparent), var(--surface-1));
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-card);
}

.top-shell-nav {
  position: fixed;
  top: 12px;
  left: 50%;
  z-index: 50;
  width: min(1280px, calc(100% - 32px));
  min-height: 68px;
  transform: translateX(-50%);
  display: grid;
  grid-template-columns: minmax(180px, 1fr) auto minmax(260px, 1fr);
  align-items: center;
  gap: 16px;
  padding: 10px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: 22px;
  background: color-mix(in srgb, var(--surface-1) 86%, transparent);
  backdrop-filter: blur(18px);
  box-shadow: var(--shadow-elevated);
}

.nav-brand, .nav-actions, .segmented-control { display: flex; align-items: center; min-width: 0; }
.nav-brand {
  gap: 12px;
  color: var(--text-primary);
  background: transparent;
  text-align: left;
  min-height: 44px;
}
.nav-brand-mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  color: var(--accent);
  border: 1px solid var(--border-accent);
  border-radius: 14px;
  background: color-mix(in srgb, var(--accent) 12%, transparent);
}
.nav-brand-copy { display: grid; gap: 2px; }
.nav-brand strong { font-size: 16px; font-weight: 780; line-height: 1.1; }
.nav-brand small { color: var(--text-muted); font-size: 12px; line-height: 1.2; overflow-wrap: break-word; }
.nav-actions { justify-content: flex-end; gap: 10px; }
.nav-score-chip {
  display: grid;
  gap: 1px;
  min-height: 44px;
  padding: 7px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
  background: var(--surface-2);
}
.nav-score-chip span { color: var(--text-muted); font-size: 10px; font-weight: 750; letter-spacing: .08em; text-transform: uppercase; }
.nav-score-chip strong { font-size: 15px; }

.segmented-control {
  justify-self: center;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--border-subtle);
  border-radius: 16px;
  background: var(--surface-2);
}
.segmented-control button {
  min-height: 40px;
  padding: 0 14px;
  border-radius: 12px;
  color: var(--text-secondary);
  background: transparent;
  font-size: 14px;
  font-weight: 700;
  transition: background-color var(--duration-normal) var(--ease-standard), color var(--duration-normal) var(--ease-standard), box-shadow var(--duration-normal) var(--ease-standard);
}
.segmented-control button.active { color: var(--text-primary); background: var(--surface-elevated); box-shadow: var(--shadow-card); }

/* 4. Typography */
h1, h2, h3, h4, p { margin: 0; min-width: 0; }
h1 { font-size: clamp(30px, 4.3vw, 52px); line-height: 1.05; font-weight: 800; letter-spacing: -0.04em; color: var(--text-primary); }
h2 { font-size: clamp(22px, 2.6vw, 32px); line-height: 1.14; font-weight: 760; letter-spacing: -0.025em; }
h3 { font-size: 18px; line-height: 1.25; font-weight: 720; }
h4 { font-size: 15px; line-height: 1.25; font-weight: 720; }
p { color: var(--text-secondary); font-size: 15px; line-height: 1.65; overflow-wrap: break-word; }
.label-text, .eyebrow, .section-kicker {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
}
.label-text.accent, .section-kicker { color: var(--accent); }

/* 5. Reusable components */
.btn, .primary-action, .secondary-action, .ghost-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 14px;
  font-size: 14px;
  font-weight: 750;
  white-space: nowrap;
  transition: background-color var(--duration-normal) var(--ease-standard), border-color var(--duration-normal) var(--ease-standard), color var(--duration-normal) var(--ease-standard), box-shadow var(--duration-normal) var(--ease-standard), transform var(--duration-normal) var(--ease-standard);
}
.btn svg { width: 18px; height: 18px; }
.btn-primary, .primary-action {
  color: #06211f;
  background: linear-gradient(135deg, var(--accent), var(--accent-blue));
  box-shadow: 0 10px 24px color-mix(in srgb, var(--accent) 22%, transparent);
}
.btn-primary:hover, .primary-action:hover { transform: translateY(-1px); box-shadow: var(--shadow-hover); }
.btn-secondary, .secondary-action {
  color: var(--text-primary);
  border: 1px solid var(--border-subtle);
  background: var(--surface-2);
}
.btn-secondary:hover, .secondary-action:hover { border-color: var(--border-accent); background: var(--surface-3); }
.btn-ghost, .ghost-link { color: var(--text-secondary); background: transparent; border: 1px solid var(--border-subtle); }
.btn-icon { padding: 0 12px; border: 1px solid var(--border-subtle); color: var(--text-primary); background: var(--surface-2); }
.btn.compact, .secondary-action.compact { min-height: 38px; padding: 0 12px; border-radius: 12px; }
button:disabled, .btn:disabled { opacity: .58; transform: none; box-shadow: none; }
button:focus-visible, a:focus-visible, textarea:focus-visible { outline: 3px solid color-mix(in srgb, var(--accent) 55%, transparent); outline-offset: 3px; }

.icon-badge {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  border: 1px solid var(--border-accent);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  color: var(--accent);
}
.icon-badge-sm { width: 36px; height: 36px; border-radius: 12px; }
.icon-badge-md { width: 44px; height: 44px; }
.icon-badge svg { width: 20px; height: 20px; stroke-width: 1.9; }
.icon-badge-sm svg { width: 18px; height: 18px; }
.icon-badge-danger { color: var(--danger); background: color-mix(in srgb, var(--danger) 12%, transparent); border-color: color-mix(in srgb, var(--danger) 34%, transparent); }
.icon-badge-warning { color: var(--warning); background: color-mix(in srgb, var(--warning) 12%, transparent); border-color: color-mix(in srgb, var(--warning) 34%, transparent); }
.icon-badge-success { color: var(--success); background: color-mix(in srgb, var(--success) 12%, transparent); border-color: color-mix(in srgb, var(--success) 34%, transparent); }
.icon-badge-blue, .icon-badge-sky { color: var(--accent-blue); background: color-mix(in srgb, var(--accent-blue) 12%, transparent); border-color: color-mix(in srgb, var(--accent-blue) 34%, transparent); }
.icon-badge-violet { color: var(--violet); background: color-mix(in srgb, var(--violet) 12%, transparent); border-color: color-mix(in srgb, var(--violet) 34%, transparent); }
.icon-badge-lime { color: var(--lime); background: color-mix(in srgb, var(--lime) 12%, transparent); border-color: color-mix(in srgb, var(--lime) 34%, transparent); }
.icon-badge-slate { color: var(--text-muted); background: var(--surface-2); border-color: var(--border-subtle); }
.icon-badge-accent { color: var(--accent); background: color-mix(in srgb, var(--accent) 12%, transparent); border-color: color-mix(in srgb, var(--accent) 34%, transparent); }

.tag, .difficulty-badge, .branch-count, .compact-status-pill, .feedback-badge {
  display: inline-flex;
  align-items: center;
  width: max-content;
  max-width: 100%;
  min-height: 26px;
  padding: 4px 9px;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  background: var(--surface-2);
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .02em;
  overflow-wrap: break-word;
}
.difficulty-badge.danger, .difficulty-badge.critical, .feedback-badge.danger { color: var(--danger); background: color-mix(in srgb, var(--danger) 10%, transparent); border-color: color-mix(in srgb, var(--danger) 32%, transparent); }
.difficulty-badge.warning, .feedback-badge.warning { color: var(--warning); background: color-mix(in srgb, var(--warning) 10%, transparent); border-color: color-mix(in srgb, var(--warning) 32%, transparent); }
.difficulty-badge.success, .feedback-badge.success { color: var(--success); background: color-mix(in srgb, var(--success) 10%, transparent); border-color: color-mix(in srgb, var(--success) 32%, transparent); }
.feedback-badge.neutral { color: var(--accent-blue); }
.clean-list { margin: 0; padding: 0; list-style: none; display: grid; gap: 9px; }
.clean-list li { position: relative; padding-left: 18px; color: var(--text-secondary); font-size: 14px; line-height: 1.55; overflow-wrap: break-word; }
.clean-list li::before { content: ""; position: absolute; left: 0; top: .65em; width: 7px; height: 7px; border-radius: 50%; background: var(--accent); }

/* 6. Page-specific components: Home */
.home-dashboard-grid { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 22px; align-items: stretch; }
.hero-panel { position: relative; overflow: hidden; padding: clamp(22px, 3vw, 34px); display: grid; gap: 24px; }
.hero-ambient { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(circle at 82% 10%, color-mix(in srgb, var(--accent) 20%, transparent), transparent 34%), linear-gradient(135deg, transparent 0, color-mix(in srgb, var(--accent-blue) 7%, transparent) 100%); opacity: .95; }
.hero-content { position: relative; display: grid; gap: 20px; }
.badge-row, .feature-chip-row, .clinical-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.badge-row span, .feature-chip-row span, .clinical-chips span {
  min-height: 28px; display: inline-flex; align-items: center; padding: 5px 10px; border-radius: 999px; border: 1px solid var(--border-subtle); background: color-mix(in srgb, var(--surface-2) 80%, transparent); color: var(--text-secondary); font-size: 12px; font-weight: 700;
}
.hero-copy { max-width: 740px; display: grid; gap: 12px; }
.hero-copy p { font-size: 17px; color: var(--text-secondary); max-width: 690px; }
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; }
.stat-grid { position: relative; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.stat-card { display: grid; grid-template-columns: 38px minmax(0, 1fr); gap: 12px; align-items: center; padding: 14px; border-radius: var(--radius-md); border: 1px solid var(--border-subtle); background: color-mix(in srgb, var(--surface-2) 76%, transparent); }
.stat-copy { display: grid; gap: 2px; }
.stat-copy span { color: var(--text-muted); font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .08em; }
.stat-copy strong { color: var(--text-primary); font-size: 24px; line-height: 1.05; }
.stat-copy small { color: var(--text-muted); font-size: 12px; line-height: 1.3; }
.mode-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.mode-card { min-height: 210px; display: grid; align-content: start; gap: 16px; padding: 18px; text-align: left; color: var(--text-primary); border: 1px solid var(--border-subtle); border-radius: var(--radius-lg); background: var(--surface-2); transition: background-color var(--duration-normal) var(--ease-standard), border-color var(--duration-normal) var(--ease-standard), box-shadow var(--duration-normal) var(--ease-standard), transform var(--duration-normal) var(--ease-standard); }
.mode-card:hover { transform: translateY(-1px); border-color: var(--border-accent); box-shadow: var(--shadow-hover); }
.mode-card.active { border-color: var(--border-accent); background: color-mix(in srgb, var(--accent) 8%, var(--surface-2)); }
.mode-card-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.mode-selected-indicator { color: var(--text-muted); font-size: 12px; font-weight: 800; }
.mode-card.active .mode-selected-indicator { color: var(--accent); }
.mode-card-copy { display: grid; gap: 7px; }
.mode-card-copy strong { font-size: 18px; line-height: 1.25; }
.mode-card-copy p { font-size: 14px; }
.dashboard-aside-card { padding: 20px; display: grid; gap: 18px; align-content: start; }
.panel-title-row, .section-title-row, .exam-results-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.panel-title-row.compact { margin-bottom: 16px; }
.compact-metric-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 10px; }
.compact-metric-grid div, .exam-results-metrics div { display: grid; gap: 5px; padding: 12px; border-radius: 14px; background: var(--surface-2); border: 1px solid var(--border-subtle); }
.compact-metric-grid span, .exam-results-metrics span { color: var(--text-muted); font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .08em; }
.compact-metric-grid strong, .exam-results-metrics strong { color: var(--text-primary); font-size: 18px; overflow-wrap: break-word; }
.leaderboard-list { display: grid; gap: 10px; }
.leaderboard-row { display: grid; grid-template-columns: 32px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 11px; border: 1px solid var(--border-subtle); border-radius: 14px; background: var(--surface-2); }
.rank-badge { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 10px; background: color-mix(in srgb, var(--accent) 12%, transparent); color: var(--accent); font-weight: 800; }
.leaderboard-copy { display: grid; gap: 2px; }
.leaderboard-copy strong, .leaderboard-copy small { overflow-wrap: break-word; }
.leaderboard-copy small { color: var(--text-muted); font-size: 12px; line-height: 1.35; }
.leaderboard-score { font-weight: 800; color: var(--accent); }
.empty-state-mini { display: grid; grid-template-columns: 36px minmax(0,1fr); gap: 12px; align-items: center; padding: 14px; border: 1px solid var(--border-subtle); border-radius: 16px; background: var(--surface-2); }
.empty-state-mini p { font-size: 13px; }

/* Branch and case list */
.section-block { display: grid; gap: 18px; }
.section-title-row p { max-width: 520px; }
.branch-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; }
.branch-card { min-height: 270px; display: grid; grid-template-rows: auto minmax(0,1fr) auto auto; gap: 14px; padding: 18px; text-align: left; color: var(--text-primary); border: 1px solid var(--border-subtle); border-radius: var(--radius-lg); background: var(--surface-1); box-shadow: var(--shadow-card); transition: transform var(--duration-normal) var(--ease-standard), border-color var(--duration-normal) var(--ease-standard), box-shadow var(--duration-normal) var(--ease-standard), background-color var(--duration-normal) var(--ease-standard); }
.branch-card:hover { transform: translateY(-1px); border-color: var(--border-accent); box-shadow: var(--shadow-hover); background: var(--surface-2); }
.branch-card-head, .branch-card-footer, .branch-card-meta, .case-list-topline, .case-list-footer { display: flex; align-items: center; gap: 10px; }
.branch-card-head, .branch-card-footer, .case-list-topline { justify-content: space-between; }
.branch-card-body { display: grid; gap: 8px; align-content: start; }
.branch-card-body h3 { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.branch-card-body p { display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden; font-size: 14px; }
.branch-progress { height: 6px; overflow: hidden; border-radius: 999px; background: var(--surface-3); border: 1px solid var(--border-subtle); }
.branch-progress span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--accent), var(--accent-blue)); }
.branch-card-meta { flex-wrap: wrap; }
.branch-card-meta span { color: var(--text-muted); font-size: 12px; font-weight: 700; }
.branch-card-footer { color: var(--accent); font-weight: 800; }
.branch-card-footer svg { width: 18px; height: 18px; }
.case-page-shell { display: grid; grid-template-columns: 310px minmax(0, 1fr); gap: 22px; align-items: start; }
.sidebar-layout { position: sticky; top: 98px; display: grid; gap: 14px; max-height: calc(100vh - 116px); overflow: auto; padding-right: 2px; }
.sidebar-branch-card { padding: 18px; display: grid; gap: 12px; }
.branch-sidebar-actions { margin-top: 4px; }
.case-list { display: grid; gap: 10px; }
.case-list-item { display: grid; gap: 8px; width: 100%; min-height: 124px; padding: 14px; text-align: left; color: var(--text-primary); border: 1px solid var(--border-subtle); border-radius: 16px; background: var(--surface-1); transition: border-color var(--duration-normal) var(--ease-standard), background-color var(--duration-normal) var(--ease-standard), transform var(--duration-normal) var(--ease-standard); }
.case-list-item:hover, .case-list-item.active { border-color: var(--border-accent); background: var(--surface-2); }
.case-list-item:hover { transform: translateY(-1px); }
.case-list-item strong { font-size: 15px; line-height: 1.3; overflow-wrap: break-word; }
.case-list-item p { font-size: 13px; line-height: 1.45; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.case-list-topline small:first-child, .case-list-footer { color: var(--text-muted); font-size: 12px; font-weight: 750; }

/* QBank case */
.qbank-shell { display: grid; grid-template-columns: minmax(0, 1fr) minmax(340px, 390px); gap: 20px; align-items: start; }
.qbank-main-column { display: grid; gap: 16px; }
.qbank-side-column { position: sticky; top: 98px; display: grid; gap: 14px; max-height: calc(100vh - 112px); overflow: auto; padding-right: 2px; }
.case-hero-card, .case-narrative-card, .clinical-data-card, .investigation-section, .media-section, .question-panel, .tools-panel { padding: clamp(18px, 2.2vw, 24px); }
.qbank-header-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 18px; align-items: start; margin-bottom: 18px; }
.case-title-copy { display: grid; gap: 8px; }
.case-title-copy h1 { font-size: clamp(26px, 3vw, 38px); }
.case-title-copy p { max-width: 820px; }
.qbank-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; }
.patient-strip { display: grid; grid-template-columns: repeat(5, minmax(150px, 1fr)); gap: 12px; }
.patient-strip-item { min-width: 0; padding: 14px 16px; border-radius: 16px; background: var(--surface-2); border: 1px solid var(--border-subtle); }
.patient-strip-item span { display: block; margin-bottom: 6px; font-size: 11px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-muted); }
.patient-strip-item strong { display: block; min-width: 0; font-size: 15px; line-height: 1.35; color: var(--text-primary); overflow-wrap: break-word; }
.patient-strip-item.wide { grid-column: span 2; }
.case-narrative-card { display: grid; gap: 18px; }
.case-chief { display: grid; gap: 7px; padding: 16px; border-radius: 16px; background: color-mix(in srgb, var(--accent) 8%, var(--surface-2)); border: 1px solid var(--border-accent); }
.case-chief span { color: var(--accent); font-size: 11px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.case-chief strong { font-size: 18px; line-height: 1.35; overflow-wrap: break-word; }
.stem-highlight-wrap { display: flex; flex-wrap: wrap; gap: 7px; }
.stem-sentence { display: inline; max-width: 100%; padding: 3px 5px; border-radius: 8px; color: var(--text-secondary); background: transparent; font-size: 15.5px; line-height: 1.65; text-align: left; overflow-wrap: break-word; transition: background-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard); }
.stem-sentence:hover { color: var(--text-primary); background: var(--surface-2); }
.stem-sentence.highlighted { color: var(--text-primary); }
.hl-yellow { background: color-mix(in srgb, var(--warning) 20%, transparent); }
.hl-green { background: color-mix(in srgb, var(--success) 18%, transparent); }
.hl-blue { background: color-mix(in srgb, var(--accent-blue) 18%, transparent); }
.hl-rose { background: color-mix(in srgb, var(--danger) 16%, transparent); }
.vitals-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; margin-bottom: 16px; }
.vital-card { display: grid; grid-template-columns: 36px minmax(0, 1fr); gap: 12px; align-items: center; min-width: 0; padding: 14px; border-radius: 16px; background: var(--surface-2); border: 1px solid var(--border-subtle); }
.vital-card.warning { border-color: color-mix(in srgb, var(--warning) 28%, var(--border-subtle)); }
.vital-card.danger { border-color: color-mix(in srgb, var(--danger) 34%, var(--border-subtle)); }
.vital-card.normal { border-color: color-mix(in srgb, var(--success) 22%, var(--border-subtle)); }
.vital-copy { display: grid; gap: 4px; min-width: 0; }
.vital-copy span { font-size: 11px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-muted); }
.vital-copy strong { font-size: 18px; line-height: 1.2; color: var(--text-primary); overflow-wrap: break-word; }
.qbank-supplement-grid { display: grid; gap: 16px; }

/* Accordion / investigations */
.qbank-accordion-stack, .investigation-stack { display: grid; gap: 10px; }
.accordion-item { overflow: hidden; border: 1px solid var(--border-subtle); border-radius: 18px; background: var(--surface-2); }
.accordion-item.open { border-color: var(--border-medium); background: var(--surface-2); }
.accordion-trigger { display: grid; grid-template-columns: 44px minmax(0, 1fr) 36px; gap: 14px; align-items: start; width: 100%; min-height: 70px; padding: 14px; color: var(--text-primary); text-align: left; background: transparent; }
.accordion-prefix { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 13px; color: var(--accent); background: color-mix(in srgb, var(--accent) 10%, transparent); border: 1px solid var(--border-accent); font-weight: 800; }
.accordion-copy { display: grid; gap: 5px; min-width: 0; }
.accordion-copy strong { display: block; line-height: 1.25; overflow-wrap: break-word; }
.accordion-copy small { display: block; margin-top: 2px; line-height: 1.45; color: var(--text-secondary); overflow-wrap: break-word; }
.accordion-toggle { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 12px; color: var(--text-muted); background: var(--surface-1); border: 1px solid var(--border-subtle); }
.accordion-toggle svg { width: 18px; height: 18px; transition: transform var(--duration-normal) var(--ease-standard); }
.accordion-item.open .accordion-toggle svg { transform: rotate(180deg); }
.accordion-panel { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 220ms var(--ease-standard); }
.accordion-item.open .accordion-panel { grid-template-rows: 1fr; }
.accordion-panel-inner { overflow: hidden; padding: 0 14px; }
.accordion-item.open .accordion-panel-inner { padding-bottom: 14px; }
.detail-copy { padding: 14px; border-radius: 14px; background: var(--surface-1); border: 1px solid var(--border-subtle); }
.detail-block { display: grid; gap: 10px; margin-top: 12px; }
.table-wrap { overflow-x: auto; border: 1px solid var(--border-subtle); border-radius: 14px; }
table { width: 100%; min-width: 640px; border-collapse: collapse; }
th, td { padding: 12px; text-align: left; border-bottom: 1px solid var(--border-subtle); font-size: 13px; line-height: 1.4; color: var(--text-secondary); overflow-wrap: break-word; }
th { color: var(--text-muted); font-size: 11px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; background: var(--surface-2); }
tr:last-child td { border-bottom: 0; }
.clinical-callout { display: grid; grid-template-columns: 36px minmax(0,1fr); gap: 12px; align-items: start; margin-top: 14px; padding: 14px; border-radius: 16px; border: 1px solid var(--border-subtle); background: var(--surface-2); }
.clinical-callout.info { border-color: color-mix(in srgb, var(--info) 28%, var(--border-subtle)); background: color-mix(in srgb, var(--info) 8%, var(--surface-2)); }
.clinical-callout.warning { border-color: color-mix(in srgb, var(--warning) 32%, var(--border-subtle)); background: color-mix(in srgb, var(--warning) 8%, var(--surface-2)); }
.clinical-callout-copy { display: grid; gap: 4px; }
.clinical-callout-copy p { font-size: 14px; }

/* Media */
.media-section { display: grid; gap: 14px; }
.media-stack { display: grid; gap: 14px; }
.evidence-figure { margin: 0; display: grid; gap: 10px; }
.media-frame { position: relative; overflow: hidden; display: grid; place-items: center; min-height: 220px; border-radius: 18px; border: 1px solid var(--border-subtle); background: #0A1118; }
.media-frame img { width: 100%; max-height: 460px; object-fit: contain; }
.media-zoom { position: absolute; top: 10px; right: 10px; display: grid; place-items: center; width: 38px; height: 38px; border-radius: 13px; color: var(--text-primary); background: color-mix(in srgb, var(--surface-1) 72%, transparent); border: 1px solid var(--border-subtle); backdrop-filter: blur(12px); }
.image-fallback { display: grid; grid-template-columns: 36px minmax(0,1fr); gap: 12px; align-items: center; width: min(520px, calc(100% - 24px)); padding: 14px; border-radius: 16px; background: var(--surface-2); border: 1px solid var(--border-subtle); }
.image-fallback.small { width: 100%; }
.image-fallback span { display: block; color: var(--text-muted); font-size: 13px; line-height: 1.4; }
.evidence-figure figcaption { display: grid; gap: 6px; padding: 0 2px; }
.media-caption-topline { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; color: var(--text-muted); font-size: 12px; }
.evidence-figure figcaption strong { font-size: 14px; }
.evidence-figure figcaption > span { color: var(--text-secondary); font-size: 13px; line-height: 1.5; overflow-wrap: break-word; }

/* Question panel / answers */
.question-panel { display: grid; gap: 16px; }
.question-panel-head { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 14px; align-items: start; }
.question-panel-head h2 { font-size: 24px; }
.question-panel-head p { font-size: 14px; }
.question-score-chip { display: grid; gap: 4px; min-width: 88px; padding: 10px 12px; border: 1px solid var(--border-subtle); border-radius: 14px; background: var(--surface-2); text-align: right; }
.question-score-chip span { color: var(--text-muted); font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .08em; }
.question-score-chip strong { font-size: 18px; color: var(--accent); }
.exam-progress-box { display: grid; gap: 8px; padding: 12px; border: 1px solid var(--border-subtle); border-radius: 14px; background: var(--surface-2); }
.exam-progress-top { display: flex; justify-content: space-between; gap: 12px; font-size: 12px; color: var(--text-muted); font-weight: 750; }
.exam-progress-track { height: 7px; overflow: hidden; border-radius: 999px; background: var(--surface-3); }
.exam-progress-track span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--accent), var(--accent-blue)); }
.tutor-hint-card { display: grid; grid-template-columns: 36px minmax(0, 1fr); gap: 12px; padding: 12px; border-radius: 16px; border: 1px solid var(--border-accent); background: color-mix(in srgb, var(--accent) 8%, var(--surface-2)); }
.tutor-hint-card p { font-size: 13px; }
.option-grid { display: grid; gap: 10px; }
.answer-option { display: grid; grid-template-columns: 42px minmax(0, 1fr) 26px; gap: 12px; align-items: center; width: 100%; min-height: 66px; padding: 14px 16px; border-radius: 16px; border: 1px solid var(--border-subtle); background: var(--surface-2); color: var(--text-primary); text-align: left; transition: background-color var(--duration-normal) var(--ease-standard), border-color var(--duration-normal) var(--ease-standard), box-shadow var(--duration-normal) var(--ease-standard), transform var(--duration-normal) var(--ease-standard); }
.answer-option:hover:not(:disabled) { border-color: var(--border-accent); background: var(--surface-3); transform: translateY(-1px); }
.answer-letter { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 12px; background: var(--surface-1); border: 1px solid var(--border-subtle); font-weight: 800; color: var(--text-secondary); flex: 0 0 auto; }
.answer-content { display: grid; gap: 3px; min-width: 0; }
.answer-title { display: block; min-width: 0; font-size: 15.5px; font-weight: 680; line-height: 1.35; color: var(--text-primary); overflow-wrap: break-word; text-wrap: pretty; }
.answer-subtitle { display: block; min-width: 0; font-size: 13px; line-height: 1.35; color: var(--text-muted); overflow-wrap: break-word; }
.answer-status-icon { display: grid; place-items: center; width: 26px; height: 26px; color: var(--text-muted); }
.answer-status-icon svg { width: 22px; height: 22px; }
.answer-option.selected { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 10%, var(--surface-2)); box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 36%, transparent); }
.answer-option.correct { border-color: var(--success); background: color-mix(in srgb, var(--success) 12%, var(--surface-2)); }
.answer-option.correct .answer-status-icon { color: var(--success); }
.answer-option.wrong { border-color: var(--danger); background: color-mix(in srgb, var(--danger) 10%, var(--surface-2)); }
.answer-option.wrong .answer-status-icon { color: var(--danger); }
.quiz-actions { display: grid; gap: 10px; }
.feedback { display: grid; gap: 14px; padding: 14px; border-radius: 18px; border: 1px solid var(--border-subtle); background: var(--surface-2); }
.feedback.success { border-color: color-mix(in srgb, var(--success) 34%, var(--border-subtle)); }
.feedback.danger { border-color: color-mix(in srgb, var(--danger) 34%, var(--border-subtle)); }
.feedback-header { display: grid; grid-template-columns: 36px minmax(0,1fr); gap: 12px; align-items: start; }
.feedback-header-split { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.feedback-main-copy { display: grid; gap: 6px; }
.feedback-kicker { color: var(--text-muted); font-size: 12px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.feedback-answer { color: var(--text-primary); font-weight: 750; line-height: 1.45; }
.feedback-explanation { color: var(--text-secondary); font-size: 14px; }
.score-pill-block { display: grid; gap: 3px; min-width: 104px; padding: 10px 12px; border-radius: 14px; background: var(--surface-1); border: 1px solid var(--border-subtle); text-align: right; }
.score-pill-block span { color: var(--text-muted); font-size: 11px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.score-pill-block strong { font-size: 20px; color: var(--accent); }
.score-pill-block small { color: var(--text-muted); font-size: 11px; line-height: 1.3; }
.feedback-grid { display: grid; gap: 10px; }
.feedback-grid.duo { grid-template-columns: repeat(2, minmax(0,1fr)); }
.feedback-grid.triad { grid-template-columns: repeat(3, minmax(0,1fr)); }
.feedback-panel { display: grid; gap: 9px; padding: 12px; border-radius: 14px; background: var(--surface-1); border: 1px solid var(--border-subtle); }
.feedback-panel p { font-size: 13px; }
.exam-nav-actions { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 10px; }

/* Tools */
.tools-panel { display: grid; gap: 14px; }
.tools-panel-head, .compact-row-head, .tools-section.compact-tool-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.tools-panel-head h3 { margin-top: 4px; }
.tools-mini-stats { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 8px; }
.tools-mini-stats div { padding: 10px; border-radius: 14px; background: var(--surface-2); border: 1px solid var(--border-subtle); }
.tools-mini-stats span { display: block; color: var(--text-muted); font-size: 10px; font-weight: 800; text-transform: uppercase; letter-spacing: .08em; }
.tools-mini-stats strong { display: block; margin-top: 4px; font-size: 14px; }
.tools-section { padding: 12px; border: 1px solid var(--border-subtle); border-radius: 16px; background: var(--surface-2); }
.tools-section.vertical { display: grid; gap: 12px; }
.tool-copy { display: grid; gap: 2px; margin-right: auto; }
.tool-copy span, .compact-row-head span { color: var(--text-muted); font-size: 12px; line-height: 1.3; }
.toggle-chip, .text-reset-button { min-height: 36px; padding: 0 12px; border-radius: 12px; color: var(--text-secondary); background: var(--surface-1); border: 1px solid var(--border-subtle); font-size: 12px; font-weight: 800; }
.toggle-chip.active { color: #06211f; background: var(--accent); }
.highlight-palette { display: flex; flex-wrap: wrap; gap: 8px; }
.highlight-dot { width: 28px; height: 28px; border-radius: 999px; border: 2px solid transparent; }
.highlight-dot.yellow { background: #FBBF24; }
.highlight-dot.green { background: #22C55E; }
.highlight-dot.blue { background: #38BDF8; }
.highlight-dot.rose { background: #FB7185; }
.highlight-dot.active { border-color: var(--text-primary); box-shadow: 0 0 0 3px color-mix(in srgb, var(--text-primary) 10%, transparent); }
.notes-box { display: grid; gap: 8px; }
.notes-box label { color: var(--text-muted); font-size: 11px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.notes-box textarea { width: 100%; min-height: 116px; resize: vertical; padding: 12px; border: 1px solid var(--border-subtle); border-radius: 14px; color: var(--text-primary); background: var(--surface-2); line-height: 1.5; }

/* Exam results */
.exam-banner-card { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 18px 22px; margin-bottom: 18px; }
.exam-results-card { padding: clamp(20px, 3vw, 30px); display: grid; gap: 22px; }
.exam-results-head h1 { font-size: clamp(28px, 4vw, 42px); margin-top: 6px; }
.exam-results-head p { margin-top: 8px; max-width: 700px; }
.exam-results-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.exam-results-metrics { display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 12px; }
.exam-results-metrics div { grid-template-columns: 36px minmax(0,1fr); align-items: center; }
.exam-results-metrics div strong { grid-column: 2; }
.exam-results-grid { display: grid; grid-template-columns: 360px minmax(0,1fr); gap: 14px; align-items: start; }
.exam-results-panel { padding: 16px; border: 1px solid var(--border-subtle); border-radius: 18px; background: var(--surface-2); display: grid; gap: 12px; }
.results-breakdown-list, .results-question-list { display: grid; gap: 10px; }
.results-breakdown-row, .results-question-row { display: grid; grid-template-columns: minmax(0,1fr) auto; gap: 12px; align-items: center; padding: 12px; border: 1px solid var(--border-subtle); border-radius: 14px; background: var(--surface-1); }
.results-breakdown-row small, .results-question-row small { display: block; margin-top: 3px; color: var(--text-muted); font-size: 12px; }
.results-breakdown-row span, .results-question-row > span { font-weight: 800; color: var(--accent); }
.results-question-row.correct { border-color: color-mix(in srgb, var(--success) 26%, var(--border-subtle)); }
.results-question-row.wrong { border-color: color-mix(in srgb, var(--danger) 28%, var(--border-subtle)); }
.results-question-row p { font-size: 13px; margin-top: 5px; }

/* 7. States already co-located with components */
/* 8. Motion */
@keyframes subtleFadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }
.page-shell, .home-dashboard-grid, .qbank-shell { animation: subtleFadeIn var(--duration-normal) var(--ease-standard); }

/* 9. Responsive */
@media (max-width: 1280px) {
  .branch-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .patient-strip { grid-template-columns: repeat(3, minmax(0,1fr)); }
  .patient-strip-item.wide { grid-column: span 2; }
}
@media (max-width: 1060px) {
  .top-shell-nav { grid-template-columns: minmax(180px,1fr) auto; }
  .nav-mode-switch { grid-row: 2; grid-column: 1 / -1; justify-self: stretch; justify-content: center; }
  .app-shell { padding-top: 134px; }
  .home-dashboard-grid { grid-template-columns: 1fr; }
  .dashboard-aside-card { order: 2; }
  .qbank-shell, .case-page-shell, .exam-results-grid { grid-template-columns: 1fr; }
  .qbank-side-column, .sidebar-layout { position: static; max-height: none; overflow: visible; padding-right: 0; }
  .question-panel { order: 0; }
  .tools-panel { order: 1; }
  .feedback-grid.duo, .feedback-grid.triad { grid-template-columns: 1fr; }
}
@media (max-width: 768px) {
  .page-shell { width: min(100% - 24px, 760px); padding-top: 16px; }
  .top-shell-nav { top: 8px; width: calc(100% - 16px); grid-template-columns: 1fr; gap: 10px; }
  .nav-brand { justify-content: center; }
  .nav-actions { justify-content: center; flex-wrap: wrap; }
  .nav-score-chip { display: none; }
  .app-shell { padding-top: 186px; }
  .hero-panel { padding: 20px; }
  .stat-grid, .mode-grid, .branch-grid, .exam-results-metrics { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .patient-strip { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .patient-strip-item.wide { grid-column: span 2; }
  .qbank-header-row, .question-panel-head, .panel-title-row, .section-title-row, .exam-results-head { grid-template-columns: 1fr; display: grid; }
  .qbank-actions, .exam-results-actions { justify-content: start; }
  .feedback-header-split { display: grid; }
}
@media (max-width: 560px) {
  .app-shell { padding-top: 194px; }
  .nav-actions .nav-cta { flex: 1 1 auto; }
  .stat-grid, .mode-grid, .branch-grid, .patient-strip, .exam-results-metrics, .compact-metric-grid, .tools-mini-stats { grid-template-columns: 1fr; }
  .patient-strip-item.wide { grid-column: auto; }
  .hero-actions, .exam-nav-actions { grid-template-columns: 1fr; display: grid; }
  .branch-card { min-height: auto; }
  .answer-option { grid-template-columns: 38px minmax(0,1fr) 24px; padding: 13px; }
  .answer-letter { width: 34px; height: 34px; }
  .accordion-trigger { grid-template-columns: 38px minmax(0, 1fr) 34px; gap: 10px; padding: 12px; }
  .accordion-prefix { width: 34px; height: 34px; }
  .media-frame { min-height: 180px; }
}
@media (max-width: 380px) {
  .page-shell { width: min(100% - 16px, 360px); }
  .btn, .primary-action, .secondary-action { width: 100%; }
  .segmented-control button { padding: 0 10px; font-size: 13px; }
  .case-hero-card, .case-narrative-card, .clinical-data-card, .investigation-section, .media-section, .question-panel, .tools-panel { padding: 16px; }
}

/* 10. Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* 11. Professional Q-bank refinement pass */
:root {
  --scroll-thumb: color-mix(in srgb, var(--text-muted) 38%, transparent);
  --scroll-thumb-hover: color-mix(in srgb, var(--accent) 42%, var(--text-muted));
  --scroll-track: color-mix(in srgb, var(--surface-2) 64%, transparent);
}
* {
  scrollbar-width: thin;
  scrollbar-color: var(--scroll-thumb) transparent;
}
*::-webkit-scrollbar { width: 8px; height: 8px; }
*::-webkit-scrollbar-track { background: transparent; border-radius: 999px; }
*::-webkit-scrollbar-thumb {
  min-height: 44px;
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
  background-color: var(--scroll-thumb);
}
*::-webkit-scrollbar-thumb:hover { background-color: var(--scroll-thumb-hover); }
body::-webkit-scrollbar-track, .table-wrap::-webkit-scrollbar-track,
.qbank-side-column::-webkit-scrollbar-track, .sidebar-layout::-webkit-scrollbar-track,
