}
.dashboard-aside-card { gap: 15px; }
.empty-state-mini { border-style: dashed; background: color-mix(in srgb, var(--surface-2) 72%, transparent); }

/* Branch/detail cards */
.section-title-row { align-items: end; }
.branch-card { min-height: 244px; padding: 17px; border-radius: 18px; }
.branch-card:hover { transform: none; box-shadow: var(--shadow-card); }
.branch-count, .difficulty-badge, .compact-status-pill, .feedback-badge, .tag {
