.vitals-grid {
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
}
.vital-card {
  grid-template-columns: 40px minmax(0,1fr);
  padding: 12px;
  border-radius: 15px;
}
.vital-copy span { font-size: 10px; }
.vital-copy strong { font-size: 17px; line-height: 1.2; overflow-wrap: break-word; }

/* Accordion: definitive fix for narrow-column physical exam bug */
.qbank-accordion-stack,
.investigation-stack {
  display: grid;
  gap: 10px;
}
.accordion-item {
  overflow: hidden;
  border-radius: 18px;
}
.accordion-trigger {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 36px;
  width: 100%;
  gap: 12px;
  align-items: start;
  padding: 14px;
}
.accordion-prefix {
  width: 38px;
  height: 38px;
  border-radius: 13px;
  font-size: 15px;
}
.accordion-copy {
  min-width: 0;
  display: grid;
  gap: 5px;
}
.accordion-title-row {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.accordion-title-row strong {
  min-width: 0;
  overflow-wrap: break-word;
}
.accordion-title-row em {
  flex: 0 0 auto;
  font-style: normal;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 800;
  padding: 4px 8px;
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-1) 82%, transparent);
}
.accordion-copy small {
  min-width: 0;
  width: 100%;
  max-width: 100%;
  line-height: 1.55;
  overflow-wrap: break-word;
  word-break: normal;
  white-space: normal;
}
.accordion-toggle {
  width: 34px;
  height: 34px;
  align-self: start;
}
.accordion-panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--duration-slow) var(--ease-standard);
}
.accordion-item.open .accordion-panel { grid-template-rows: 1fr; }
.accordion-panel-inner {
  overflow: hidden;
  min-width: 0;
  padding: 0 14px;
}
.accordion-item.open .accordion-panel-inner { padding-bottom: 14px; }
.detail-copy {
  width: 100%;
  min-width: 0;
  padding: 14px;
  line-height: 1.65;
  overflow-wrap: break-word;
  word-break: normal;
  white-space: normal;
}
.clean-list.dense li {
  overflow-wrap: break-word;
  line-height: 1.6;
}

/* Investigation cards and callouts */
.investigation-section { padding: 18px; }
.panel-title-row.compact h2 { margin-bottom: 0; }
.tag.quiet-tag { font-size: 11px; padding: 4px 8px; }
.clinical-callout {
  grid-template-columns: 34px minmax(0, 1fr);
  padding: 12px;
  border-radius: 14px;
  gap: 10px;
}
.clinical-callout strong { font-size: 14px; }
.clinical-callout p,
.clinical-callout span {
  line-height: 1.55;
  font-size: 13px;
}

/* Lab table + horizontal scrollbar */
.table-wrap,
.lab-table-wrap {
  overflow: auto;
  max-width: 100%;
  border-radius: 14px;
  scrollbar-gutter: stable;
}
.lab-table {
  width: 100%;
  min-width: 720px;
  table-layout: fixed;
}
.lab-table th:nth-child(1), .lab-table td:nth-child(1) { width: 22%; }
.lab-table th:nth-child(2), .lab-table td:nth-child(2) { width: 20%; }
.lab-table th:nth-child(3), .lab-table td:nth-child(3) { width: 20%; }
.lab-table th:nth-child(4), .lab-table td:nth-child(4) { width: 38%; }
.lab-table th,
.lab-table td {
  white-space: normal;
  overflow-wrap: break-word;
  word-break: normal;
  vertical-align: top;
}

/* Media card */
.media-section { padding: 18px; }
.media-card-head {
  margin-bottom: 12px;
}
.evidence-figure {
  border-radius: 18px;
}
.media-frame {
  padding: 10px;
  background: color-mix(in srgb, var(--surface-1) 70%, transparent);
}
.media-frame img {
  width: 100%;
  max-height: 520px;
  object-fit: contain;
  border-radius: 14px;
}
.media-zoom {
  top: 16px;
  right: 16px;
  width: 34px;
  height: 34px;
  border-radius: 12px;
  background: color-mix(in srgb, var(--surface-1) 70%, transparent);
  backdrop-filter: blur(12px);
  opacity: .82;
}
.media-zoom:hover { opacity: 1; }
.evidence-figure figcaption {
  padding: 12px 14px 14px;
  gap: 6px;
}
.media-caption-topline {
  gap: 8px;
  color: var(--text-muted);
  font-size: 12px;
}
.evidence-figure figcaption strong {
  font-size: 15px;
  line-height: 1.35;
}
.evidence-figure figcaption span:last-child {
  line-height: 1.55;
  font-size: 13px;
}

/* Question panel and answer cards */
.question-panel {
  padding: 18px;
}
.question-panel-head {
  gap: 12px;
  align-items: start;
}
.question-panel-head h2 {
  font-size: 22px;
  letter-spacing: -.035em;
}
.question-panel-head p {
  line-height: 1.5;
  color: var(--text-secondary);
}
.question-score-chip {
  min-width: 96px;
  padding: 8px 10px;
  border-radius: 14px;
}
.question-score-chip span { font-size: 10px; }
.question-score-chip strong { font-size: 13px; }
.option-grid {
  gap: 9px;
}
.answer-option {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) 24px;
  align-items: center;
  min-height: 66px;
  padding: 12px 14px;
  gap: 12px;
  border-radius: 15px;
  transform: none;
}
.answer-option:hover:not(:disabled) {
  transform: none;
}
.answer-letter {
  width: 36px;
  height: 36px;
  border-radius: 12px;
}
.answer-content {
  min-width: 0;
}
.answer-title {
  display: block;
  font-size: 15px;
  line-height: 1.45;
  overflow-wrap: break-word;
  word-break: normal;
}
.answer-subtitle {
  display: block;
  margin-top: 4px;
  font-size: 12px;
  line-height: 1.4;
}
.answer-option:disabled {
  opacity: .88;
  cursor: default;
}
.answer-option:not(.correct):not(.wrong):disabled {
  color: var(--text-secondary);
}
.quiz-actions .btn:disabled,
.btn:disabled {
  opacity: .62;
  filter: saturate(.9);
}

/* Tools panel */
.tools-panel {
  padding: 16px;
  max-height: calc(100vh - 118px);
  overflow: auto;
  scrollbar-gutter: stable;
}
.tools-panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}
.tools-panel-head h3 {
  font-size: 19px;
  margin: 0;
}
.panel-meta-muted {
  color: var(--text-muted);
  font-size: 12px;
  white-space: nowrap;
}
.tools-section {
  border-top: 1px solid var(--border-subtle);
  padding-top: 12px;
  margin-top: 12px;
}
.tool-row {
  display: grid;
  grid-template-columns: 36px minmax(0,1fr) auto;
  gap: 10px;
  align-items: center;
}
.tool-copy {
  display: grid;
  gap: 3px;
}
.tool-copy span,
.highlight-tool-head span {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.45;
}
.toggle-chip {
  min-height: 32px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 12px;
}
.highlight-tool-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}
.highlight-tool-head > div {
  display: grid;
  gap: 3px;
}
.text-reset-button {
  min-height: 30px;
  padding: 0 8px;
  border-radius: 10px;
}
.highlight-palette {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px;
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
  background: color-mix(in srgb, var(--surface-1) 72%, transparent);
}
.highlight-dot {
  width: 28px;
  height: 28px;
  border-radius: 999px;
  border: 2px solid color-mix(in srgb, var(--surface-1) 80%, transparent);
  box-shadow: 0 0 0 1px var(--border-subtle);
}
.highlight-dot.active {
  box-shadow: 0 0 0 2px var(--accent), 0 0 0 4px color-mix(in srgb, var(--accent) 10%, transparent);
}
.notes-tool label {
  display: block;
  margin-bottom: 8px;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.notes-tool textarea {
  width: 100%;
  min-height: 160px;
  padding: 12px 13px;
  border-radius: 14px;
  border: 1px solid var(--border-subtle);
  background: var(--surface-1);
  color: var(--text-primary);
  line-height: 1.55;
  resize: vertical;
}
.notes-tool textarea:focus {
  outline: none;
  border-color: var(--border-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 14%, transparent);
}

/* Layout: reduce sticky pain */
.qbank-side-column {
  top: 88px;
  max-height: calc(100vh - 102px);
  scrollbar-gutter: stable;
}
.qbank-shell {
  gap: 18px;
}

/* Responsive */
@media (max-width: 860px) {
  .home-dashboard-grid,
  .qbank-shell,
  .case-page-shell {
    grid-template-columns: 1fr;
  }
  .qbank-side-column {
    position: static;
    max-height: none;
    overflow: visible;
  }
  .tools-panel {
    max-height: none;
  }
  .sidebar-layout {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 860px) {
  .top-shell-nav {
    grid-template-columns: 1fr;
    gap: 10px;
  }
  .nav-actions {
    width: 100%;
    justify-content: space-between;
  }
  .stat-grid,
  .mode-grid,
  .summary-strip {
    grid-template-columns: 1fr 1fr;
  }
  .patient-strip-item.wide {
    grid-column: span 1;
  }
  .qbank-header-row,
  .question-panel-head {
    grid-template-columns: 1fr;
  }
  .qbank-actions {
    justify-content: flex-start;
  }
  .feedback-grid.duo,
  .feedback-grid.triad {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 560px) {
  .app-shell {
    padding: 12px;
  }
  .stat-grid,
  .mode-grid,
  .summary-strip,
  .vitals-grid,
  .tools-mini-stats {
    grid-template-columns: 1fr;
  }
  .answer-option {
    grid-template-columns: 38px minmax(0, 1fr) 22px;
    padding: 11px 12px;
  }
  .answer-letter {
    width: 34px;
    height: 34px;
  }
  .accordion-trigger {
    grid-template-columns: 40px minmax(0, 1fr) 32px;
    gap: 10px;
    padding: 12px;
  }
  .accordion-prefix {
    width: 34px;
    height: 34px;
  }
  .lab-table {
    min-width: 660px;
  }
}

/* === SENIOR PRODUCT UI REVISION: Q-bank polish layer === */
:root {
  --control-h: 38px;
  --control-radius: 13px;
  --hairline: 1px solid var(--border-subtle);
}

/* Header / TopNav: compact brand + unified action group */
.top-shell-nav {
  min-height: 62px;
  padding: 8px 10px;
  grid-template-columns: minmax(210px, 0.95fr) auto minmax(250px, auto);
  gap: 12px;
  border-radius: 18px;
}
.nav-brand {
  min-height: 44px;
  gap: 10px;
  padding: 0 4px;
  border-radius: 14px;
}
.nav-brand-mark {
  width: 40px;
  height: 40px;
  border-radius: 13px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 16%, transparent), color-mix(in srgb, var(--accent-blue) 8%, transparent));
}
.nav-brand-mark svg { width: 20px; height: 20px; stroke-width: 2; }
.brand-symbol { display: block; overflow: visible; vector-effect: non-scaling-stroke; }
.nav-brand-copy { gap: 0; }
.nav-brand strong { font-size: 15px; font-weight: 760; letter-spacing: -0.015em; }
.nav-brand small { font-size: 11.5px; line-height: 1.15; }
.segmented-control {
  min-height: 40px;
  padding: 3px;
  border-radius: 15px;
}
.segmented-control button {
  min-height: 32px;
  padding: 0 12px;
  border-radius: 11px;
  font-size: 13px;
  font-weight: 720;
}
.segmented-control button.active {
  background: color-mix(in srgb, var(--surface-elevated) 92%, var(--accent) 8%);
  box-shadow: 0 1px 1px rgba(0,0,0,.12), inset 0 0 0 1px color-mix(in srgb, var(--border-accent) 40%, transparent);
}
.nav-actions {
  min-height: 44px;
  gap: 4px;
  padding: 3px;
  border-radius: 16px;
  background: color-mix(in srgb, var(--surface-2) 72%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--text-primary) 5%, transparent);
}
.nav-score-chip {
  display: inline-grid;
  min-width: 56px;
  min-height: var(--control-h);
  place-content: center;
  text-align: center;
  padding: 0 8px;
}
.nav-score-chip span { font-size: 9.5px; line-height: 1; }
.nav-score-chip strong { margin-top: 2px; font-size: 14px; line-height: 1; }
.nav-actions .btn {
  min-height: var(--control-h);
  border-radius: var(--control-radius);
  font-size: 13px;
  font-weight: 740;
}
.nav-actions .btn svg { width: 16px; height: 16px; }
.nav-cta { padding-inline: 12px; box-shadow: none; }
.theme-toggle {
  width: 38px;
  min-width: 38px;
  height: 38px;
  background: transparent;
  border-color: transparent;
}
.theme-toggle:hover { background: var(--surface-3); border-color: var(--border-subtle); }

/* Home hero / CTA */
.hero-kicker {
  padding: 0;
  border: 0;
  background: transparent;
  text-transform: none;
  letter-spacing: .01em;
  font-size: 12px;
  font-weight: 650;
  color: var(--text-muted);
}
.hero-copy h1 {
  font-weight: 770;
  letter-spacing: -0.06em;
}
.hero-actions .btn {
  min-height: 44px;
  padding-inline: 17px;
  border-radius: 14px;
  font-size: 14px;
  font-weight: 740;
}
.hero-actions .btn svg { width: 17px; height: 17px; stroke-width: 2; }
.hero-actions .btn-secondary {
  background: color-mix(in srgb, var(--surface-2) 88%, transparent);
}

/* Dashboard metric cards */
.stat-card {
  min-height: 96px;
  align-items: start;
  grid-template-columns: 38px minmax(0, 1fr);
  padding: 13px;
  border-radius: 16px;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--text-primary) 4%, transparent);
}
.stat-card .icon-badge { width: 36px; height: 36px; border-radius: 12px; }
.stat-card .icon-badge svg { width: 17px; height: 17px; }
.stat-copy { align-self: stretch; display: grid; align-content: start; gap: 4px; }
.stat-copy span { font-size: 11px; font-weight: 740; letter-spacing: 0; text-transform: none; color: var(--text-muted); }
.stat-copy strong { margin-top: 2px; font-weight: 760; letter-spacing: -0.035em; }
.stat-copy small { line-height: 1.35; }

/* Mode cards: compact exam platform cards */
.mode-card {
  min-height: 154px;
  grid-template-rows: auto auto 1fr;
  padding: 14px;
  gap: 9px;
  border-radius: 17px;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--text-primary) 4%, transparent);
}
.mode-card.active {
  background: linear-gradient(180deg, color-mix(in srgb, var(--accent) 9%, var(--surface-2)), var(--surface-2));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 18%, transparent);
}
.mode-card-top .icon-badge { width: 38px; height: 38px; border-radius: 12px; }
.mode-selected-indicator {
  min-height: 24px;
  padding: 0 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 760;
  border: var(--hairline);
  background: color-mix(in srgb, var(--surface-1) 84%, transparent);
}
.mode-card-copy { gap: 5px; }
.mode-card-copy strong { font-size: 16px; letter-spacing: -0.015em; }
.mode-card-copy p { font-size: 13px; line-height: 1.48; }
.feature-chip-row { align-self: end; gap: 5px; }
.feature-chip-row span {
  min-height: 22px;
  padding: 2px 7px;
  font-size: 10.5px;
  font-weight: 700;
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-1) 72%, transparent);
  border: var(--hairline);
}

/* Session summary */
.dashboard-aside-card { padding: 16px; border-radius: 20px; }
.summary-strip { gap: 7px; }
.summary-strip div {
  padding: 9px 10px;
  border-radius: 13px;
  background: color-mix(in srgb, var(--surface-2) 66%, transparent);
}
.summary-strip span { font-size: 9.5px; }
.summary-strip strong { font-size: 15px; }
.summary-performance-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: -4px;
  padding: 11px 12px;
  border-radius: 15px;
  border: var(--hairline);
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 8%, var(--surface-2)), var(--surface-2));
}
.summary-performance-row span { color: var(--text-secondary); font-size: 13px; font-weight: 700; }
.summary-performance-row strong { font-size: 20px; line-height: 1; }
.empty-state-mini.refined-empty {
  border-radius: 16px;
  background: color-mix(in srgb, var(--surface-2) 64%, transparent);
  border: 1px dashed var(--border-medium);
}

/* Branch cards + action footers */
.branch-card {
  min-height: 232px;
  grid-template-rows: auto auto auto auto auto;
  gap: 11px;
  padding: 15px;
  border-radius: 18px;
}
.branch-card-head .icon-badge {
  width: 46px;
  height: 46px;
  border-radius: 14px;
}
.branch-card-head .icon-badge svg { width: 21px; height: 21px; stroke-width: 1.9; }
.branch-count {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  padding: 0 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-2) 80%, transparent);
  border: var(--hairline);
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 750;
}
.branch-card-body h3 { font-size: 17px; letter-spacing: -0.02em; }
.branch-card-body p { font-size: 13px; line-height: 1.52; }
.branch-progress {
  height: 5px;
  border-radius: 999px;
  overflow: hidden;
  background: color-mix(in srgb, var(--text-muted) 13%, transparent);
}
.branch-progress span { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, var(--accent), var(--accent-blue)); }
.branch-card-meta { justify-content: space-between; gap: 8px; }
.branch-card-footer,
.case-list-footer {
  min-height: 32px;
  justify-content: flex-start;
  width: fit-content;
  padding: 0 10px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent) 24%, transparent);
  color: var(--accent);
  font-size: 13px;
  font-weight: 760;
}
.branch-card-footer svg,
.case-list-footer svg { width: 15px; height: 15px; stroke-width: 2.1; }

/* Branch detail left panel */
.branch-back-button {
  display: inline-flex;
  width: fit-content;
  min-height: 34px;
  padding: 0 10px;
  gap: 7px;
  border-radius: 11px;
  font-size: 13px;
  background: transparent;
}
.case-list { scrollbar-gutter: stable; }
.case-list-item {
  min-height: auto;
  padding: 13px;
  gap: 8px;
  border-radius: 15px;
}
.case-list-topline { gap: 8px; }
.case-list-item strong { font-size: 14.5px; line-height: 1.32; }
.case-list-footer { margin-top: 3px; min-height: 30px; padding-inline: 9px; }

/* Case hero + patient strip */
.case-title-copy h1 {
  font-size: clamp(24px, 2.85vw, 36px);
  font-weight: 750;
  line-height: 1.11;
  letter-spacing: -0.045em;
}
.qbank-actions { display: inline-flex; flex-wrap: wrap; }
.case-hero-meta {
  min-height: 34px;
  padding-inline: 11px;
  font-size: 12.5px;
  font-weight: 760;
  border: var(--hairline);
  background: color-mix(in srgb, var(--surface-2) 78%, transparent);
}
.case-refresh-btn { min-height: 34px; border-radius: 12px; font-size: 13px; }
.patient-strip { grid-template-columns: repeat(3, minmax(155px, 1fr)); }
.patient-strip-item.wide { grid-column: span 2; }
.patient-strip-item { padding: 11px 12px; border-radius: 13px; }
.patient-strip-item span { text-transform: none; letter-spacing: .01em; font-size: 11px; font-weight: 720; }
.patient-strip-item strong { font-size: 14px; line-height: 1.42; }

/* Question panel */
.question-score-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  min-height: 30px;
  padding: 0 9px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-2) 78%, transparent);
  border: var(--hairline);
}
.question-score-chip span,
.question-score-chip strong {
  margin: 0;
  display: inline;
  font-size: 12px;
  line-height: 1;
  white-space: nowrap;
}
.question-score-chip span::after { content: "·"; margin-left: 6px; color: var(--text-faint); }
.answer-option { box-shadow: inset 0 1px 0 color-mix(in srgb, var(--text-primary) 3%, transparent); }
.answer-letter {
