.summary-risk-chip-row em {
  display: inline-flex;
  align-items: center;
  min-height: 27px;
  padding: 0 9px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--accent) 20%, var(--border-subtle));
  background: color-mix(in srgb, var(--accent) 7%, transparent);
  color: var(--text-secondary);
  font-style: normal;
  font-size: 12px;
  font-weight: 740;
  line-height: 1;
  max-width: 100%;
  overflow-wrap: break-word;
}

.refined-focus-callout {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  align-items: start;
  gap: 10px;
  padding: 12px 13px;
  border-radius: 17px;
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--border-subtle));
  background: linear-gradient(180deg, color-mix(in srgb, var(--accent) 6%, transparent), color-mix(in srgb, var(--surface-2) 88%, transparent));
  color: var(--accent);
}

.refined-focus-callout svg {
  margin-top: 1px;
  color: var(--accent);
}

.refined-focus-callout div { min-width: 0; }
.refined-focus-callout p { margin-top: 4px; color: var(--text-secondary); }

/* Sağ panel: çalışma araçları ve tanısal karar net ayrışır */
.right-workspace-shell {
  display: grid;
  gap: 14px;
  padding: 16px;
  border-radius: 24px;
  border: 1px solid color-mix(in srgb, var(--border-medium) 74%, transparent);
  background: color-mix(in srgb, var(--surface-1) 94%, transparent);
  box-shadow: var(--shadow-card);
}

.right-workspace-shell .tools-panel,
.right-workspace-shell .question-panel {
  padding: 0 !important;
  border: 0 !important;
  box-shadow: none !important;
  background: transparent !important;
  border-radius: 0 !important;
}

.clinical-tools-panel {
  display: grid;
  gap: 12px;
  min-width: 0;
}

.tools-panel-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 10px;
}

.tools-title-block span,
.panel-eyebrow {
  color: var(--accent);
  font-size: 10.5px;
  font-weight: 850;
  letter-spacing: .09em;
  text-transform: uppercase;
}

.tools-title-block strong {
  display: block;
  margin-top: 3px;
  color: var(--text-primary);
  font-size: 15px;
  line-height: 1.22;
  letter-spacing: -0.015em;
}

.panel-status-chip {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 9px;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  background: color-mix(in srgb, var(--surface-2) 82%, transparent);
  color: var(--text-muted);
  font-size: 11.5px;
  font-weight: 780;
  white-space: nowrap;
}

.tools-state-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.tool-state-card {
  min-width: 0;
  min-height: 58px;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 10px;
  border-radius: 17px;
  border: 1px solid var(--border-subtle);
  background: color-mix(in srgb, var(--surface-2) 80%, transparent);
  color: var(--text-primary);
  text-align: left;
  transition: border-color 160ms var(--ease-standard), background-color 160ms var(--ease-standard), transform 160ms var(--ease-standard);
}

.tool-state-card:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--accent) 28%, var(--border-subtle));
}

.tool-state-card.active {
  background: color-mix(in srgb, var(--accent) 9%, var(--surface-2));
  border-color: color-mix(in srgb, var(--accent) 28%, var(--border-subtle));
}

.tool-state-card.muted,
.tool-state-card:disabled {
  color: var(--text-muted);
  opacity: .78;
  cursor: default;
}

.tool-state-card .icon-badge { width: 32px; height: 32px; border-radius: 11px; }
.tool-state-card .icon-badge svg { width: 16px; height: 16px; }
.tool-state-card span { display: grid; gap: 2px; min-width: 0; }
.tool-state-card em { color: var(--text-muted); font-size: 11px; font-style: normal; font-weight: 760; }
.tool-state-card strong { color: var(--text-primary); font-size: 13px; overflow-wrap: break-word; }

.color-selector-card {
  display: grid;
  gap: 10px;
  padding: 11px;
  border-radius: 17px;
  border: 1px solid var(--border-subtle);
  background: color-mix(in srgb, var(--surface-2) 64%, transparent);
}

.color-selector-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.color-selector-head span { color: var(--text-primary); font-size: 13px; font-weight: 800; }
.color-selector-head small { color: var(--text-muted); font-size: 11.5px; }
.premium-color-row { display: flex; flex-wrap: wrap; align-items: center; gap: 9px; }

.premium-color-row .highlight-dot,
.quick-highlight-row .highlight-dot {
  width: 30px;
  height: 30px;
  border-radius: 999px;
  border: 2px solid color-mix(in srgb, var(--surface-1) 94%, transparent);
  box-shadow: 0 0 0 1px var(--border-subtle), inset 0 1px 1px rgba(255,255,255,.35);
  transition: box-shadow 160ms var(--ease-standard), transform 160ms var(--ease-standard);
}

.premium-color-row .highlight-dot.active,
.quick-highlight-row .highlight-dot.active {
  transform: translateY(-1px);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent), 0 0 0 1px color-mix(in srgb, var(--accent) 42%, transparent), inset 0 1px 1px rgba(255,255,255,.45);
}

.clinical-note-details {
  border: 1px solid var(--border-subtle);
  border-radius: 17px;
  background: color-mix(in srgb, var(--surface-2) 58%, transparent);
  overflow: clip;
}

.clinical-note-details summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 13px;
  cursor: pointer;
  list-style: none;
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 790;
}

.clinical-note-details summary::-webkit-details-marker { display: none; }
.clinical-note-details summary span { display: inline-flex; align-items: center; gap: 8px; min-width: 0; }
.clinical-note-details[open] summary > svg { transform: rotate(180deg); }
.clinical-note-body { display: grid; gap: 10px; padding: 0 13px 13px; }
.clinical-note-body textarea { width: 100%; min-height: 86px; padding: 11px; border-radius: 14px; border: 1px solid var(--border-subtle); background: var(--surface-1); color: var(--text-primary); resize: vertical; }

/* Soru alanı */
.diagnostic-decision-panel {
  display: grid;
  gap: 14px;
  padding-top: 15px !important;
  border-top: 1px solid color-mix(in srgb, var(--border-subtle) 82%, transparent) !important;
}

.diagnostic-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: start;
}

.diagnostic-head h2 {
  margin-top: 3px;
  font-size: 22px;
  line-height: 1.08;
  letter-spacing: -0.035em;
}

.diagnostic-head p {
  margin-top: 5px;
  color: var(--text-secondary);
  font-size: 13.5px;
  line-height: 1.48;
}

.compact-meta-pill {
  min-height: 34px;
  padding: 6px 10px;
  border-radius: 999px;
}
.compact-meta-pill span { font-size: 10.5px; }
.compact-meta-pill strong { font-size: 12px; }

/* Klinik destek kartı */
.expert-insight-card {
  display: grid;
  gap: 12px;
  padding: 14px;
  border-radius: 20px;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--border-subtle));
  background:
    radial-gradient(circle at 0% 0%, color-mix(in srgb, var(--accent) 12%, transparent), transparent 42%),
    color-mix(in srgb, var(--surface-2) 86%, transparent);
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.05);
}

.expert-insight-head {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
}

.expert-insight-head .icon-badge { width: 32px; height: 32px; border-radius: 11px; }
.expert-insight-head strong { display: block; font-size: 15px; letter-spacing: -0.015em; }
.expert-insight-head p { margin: 3px 0 0; color: var(--text-muted); font-size: 12.5px; line-height: 1.42; }

.expert-insight-section {
  min-width: 0;
  display: grid;
  gap: 7px;
  padding-top: 10px;
  border-top: 1px dashed color-mix(in srgb, var(--border-subtle) 82%, transparent);
}

.expert-insight-section span {
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 820;
  letter-spacing: -0.01em;
}

.expert-insight-section p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.58;
  overflow-wrap: break-word;
}

.expert-evidence-list {
  display: grid;
  gap: 7px;
}

.expert-evidence-list em {
  display: block;
  padding: 8px 10px;
  border-radius: 13px;
  border: 1px solid var(--border-subtle);
  background: color-mix(in srgb, var(--surface-1) 82%, transparent);
  color: var(--text-secondary);
  font-style: normal;
  font-size: 12.5px;
  line-height: 1.45;
  overflow-wrap: break-word;
}

.expert-insight-section.reasoning {
  padding: 11px 12px;
  border-top: 0;
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--border-subtle));
  background: color-mix(in srgb, var(--accent) 5%, var(--surface-2));
}

/* Fizik muayene accordion: tekrar azaltılmış, kompakt ve tam genişlik */
.clinical-accordion {
  border-radius: 18px;
  border-color: color-mix(in srgb, var(--border-subtle) 88%, transparent);
  background: color-mix(in srgb, var(--surface-2) 82%, transparent);
}

.clinical-accordion-trigger {
  grid-template-columns: 36px minmax(0, 1fr) 34px;
  gap: 12px;
  align-items: center;
  min-height: 64px;
  padding: 12px 13px;
}

.clinical-accordion .accordion-prefix {
  width: 34px;
  height: 34px;
  border-radius: 12px;
}

.clinical-accordion .accordion-title-row {
  align-items: center;
}

.clinical-accordion .accordion-title-row strong {
  font-size: 15px;
  line-height: 1.18;
}

.clinical-accordion .accordion-title-row em {
  font-size: 10px;
  padding: 3px 7px;
  border-radius: 999px;
}

.clinical-accordion .accordion-copy small {
  max-width: 100%;
  color: var(--text-muted);
  font-size: 12.5px;
  line-height: 1.42;
}

.clinical-accordion-body {
  min-width: 0;
  overflow: hidden;
  padding-left: 13px;
  padding-right: 13px;
}

.scientific-summary-block p,
.scientific-finding-list li,
.detail-copy {
  overflow-wrap: break-word;
  line-height: 1.62;
}

@media (max-width: 980px) {
  .structured-patient-summary-grid,
  .tools-state-grid {
    grid-template-columns: 1fr;
  }
  .diagnostic-head {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 620px) {
  .compact-summary-head,
  .patient-summary-head,
  .expert-insight-head,
  .refined-focus-callout {
    grid-template-columns: 1fr;
  }
  .clinical-accordion-trigger {
    grid-template-columns: 32px minmax(0, 1fr) 32px;
  }
}


/* ===== v13 safe clinical support refactor ===== */
.compact-tool-status-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
}

.muted-section-label {
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 820;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.clinical-tools-panel {
  gap: 12px;
}

.diagnostic-decision-panel {
  padding-top: 18px !important;
  margin-top: 2px;
}

.diagnostic-head h2 {
  margin-top: 0 !important;
}

.panel-eyebrow {
  display: none !important;
}

.safe-expert-card {
  border-color: color-mix(in srgb, var(--border-subtle) 78%, transparent);
  background:
    radial-gradient(circle at 0% 0%, color-mix(in srgb, var(--accent) 7%, transparent), transparent 44%),
    color-mix(in srgb, var(--surface-2) 90%, transparent);
}

.safe-expert-card .expert-insight-head p {
  max-width: 34rem;
}

.safe-expert-card .expert-insight-section span {
  font-size: 12px;
  color: var(--text-primary);
}

.neutral-evidence .expert-evidence-list {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.neutral-evidence .expert-evidence-list em {
  padding: 7px 9px;
  border-radius: 999px;
  text-align: center;
  background: color-mix(in srgb, var(--surface-1) 86%, transparent);
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.25;
}

.safe-reasoning {
  background: color-mix(in srgb, var(--accent) 3%, var(--surface-2)) !important;
  border-color: color-mix(in srgb, var(--border-subtle) 88%, transparent) !important;
}

.tool-state-card strong,
.tool-state-card em,
.color-selector-head small,
.clinical-note-details summary,
.diagnostic-head p,
.expert-insight-section p {
  overflow-wrap: break-word;
}

@media (max-width: 680px) {
  .neutral-evidence .expert-evidence-list {
    grid-template-columns: 1fr;
  }
}

/* ===== v14 microcopy audit: compact headings and lower visual noise ===== */
.panel-title-row.compact,
.media-card-head,
.section-title-row.stacked,
.bottom-case-browser-head,
.question-panel-head,
.refined-section-heading {
  margin-bottom: 12px !important;
}

.refined-section-heading h2,
.panel-title-row h2,
.media-card-head h2,
.section-title-row h2,
.bottom-case-browser-head h3,
.diagnostic-head h2 {
  margin-bottom: 0 !important;
}

.question-panel-head p,
.diagnostic-head p,
.media-card-head p,
.bottom-case-browser-head p,
.section-title-row p,
.refined-section-heading p,
.color-selector-head small,
.expert-insight-head p {
  display: none !important;
}

.home-metric-card {
  min-height: 72px !important;
  align-content: space-between;
}

.home-metric-card strong {
  margin-top: 2px;
}

.summary-v8-header {
  align-items: center;
}

.summary-v8-header h2 {
  margin-bottom: 0 !important;
}

.summary-v8-row small {
  margin-top: 1px;
}

.case-list-item {
  min-height: auto !important;
}

.horizontal-case-card {
  min-height: 136px !important;
}

.case-list-footer {
  margin-top: 4px;
}

.color-selector-card {
  gap: 10px !important;
}

.color-selector-head {
  margin-bottom: 0 !important;
}

.investigation-section .accordion-copy small {
  max-width: 16rem;
}

.media-section,
.investigation-section,
.clinical-data-card,
.bottom-case-browser {
  scroll-margin-top: 130px;
}

.evidence-figure figcaption strong,
.accordion-copy strong,
.summary-detail-card p,
.patient-summary-head p,
.detail-copy,
.scientific-summary-block p,
.scientific-finding-list li {
  overflow-wrap: break-word;
}

@media (max-width: 760px) {
  .home-hero-copy-v8 p {
    max-width: 100%;
  }

  .horizontal-case-card {
    min-height: 128px !important;
  }
}


/* ===== v15 typography and theme polish =====
   Scope: design tokens, typography, contrast, buttons, chips and card hierarchy.
   No structural layout changes. */
html,
body,
button,
input,
textarea,
select {
  font-family: var(--font-ui);
  font-feature-settings: "cv02" 1, "cv03" 1, "cv04" 1, "kern" 1;
}

html[data-theme="dark"],
.app-shell[data-theme="dark"] {
  --bg: #071115;
  --bg-soft: #0A1820;
  --surface-1: #0F1C25;
  --surface-2: #142532;
  --surface-3: #1A3040;
  --surface-elevated: #1D3445;
  --border-subtle: rgba(148, 163, 184, 0.18);
  --border-medium: rgba(148, 163, 184, 0.28);
  --border-accent: rgba(45, 212, 191, 0.30);
  --text-primary: #F6F8FB;
  --text-secondary: #C8D3E0;
  --text-muted: #A0AEC0;
  --text-faint: #7B8A9D;
  --accent: #2CCFC0;
  --accent-strong: #10B6A6;
  --accent-blue: #43BFF4;
  --warning: #E8A13A;
  --danger: #F05252;
  --success: #2EC66D;
  --info: #66A6F2;
  --shadow-card: 0 1px 2px rgba(0, 0, 0, 0.24), inset 0 1px 0 rgba(255,255,255,.025);
  --shadow-elevated: 0 16px 42px rgba(0, 0, 0, 0.24);
  --shadow-hover: 0 0 0 1px rgba(45, 212, 191, 0.22), 0 18px 44px rgba(0, 0, 0, 0.30);
}

html[data-theme="light"],
.app-shell[data-theme="light"] {
  --bg: #F5F8FA;
  --bg-soft: #EEF4F7;
  --surface-1: #FFFFFF;
  --surface-2: #F7FAFC;
  --surface-3: #EEF4F7;
  --surface-elevated: #FFFFFF;
  --border-subtle: #DDE6EE;
  --border-medium: #C8D4E0;
  --border-accent: rgba(15, 118, 110, 0.28);
  --text-primary: #111827;
  --text-secondary: #334155;
  --text-muted: #5F6F82;
  --text-faint: #8794A5;
  --accent: #0E8178;
  --accent-strong: #0B6B64;
  --accent-blue: #087DB5;
  --warning: #B87513;
  --danger: #C93434;
  --success: #168A47;
  --info: #2569D8;
  --shadow-card: 0 1px 2px rgba(15, 23, 42, 0.07), 0 1px 0 rgba(255,255,255,.65) inset;
  --shadow-elevated: 0 16px 36px rgba(15, 23, 42, 0.10);
  --shadow-hover: 0 12px 30px rgba(15, 23, 42, 0.12);
}

body {
  font-size: 15px;
  line-height: 1.55;
  letter-spacing: -0.006em;
}

h1, h2, h3, h4,
.nav-brand strong,
.case-title-copy h1,
.home-hero-copy-v8 h1,
.branch-header-text h2 {
  font-family: var(--font-ui);
  letter-spacing: -0.035em;
  color: var(--text-primary);
}

h1,
.case-title-copy h1,
.home-hero-copy-v8 h1 {
  font-weight: 760;
  line-height: 1.03;
}

h2,
.panel-title-row h2,
.refined-section-heading h2,
.question-panel-head h2,
.summary-v8-header h2 {
  font-weight: 720;
  line-height: 1.16;
}

h3,
.branch-card-body h3,
.bottom-case-browser-head h3,
.case-list-item strong {
  font-weight: 680;
  line-height: 1.22;
}

p,
.detail-copy,
.detail-block p,
.clinical-callout-copy p,
.summary-detail-card p,
.patient-summary-focus-strip p,
.stem-sentence,
.answer-title {
  color: var(--text-secondary);
  font-weight: 450;
  line-height: 1.62;
  overflow-wrap: break-word;
}

.case-title-copy p,
.home-hero-copy-v8 p,
.branch-card-body p,
.case-list-item p,
.media-caption-copy p,
.investigation-copy p {
  color: var(--text-secondary);
  font-weight: 450;
  line-height: 1.58;
}

small,
.meta,
.nav-brand small,
.summary-v8-item span,
.summary-detail-card span,
.patient-summary-focus-strip span,
.branch-card-meta span,
.case-list-meta-text,
.question-score-chip span,
.feedback-kicker {
  color: var(--text-muted);
  font-weight: 620;
  letter-spacing: .035em;
}

/* Technical data should feel precise without turning the full UI into mono. */
.nav-score-chip strong,
.question-score-chip strong,
.summary-v8-score strong,
.home-metric-card strong,
.stat-copy strong,
.vital-copy strong,
.lab-table td:nth-child(2),
.lab-table td:nth-child(3),
.investigation-table td:nth-child(2),
.investigation-table td:nth-child(3),
.mini-clinical-row em,
.leaderboard-score,
.answer-letter {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.015em;
}

/* Surfaces and card hierarchy */
.card-surface,
.home-hero-v8,
.session-summary-v8,
.branch-card,
.case-hero-card,
.patient-summary-card,
.case-narrative-card,
.clinical-data-card,
.media-section,
.investigation-section,
.question-panel,
.tools-panel,
.right-workspace-shell,
.bottom-case-browser {
  border-color: var(--border-subtle);
  box-shadow: var(--shadow-card);
}

.card-surface:hover,
.branch-card:hover,
.answer-option:hover:not(:disabled) {
  transition: border-color var(--duration-normal) var(--ease-standard),
    background-color var(--duration-normal) var(--ease-standard),
    box-shadow var(--duration-normal) var(--ease-standard),
    transform var(--duration-normal) var(--ease-standard);
}

/* Buttons */
.btn,
.primary-action,
.secondary-action,
.ghost-link {
  font-weight: 680;
  letter-spacing: -0.006em;
  gap: 8px;
  border-radius: 14px;
}

.btn svg,
.primary-action svg,
.secondary-action svg {
  width: 17px;
  height: 17px;
  stroke-width: 2;
}

.btn-primary,
.primary-action {
  color: #042523;
  background: linear-gradient(180deg, color-mix(in srgb, var(--accent) 96%, white 4%), var(--accent-strong));
  border-color: color-mix(in srgb, var(--accent) 58%, transparent);
  box-shadow: 0 8px 22px color-mix(in srgb, var(--accent) 18%, transparent);
}

.btn-primary:hover,
.primary-action:hover {
  box-shadow: 0 12px 28px color-mix(in srgb, var(--accent) 24%, transparent);
}

.btn-secondary,
.secondary-action,
.btn-ghost,
.ghost-link {
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--surface-2) 82%, transparent);
  border-color: var(--border-subtle);
}

.btn-secondary:hover,
.secondary-action:hover,
.btn-ghost:hover,
.ghost-link:hover {
  color: var(--text-primary);
  background: var(--surface-3);
  border-color: var(--border-medium);
}

button:disabled,
.btn:disabled,
.answer-option:disabled {
  color: color-mix(in srgb, var(--text-muted) 82%, transparent);
  opacity: .72;
}

/* Chips, badges, status pills */
.tag,
.difficulty-badge,
.branch-count,
.compact-status-pill,
.feedback-badge,
.feature-chip-row span,
.clinical-chips span,
.badge-row span,
.tool-state-chip,
.tool-chip,
.quick-note-chip {
  font-weight: 650;
  letter-spacing: .01em;
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--surface-2) 78%, transparent);
  border-color: var(--border-subtle);
}

.difficulty-badge.danger,
.difficulty-badge.critical,
.feedback-badge.danger {
  color: var(--danger);
  background: color-mix(in srgb, var(--danger) 8%, var(--surface-2));
  border-color: color-mix(in srgb, var(--danger) 26%, var(--border-subtle));
}

.difficulty-badge.warning,
.feedback-badge.warning {
  color: var(--warning);
  background: color-mix(in srgb, var(--warning) 8%, var(--surface-2));
  border-color: color-mix(in srgb, var(--warning) 26%, var(--border-subtle));
}

.difficulty-badge.success,
.feedback-badge.success {
  color: var(--success);
  background: color-mix(in srgb, var(--success) 8%, var(--surface-2));
  border-color: color-mix(in srgb, var(--success) 24%, var(--border-subtle));
}

.icon-badge {
  border-color: var(--border-subtle);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--text-primary) 5%, transparent);
}
.icon-badge-sm { width: 34px; height: 34px; border-radius: 11px; }
.icon-badge-md { width: 42px; height: 42px; border-radius: 14px; }
.icon-badge svg { stroke-width: 1.95; }
.icon-badge-accent {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, var(--surface-2));
  border-color: color-mix(in srgb, var(--accent) 28%, var(--border-subtle));
}

/* Patient summary and clinical cards */
.professional-patient-summary-card {
  background: linear-gradient(180deg, color-mix(in srgb, var(--surface-2) 94%, transparent), color-mix(in srgb, var(--surface-1) 96%, transparent));
  border-color: var(--border-subtle);
}

.patient-summary-head strong,
.refined-section-heading h2,
.structured-tutor-content > strong {
  font-weight: 700;
}

.summary-detail-card {
  background: color-mix(in srgb, var(--surface-1) 88%, var(--surface-2) 12%);
  border-color: color-mix(in srgb, var(--border-subtle) 88%, transparent);
}

.summary-detail-card span,
.patient-summary-focus-strip span,
.structured-tutor-content dt,
.quick-tools-head span {
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 650;
  letter-spacing: .045em;
}

.patient-summary-focus-strip,
.clinical-callout.info,
.structured-tutor-card {
  background: color-mix(in srgb, var(--accent) 6%, var(--surface-2));
  border-color: color-mix(in srgb, var(--accent) 18%, var(--border-subtle));
}

/* Accordion and examination */
.accordion-item,
.detail-copy,
.detail-block,
.vital-card,
.investigation-card,
.media-card {
  border-color: var(--border-subtle);
}

.accordion-trigger,
.accordion-toggle {
  color: var(--text-primary);
  font-weight: 650;
}

.vital-card {
  background: color-mix(in srgb, var(--surface-2) 86%, transparent);
}

.vital-copy span {
  color: var(--text-muted);
  font-weight: 650;
}
.vital-copy strong {
  color: var(--text-primary);
  font-weight: 600;
}

/* Right panel and Q-bank answer options */
.right-workspace-shell {
  background: linear-gradient(180deg, color-mix(in srgb, var(--surface-1) 96%, transparent), color-mix(in srgb, var(--surface-2) 62%, transparent));
}

.question-panel-head h2 {
  font-size: clamp(20px, 2vw, 23px);
  font-weight: 720;
}

.question-panel-head p {
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.52;
}

.question-score-chip {
  background: color-mix(in srgb, var(--surface-2) 80%, transparent);
  border-color: var(--border-subtle);
}

.answer-option {
  background: color-mix(in srgb, var(--surface-2) 84%, transparent);
  border-color: var(--border-subtle);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--text-primary) 3%, transparent);
}
.answer-option:hover:not(:disabled) {
  background: color-mix(in srgb, var(--surface-3) 88%, transparent);
  border-color: color-mix(in srgb, var(--accent) 30%, var(--border-subtle));
}
.answer-option.selected {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-2));
  border-color: color-mix(in srgb, var(--accent) 50%, var(--border-subtle));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 24%, transparent);
}
.answer-letter {
  color: var(--accent);
  font-weight: 700;
}
.answer-title {
  color: var(--text-primary);
  font-weight: 520;
  line-height: 1.38;
}

/* Tool controls */
.tool-chip,
.toggle-chip,
.text-reset-button {
  border-radius: 999px;
}
.toggle-chip.active,
.tool-chip.active {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-2));
  border-color: color-mix(in srgb, var(--accent) 28%, var(--border-subtle));
}
.highlight-dot {
  width: 27px;
  height: 27px;
  border: 2px solid color-mix(in srgb, var(--surface-1) 80%, transparent);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.18);
}
.highlight-dot.active {
  box-shadow: 0 0 0 2px var(--surface-1), 0 0 0 4px color-mix(in srgb, var(--accent) 82%, transparent);
}

/* Tables and technical rows */
.lab-table,
.investigation-table,
.compact-metric-grid strong,
.exam-results-metrics strong {
  font-variant-numeric: tabular-nums;
}
.lab-table th,
.investigation-table th {
  color: var(--text-muted);
  font-weight: 650;
}
.lab-table td,
.investigation-table td {
  color: var(--text-secondary);
}
.lab-table td:nth-child(2),
.investigation-table td:nth-child(2) {
  color: var(--text-primary);
  font-weight: 560;
}

/* Light theme surface tuning */
.app-shell[data-theme="light"] .card-surface,
html[data-theme="light"] .card-surface {
  background: linear-gradient(180deg, #FFFFFF, #FBFCFE);
}
.app-shell[data-theme="dark"] .card-surface,
html[data-theme="dark"] .card-surface {
  background: linear-gradient(180deg, color-mix(in srgb, var(--surface-1) 96%, transparent), color-mix(in srgb, var(--surface-1) 88%, black 12%));
}

@media (max-width: 720px) {
  body { font-size: 14.5px; }
  .case-title-copy h1,
  .home-hero-copy-v8 h1 { letter-spacing: -0.045em; }
  .btn,
  .primary-action,
  .secondary-action { font-size: 14px; }
}

/* ===== v16 product quality refactor: typography safety, spoiler-safe panels, compact Q-bank UI ===== */

/* Text rendering safety: keep natural Turkish word flow in headings, labels and flex/grid children.
   Do not use `anywhere` globally; in narrow cards it can make clinical text flow one letter per line. */
:where(h1,h2,h3,h4,p,span,strong,small,em,button,a,li,td,th,label,summary) {
  word-spacing: normal;
  word-break: normal;
  overflow-wrap: normal;
  hyphens: none;
}

:where(.case-title-copy,.case-title-copy h1,.branch-card-body,.answer-title,.accordion-copy,.summary-detail-card,.patient-summary-card,.question-panel,.right-workspace-shell,.media-section,.investigation-section) {
  min-width: 0;
}

:where(h1,h2,h3,.answer-title,.accordion-title-row strong,.branch-card-body h3) {
  letter-spacing: -0.025em;
  line-height: 1.12;
  text-wrap: balance;
  overflow-wrap: break-word;
  white-space: normal;
}

:where(p,.detail-copy,.scientific-finding-list li,.feedback-explanation,.patient-summary-head p,.summary-detail-card p) {
  line-height: 1.62;
  letter-spacing: 0;
  overflow-wrap: break-word;
}

/* Patient summary: compact, no repeated long narrative */
.clinical-summary-card {
  padding: 16px;
  gap: 12px;
}

.compact-summary-head {
  grid-template-columns: 34px minmax(0, 1fr);
  align-items: start;
  gap: 11px;
}

.compact-summary-head .icon-badge {
  width: 34px;
  height: 34px;
  border-radius: 11px;
}

.compact-summary-head strong {
  font-size: 12px;
  letter-spacing: .045em;
  font-weight: 720;
}

.compact-summary-head p {
  font-size: 14.5px;
  color: var(--text-secondary);
}

.structured-patient-summary-grid {
  gap: 10px;
}

.summary-detail-card {
  min-height: 0;
  padding: 12px 13px;
  gap: 7px;
}

.summary-detail-card span {
  font-size: 10.5px;
  letter-spacing: .055em;
  font-weight: 700;
}

.summary-risk-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.summary-risk-chip-row em {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 0 9px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--border-subtle) 82%, transparent);
  background: color-mix(in srgb, var(--surface-2) 80%, transparent);
  color: var(--text-secondary);
  font-style: normal;
  font-size: 12px;
  font-weight: 650;
}

.refined-focus-callout {
  padding: 12px 13px;
  gap: 10px;
  border-color: color-mix(in srgb, var(--accent) 18%, var(--border-subtle));
  background: color-mix(in srgb, var(--accent) 5%, var(--surface-1));
}

.refined-focus-callout svg {
  flex: 0 0 auto;
  color: var(--accent);
}

.refined-focus-callout span {
  font-size: 10.5px;
  letter-spacing: .055em;
  font-weight: 720;
}

.refined-focus-callout p {
  font-size: 14px;
  line-height: 1.55;
}

/* Story is now narrative-only; avoid duplicate risk chips */
.professional-story-card .clinical-chips {
  display: none;
}

/* Right panel: shorter study mode, clean exam mode */
.professional-right-column {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--text-muted) 25%, transparent) transparent;
}

.right-workspace-shell {
  padding: 13px;
  gap: 12px;
  max-height: calc(100vh - 112px);
  overflow: auto;
  scrollbar-width: thin;
}

.tools-state-grid {
  gap: 8px;
}

.tool-state-card {
  min-height: 52px;
  padding: 9px 10px;
}

.tool-state-card em {
  letter-spacing: .02em;
  font-size: 11px;
}

.tool-state-card strong {
  font-size: 13px;
}

.color-selector-card {
  padding: 10px 11px;
}

.premium-color-row {
  gap: 10px;
}

.highlight-dot {
  width: 28px;
  height: 28px;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.22);
}

.highlight-dot.active {
  outline: 2px solid color-mix(in srgb, var(--accent) 52%, transparent);
  outline-offset: 3px;
  transform: none;
}

.clinical-note-details summary {
  min-height: 42px;
}

.safe-expert-card {
  padding: 13px;
  gap: 10px;
}

.expert-insight-head strong {
  font-size: 14px;
  font-weight: 720;
}

.expert-insight-section {
  padding: 10px 11px;
  border-radius: 14px;
}

.expert-insight-section span {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .04em;
}

.expert-insight-section p {
  margin: 4px 0 0;
  font-size: 13px;
  line-height: 1.5;
}

.expert-evidence-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.expert-evidence-list em {
  min-height: 24px;
  padding: 0 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-2) 84%, transparent);
  border: 1px solid var(--border-subtle);
  font-style: normal;
  font-size: 12px;
}

/* Diagnosis panel */
.diagnostic-head h2 {
  font-size: 18px;
  letter-spacing: -0.015em;
}

.compact-meta-pill {
  min-width: 70px;
  padding: 8px 10px;
}

.answer-option {
  min-width: 0;
}

.answer-title {
  font-weight: 640;
  line-height: 1.4;
}

.feedback-explanation-panel {
  margin-top: 12px;
  padding: 14px;
}

.feedback-explanation-panel h4 {
  margin-bottom: 7px;
}

/* Examination: objective data first, interpretation is opt-in */
.clinical-accordion-trigger {
  min-width: 0;
}

.accordion-copy,
.accordion-title-row {
  min-width: 0;
}

.accordion-title-row {
  gap: 8px;
}

.accordion-title-row strong {
  font-size: 15.5px;
}

.accordion-title-row em {
  flex: 0 0 auto;
  white-space: nowrap;
  font-size: 10.5px;
  font-weight: 650;
}

.neutral-disclosure {
  margin-top: 12px;
}

.neutral-disclosure summary,
.investigation-disclosure summary,
.media-disclosure summary {
  font-size: 13px;
  font-weight: 680;
}

.scientific-finding-list li {
  color: var(--text-secondary);
}

/* Branch cards: faster scan */
.branch-card {
  min-height: 226px;
  gap: 12px;
}

.branch-card-body p {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  line-height: 1.45;
}

.branch-card-footer span {
  font-size: 13px;
  font-weight: 700;
}

/* Media evidence: stronger medical asset card */
.media-section {
  padding: 18px;
}

.media-frame {
  min-height: clamp(240px, 36vw, 430px);
}

.media-frame img {
  max-height: 560px;
  object-fit: contain;
}

.media-zoom {
  width: 40px;
  height: 40px;
  border-radius: 14px;
  background: color-mix(in srgb, var(--surface-1) 88%, transparent);
  border: 1px solid color-mix(in srgb, var(--border-subtle) 88%, transparent);
  backdrop-filter: blur(10px);
}

.media-caption-topline {
  gap: 8px;
}

.media-caption-topline .tag {
  font-size: 11px;
  font-weight: 700;
}

.evidence-figure figcaption strong {
  font-size: 14px;
  font-weight: 680;
  line-height: 1.45;
}

/* Lab / investigation */
.lab-table {
  table-layout: fixed;
}

.lab-table th,
.lab-table td {
  overflow-wrap: break-word;
  line-height: 1.45;
}

.lab-table td:nth-child(2),
.lab-table td:nth-child(3),
.compact-meta-pill strong,
.nav-score-chip strong {
  font-family: var(--font-mono, "JetBrains Mono", "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, monospace);
}

/* Responsive QA */
@media (max-width: 1024px) {
  .right-workspace-shell {
    max-height: none;
    overflow: visible;
  }

  .professional-qbank-shell {
    grid-template-columns: 1fr !important;
  }
}

@media (max-width: 768px) {
  .case-section-nav {
    overflow-x: auto;
    grid-template-columns: repeat(4, max-content);
    scrollbar-width: none;
  }

  .section-nav-btn {
    white-space: nowrap;
    min-width: 96px;
  }

  .structured-patient-summary-grid {
    grid-template-columns: 1fr !important;
  }

  .case-title-copy h1 {
    font-size: clamp(28px, 9vw, 40px);
    line-height: 1.12;
  }

  .lab-table-wrap {
    overflow-x: auto;
    scrollbar-width: thin;
  }

  .lab-table {
    min-width: 680px;
  }
}

@media (max-width: 420px) {
  .page-shell {
    width: min(100% - 14px, 100%);
  }

  .professional-case-hero,
  .clinical-summary-card,
  .question-panel,
  .right-workspace-shell,
  .media-section,
  .investigation-section,
  .clinical-data-card {
    border-radius: 18px !important;
  }

  .patient-summary-head {
    grid-template-columns: 1fr;
  }

  .tools-state-grid,
  .quick-tools-actions {
    grid-template-columns: 1fr;
  }
}

/* ===== v18 Interactive Investigation Ordering Module ===== */

.investigation-order-section {
  display: grid;
  gap: 16px;
  padding: 18px;
}

.investigation-order-head {
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.investigation-order-head h2 {
  font-size: 20px;
  line-height: 1.18;
  letter-spacing: -0.02em;
}

.investigation-order-head p {
  margin-top: 5px;
  max-width: 680px;
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.5;
}

.ordered-count-chip {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  padding: 0 12px;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  background: color-mix(in srgb, var(--surface-2) 84%, transparent);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 700;
}

.investigation-option-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.investigation-option-card {
  position: relative;
  min-width: 0;
  min-height: 76px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  padding: 12px;
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--border-subtle) 88%, transparent);
  background: color-mix(in srgb, var(--surface-1) 94%, transparent);
  color: var(--text-primary);
  text-align: left;
  transition:
    border-color 160ms var(--ease-standard),
    background-color 160ms var(--ease-standard),
    transform 160ms var(--ease-standard),
    box-shadow 160ms var(--ease-standard);
}

.investigation-option-card:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--accent) 24%, var(--border-subtle));
  background: color-mix(in srgb, var(--accent) 4%, var(--surface-1));
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.06);
}

.investigation-option-card.selected {
  border-color: color-mix(in srgb, var(--success) 30%, var(--border-subtle));
  background: color-mix(in srgb, var(--success) 6%, var(--surface-1));
}

.investigation-option-card:disabled {
  cursor: default;
}

.investigation-option-copy {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.investigation-option-copy strong {
  min-width: 0;
  font-size: 14px;
  font-weight: 700;
  line-height: 1.25;
  overflow-wrap: break-word;
}

.investigation-option-copy em {
  color: var(--text-muted);
  font-size: 11px;
  font-style: normal;
  font-weight: 650;
  letter-spacing: .04em;
  text-transform: uppercase;
}

.investigation-option-state {
  flex: 0 0 auto;
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  padding: 0 9px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-2) 86%, transparent);
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.investigation-option-card.selected .investigation-option-state {
  color: var(--success);
  background: color-mix(in srgb, var(--success) 10%, transparent);
}

.order-inline-feedback {
  grid-column: 1 / -1;
  margin-top: -2px;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.35;
}

.ordered-results-panel {
  display: grid;
  gap: 12px;
  padding-top: 4px;
}

.ordered-results-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.ordered-results-head h3 {
  margin: 0;
  font-size: 17px;
  font-weight: 720;
  letter-spacing: -0.015em;
}

.ordered-results-note {
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.35;
}

.ordered-empty-state,
.media-order-empty {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  padding: 16px;
  border-radius: 18px;
  border: 1px dashed color-mix(in srgb, var(--border-subtle) 86%, transparent);
  background: color-mix(in srgb, var(--surface-2) 46%, transparent);
}

.ordered-empty-state strong,
.media-order-empty strong {
  display: block;
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 700;
}

.ordered-empty-state p,
.media-order-empty p {
  margin: 4px 0 0;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.45;
}

.ordered-result-stack {
  display: grid;
  gap: 12px;
}

.ordered-result-card {
  min-width: 0;
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--border-subtle) 88%, transparent);
  background: color-mix(in srgb, var(--surface-1) 96%, transparent);
  overflow: hidden;
}

.ordered-result-head {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  padding: 13px 14px;
  border-bottom: 1px solid color-mix(in srgb, var(--border-subtle) 82%, transparent);
  background: color-mix(in srgb, var(--surface-2) 52%, transparent);
}

.ordered-result-index {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  color: var(--accent);
  font-size: 12px;
  font-weight: 760;
}

.ordered-result-head strong {
  display: block;
  min-width: 0;
  font-size: 14.5px;
  line-height: 1.3;
  overflow-wrap: break-word;
}

.ordered-result-head small {
  display: block;
  margin-top: 3px;
  color: var(--text-muted);
  font-size: 11.5px;
  line-height: 1.25;
}

.order-priority-chip {
  min-height: 26px;
  display: inline-flex;
  align-items: center;
  padding: 0 9px;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--surface-1) 86%, transparent);
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.order-priority-chip.success { color: var(--success); background: color-mix(in srgb, var(--success) 8%, transparent); border-color: color-mix(in srgb, var(--success) 20%, transparent); }
.order-priority-chip.warning { color: var(--warning); background: color-mix(in srgb, var(--warning) 8%, transparent); border-color: color-mix(in srgb, var(--warning) 20%, transparent); }
.order-priority-chip.blue { color: var(--accent-blue); background: color-mix(in srgb, var(--accent-blue) 8%, transparent); border-color: color-mix(in srgb, var(--accent-blue) 20%, transparent); }
.order-priority-chip.slate { color: var(--text-muted); }

.ordered-result-body {
  display: grid;
  gap: 12px;
  padding: 14px;
}

.ordered-result-summary,
.ordered-result-empty {
  margin: 0;
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.58;
}

.ordered-result-table-wrap {
  margin-top: 0;
}

.ordered-result-table th,
.ordered-result-table td {
  white-space: normal;
  overflow-wrap: break-word;
}

.ordered-image-grid {
  display: grid;
  gap: 12px;
}

.ordered-image-card {
  margin: 0;
  overflow: hidden;
  border-radius: 16px;
  border: 1px solid var(--border-subtle);
  background: var(--surface-2);
}

.ordered-image-frame {
  position: relative;
  display: grid;
  place-items: center;
  min-height: clamp(220px, 34vw, 420px);
  background: color-mix(in srgb, var(--surface-2) 84%, black 3%);
}

.ordered-image-frame img {
  max-width: 100%;
  max-height: 520px;
  object-fit: contain;
  display: block;
}

.ordered-image-frame a {
  position: absolute;
  right: 12px;
  top: 12px;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  border: 1px solid var(--border-subtle);
  background: color-mix(in srgb, var(--surface-1) 88%, transparent);
  color: var(--text-primary);
  backdrop-filter: blur(10px);
}

.ordered-image-card figcaption {
  display: grid;
  gap: 3px;
  padding: 11px 12px;
}

.ordered-image-card figcaption strong {
  font-size: 13.5px;
  line-height: 1.35;
}

.ordered-image-card figcaption span {
  color: var(--text-muted);
  font-size: 11.5px;
}

.preanswer-investigation-nudge {
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--accent) 16%, var(--border-subtle));
  background: color-mix(in srgb, var(--accent) 5%, transparent);
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.45;
}

.investigation-strategy-panel {
  display: grid;
  gap: 12px;
}

.investigation-review-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.investigation-review-grid div {
  min-width: 0;
  padding: 10px;
  border-radius: 14px;
  border: 1px solid var(--border-subtle);
  background: color-mix(in srgb, var(--surface-2) 74%, transparent);
}

.investigation-review-grid span {
  display: block;
  color: var(--text-muted);
  font-size: 10.5px;
  font-weight: 720;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.investigation-review-grid strong {
  display: block;
  margin-top: 4px;
  font-size: 18px;
  font-family: var(--font-mono, "JetBrains Mono", "IBM Plex Mono", ui-monospace, monospace);
}

.investigation-strategy-panel p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.58;
}

@media (max-width: 1180px) {
  .investigation-option-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .investigation-option-grid,
  .investigation-review-grid {
    grid-template-columns: 1fr;
  }

  .investigation-order-head,
  .ordered-results-head {
    align-items: flex-start;
    flex-direction: column;
  }

  .ordered-result-head {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .order-priority-chip {
    grid-column: 2;
    width: fit-content;
  }

  .investigation-option-card {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .investigation-option-state {
    grid-column: 2;
    width: fit-content;
  }
}

@media (max-width: 420px) {
  .investigation-order-section {
    padding: 14px;
  }

  .ordered-result-body {
    padding: 12px;
  }

  .ordered-image-frame {
    min-height: 220px;
  }
}

/* ===== v19 clinical test ordering refinement ===== */
.order-priority-chip.violet {
  color: var(--accent-violet, #7c3aed);
  background: color-mix(in srgb, var(--accent-violet, #7c3aed) 8%, transparent);
  border-color: color-mix(in srgb, var(--accent-violet, #7c3aed) 20%, transparent);
}

.order-inline-feedback.violet {
  color: var(--text-secondary);
}

.investigation-order-head h2::after {
  content: '';
}

.investigation-option-card .order-inline-feedback {
  font-weight: 560;
}

.ordered-result-empty {
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px dashed color-mix(in srgb, var(--border-subtle) 84%, transparent);
  background: color-mix(in srgb, var(--surface-2) 52%, transparent);
}

.investigation-strategy-panel h4 {
  line-height: 1.25;
}

/* ===== v21 premium post-answer feedback panel ===== */
.answer-feedback-panel.feedback {
  display: grid;
  gap: 16px;
  padding: 14px;
  border-radius: 22px;
  border: 1px solid var(--border-subtle);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--surface-elevated) 96%, transparent), var(--surface-2)),
    radial-gradient(circle at top left, color-mix(in srgb, var(--accent) 10%, transparent), transparent 42%);
  box-shadow: var(--shadow-elevated);
  overflow: hidden;
}

.answer-feedback-panel.success {
  border-color: color-mix(in srgb, var(--success) 24%, var(--border-subtle));
}

.answer-feedback-panel.danger {
  border-color: color-mix(in srgb, var(--danger) 24%, var(--border-subtle));
}

.answer-feedback-summary {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 14px;
  align-items: start;
  padding: 16px;
  border-radius: 18px;
  border: 1px solid var(--border-subtle);
  background: color-mix(in srgb, var(--surface-1) 78%, transparent);
  position: relative;
}

.answer-feedback-summary.success {
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--success) 12%, var(--surface-1)), color-mix(in srgb, var(--surface-1) 86%, transparent));
  border-color: color-mix(in srgb, var(--success) 28%, var(--border-subtle));
}

.answer-feedback-summary.danger {
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--danger) 11%, var(--surface-1)), color-mix(in srgb, var(--surface-1) 86%, transparent));
  border-color: color-mix(in srgb, var(--danger) 28%, var(--border-subtle));
}

.answer-feedback-status-icon {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 14px;
  background: var(--surface-2);
  border: 1px solid var(--border-subtle);
  color: var(--text-secondary);
}

.answer-feedback-summary.success .answer-feedback-status-icon { color: var(--success); }
.answer-feedback-summary.danger .answer-feedback-status-icon { color: var(--danger); }
.answer-feedback-status-icon svg { width: 23px; height: 23px; }

.answer-feedback-summary-copy {
  display: grid;
  gap: 5px;
}

.feedback-status-pill {
  width: fit-content;
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 4px 9px;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.feedback-status-pill.success {
  color: var(--success);
  background: color-mix(in srgb, var(--success) 10%, transparent);
  border-color: color-mix(in srgb, var(--success) 28%, transparent);
}

.feedback-status-pill.danger {
  color: var(--danger);
  background: color-mix(in srgb, var(--danger) 10%, transparent);
  border-color: color-mix(in srgb, var(--danger) 28%, transparent);
}

.answer-feedback-summary h3 {
  margin: 0;
  color: var(--text-primary);
  font-size: clamp(17px, 2.2vw, 20px);
  line-height: 1.2;
  letter-spacing: -.025em;
}

.answer-feedback-summary p {
  margin: 0;
  color: var(--text-primary);
  font-size: 15.5px;
  font-weight: 740;
  line-height: 1.42;
  overflow-wrap: break-word;
}

.answer-feedback-summary small {
  color: var(--text-muted);
  font-size: 12.5px;
  line-height: 1.35;
}

.answer-feedback-meta-row {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding-top: 2px;
}

.answer-feedback-meta-row span {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 5px 9px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-2) 78%, transparent);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
}

.answer-feedback-grid {
  display: grid;
  gap: 12px;
}

.feedback-card {
  display: grid;
  gap: 12px;
  padding: 14px;
  border-radius: 17px;
  border: 1px solid var(--border-subtle);
  background: color-mix(in srgb, var(--surface-1) 72%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--text-primary) 3%, transparent);
}

.feedback-card-head {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
}

.feedback-card-head .icon-badge {
  width: 34px;
  height: 34px;
  border-radius: 12px;
}

.feedback-card-head .icon-badge svg {
  width: 17px;
  height: 17px;
}

.feedback-card-head span {
  display: block;
  color: var(--text-muted);
  font-size: 11.5px;
  font-weight: 790;
  letter-spacing: .075em;
  text-transform: uppercase;
  line-height: 1.2;
}

.feedback-card-head h4 {
  margin: 2px 0 0;
  color: var(--text-primary);
  font-size: 16px;
  line-height: 1.25;
  letter-spacing: -.015em;
}

.diagnosis-name-card {
  display: grid;
  gap: 6px;
  padding: 13px;
  border-radius: 15px;
  border: 1px solid color-mix(in srgb, var(--success) 18%, var(--border-subtle));
  background: color-mix(in srgb, var(--success) 7%, var(--surface-2));
}

.diagnosis-name-card strong {
  color: var(--text-primary);
  font-size: 16px;
  line-height: 1.35;
  overflow-wrap: break-word;
}

.diagnosis-name-card span {
  color: var(--text-muted);
  font-size: 12.5px;
  line-height: 1.4;
}

.feedback-body-copy {
  margin: 0;
  color: var(--text-secondary);
  font-size: 14.5px;
  line-height: 1.65;
  text-wrap: pretty;
}

.evidence-chain-box {
  display: grid;
  gap: 9px;
  padding: 12px;
  border-radius: 15px;
  background: var(--surface-2);
  border: 1px solid var(--border-subtle);
}

.evidence-chain-box > span {
  color: var(--accent-blue);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.evidence-chain-box ul,
.comparison-point-list {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.evidence-chain-box li,
.comparison-point-list li {
  position: relative;
  padding-left: 18px;
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.55;
}

.evidence-chain-box li::before,
.comparison-point-list li::before {
  content: '';
  position: absolute;
  left: 0;
  top: .68em;
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent-blue) 72%, var(--surface-3));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent-blue) 10%, transparent);
}

.feedback-metric-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.feedback-metric-card {
  display: grid;
  gap: 5px;
  min-height: 70px;
  padding: 11px;
  border-radius: 14px;
  border: 1px solid var(--border-subtle);
  background: var(--surface-2);
}

.feedback-metric-card span {
  color: var(--text-muted);
  font-size: 11.5px;
  font-weight: 750;
  line-height: 1.2;
}

.feedback-metric-card strong {
  color: var(--text-primary);
  font-size: 20px;
  line-height: 1;
  letter-spacing: -.02em;
}

.feedback-metric-card.info { border-color: color-mix(in srgb, var(--accent-blue) 24%, var(--border-subtle)); }
.feedback-metric-card.success,
.feedback-metric-card.soft-success { border-color: color-mix(in srgb, var(--success) 22%, var(--border-subtle)); }
.feedback-metric-card.warning { border-color: color-mix(in srgb, var(--warning) 24%, var(--border-subtle)); }
.feedback-metric-card.success strong,
.feedback-metric-card.soft-success strong { color: var(--success); }
.feedback-metric-card.warning strong { color: var(--warning); }

.test-strategy-details {
  display: grid;
  gap: 9px;
}

.test-strategy-row {
  display: grid;
  gap: 5px;
  padding: 11px 12px;
  border-radius: 14px;
  border: 1px solid var(--border-subtle);
  background: var(--surface-2);
}

.test-strategy-row > span {
  color: var(--text-muted);
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.test-strategy-row p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.55;
}

.feedback-timeline-list {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.feedback-timeline-list li {
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr);
  gap: 9px;
  align-items: center;
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.35;
}

.feedback-timeline-list b {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 9px;
  background: color-mix(in srgb, var(--accent-blue) 10%, var(--surface-1));
  border: 1px solid color-mix(in srgb, var(--accent-blue) 22%, var(--border-subtle));
  color: var(--accent-blue);
  font-size: 12px;
}

.feedback-timeline-list em {
  font-style: normal;
  overflow-wrap: break-word;
}

.clinical-pearl-list {
  display: grid;
  gap: 8px;
}

.clinical-pearl-item {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 9px;
  align-items: start;
  padding: 10px;
  border-radius: 13px;
  background: var(--surface-2);
  border: 1px solid var(--border-subtle);
}

.clinical-pearl-item > span {
  width: 9px;
  height: 9px;
  margin-top: 7px;
  border-radius: 999px;
  background: var(--accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 11%, transparent);
}

.clinical-pearl-item p,
.management-action-item p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.55;
}

.differential-option-chip {
  width: fit-content;
  max-width: 100%;
  padding: 7px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--warning) 28%, var(--border-subtle));
  background: color-mix(in srgb, var(--warning) 9%, var(--surface-2));
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 760;
  line-height: 1.25;
  overflow-wrap: break-word;
}

.differential-comparison-card .comparison-point-list li::before {
  background: color-mix(in srgb, var(--warning) 76%, var(--surface-3));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--warning) 10%, transparent);
}

.management-step-card {
  border-color: color-mix(in srgb, var(--warning) 20%, var(--border-subtle));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--warning) 6%, var(--surface-1)), color-mix(in srgb, var(--surface-1) 84%, transparent));
}

.management-action-list {
  display: grid;
  gap: 8px;
}

.management-action-item {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  padding: 10px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--warning) 18%, var(--border-subtle));
  background: color-mix(in srgb, var(--surface-2) 85%, transparent);
}

.management-action-item b {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--warning) 12%, var(--surface-1));
  color: var(--warning);
  border: 1px solid color-mix(in srgb, var(--warning) 28%, transparent);
  font-size: 12px;
}

.answer-feedback-actions {
  padding-top: 2px;
}

.answer-feedback-actions .exam-nav-actions {
  margin-top: 0;
}

@media (max-width: 900px) {
  .feedback-metric-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .answer-feedback-panel.feedback {
    padding: 12px;
    border-radius: 18px;
  }

  .answer-feedback-summary {
    grid-template-columns: 38px minmax(0, 1fr);
    gap: 11px;
    padding: 13px;
    border-radius: 16px;
  }

  .answer-feedback-status-icon {
    width: 38px;
    height: 38px;
    border-radius: 13px;
  }

  .answer-feedback-summary h3 {
    font-size: 17px;
  }

  .answer-feedback-summary p {
    font-size: 14.5px;
  }

  .feedback-card {
    padding: 12px;
    border-radius: 15px;
  }

  .feedback-card-head h4 {
    font-size: 15.5px;
  }

  .feedback-body-copy,
  .evidence-chain-box li,
  .comparison-point-list li,
  .test-strategy-row p,
  .clinical-pearl-item p,
  .management-action-item p {
    font-size: 13.5px;
    line-height: 1.55;
  }
}

@media (max-width: 460px) {
  .feedback-metric-grid {
    grid-template-columns: 1fr;
  }

  .answer-feedback-meta-row span {
    width: 100%;
    justify-content: center;
  }
}

/* ===== v23 incorrect-answer feedback quality pass ===== */
.answer-feedback-panel,
.answer-feedback-panel *,
.feedback-card,
.feedback-card *,
.diagnosis-comparison-card,
.diagnosis-comparison-card * {
