  padding: 14px;
  border-radius: 22px;
  overflow: hidden;
}

.answer-feedback-summary {
  grid-template-columns: 40px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  padding: 15px;
  overflow: hidden;
}

.answer-feedback-status-icon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  min-width: 40px;
  border-radius: 13px;
  align-self: start;
  flex: 0 0 auto;
