  hyphens: auto;
}

.answer-feedback-summary-copy p span,
.answer-feedback-summary-copy small span,
.differential-option-chip span {
  color: var(--text-muted);
  font-weight: 750;
}

.answer-feedback-summary h3 {
  font-size: clamp(16px, 2vw, 18px);
  line-height: 1.22;
}

.answer-feedback-summary p {
  font-size: 15px;
  line-height: 1.45;
  font-weight: 730;
}

.answer-feedback-summary small {
  display: block;
  font-size: 13px;
  line-height: 1.45;
  overflow-wrap: break-word;
