.refined-results-headline {
  align-items: flex-start;
}

.refined-results-headline h3 {
  margin-top: 3px;
  font-size: 16px;
  line-height: 1.25;
}

.refined-empty-state {
  padding: 17px;
  border-radius: 18px;
  align-items: center;
  background: color-mix(in srgb, var(--surface-1) 52%, transparent);
}

.refined-result-card {
  border-radius: 17px;
  background: color-mix(in srgb, var(--surface-1) 86%, transparent);
}

.refined-result-head {
  grid-template-columns: 28px minmax(0, 1fr) auto;
  padding: 12px 13px;
}

.refined-result-body {
  padding: 13px;
}

.order-priority-chip.compact {
