.order-card-shell {
  position: relative;
  display: grid;
  overflow: hidden;
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--border-subtle) 86%, transparent);
  background: color-mix(in srgb, var(--surface-1) 90%, transparent);
  transition:
    border-color var(--duration-fast) var(--ease-standard),
    background-color var(--duration-fast) var(--ease-standard),
    box-shadow var(--duration-fast) var(--ease-standard);
}

.order-card-shell:hover {
  border-color: color-mix(in srgb, var(--accent) 24%, var(--border-subtle));
  box-shadow: 0 10px 24px color-mix(in srgb, #020617 10%, transparent);
}

.order-card-shell.selected {
  border-color: color-mix(in srgb, var(--success) 30%, var(--border-subtle));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--success) 7%, var(--surface-1)), color-mix(in srgb, var(--surface-1) 92%, transparent));
}

.order-card-shell.priority-lowPriority,
.order-card-shell.priority-inappropriateEarly {
  background: color-mix(in srgb, var(--surface-2) 52%, transparent);
}

.smart-order-card.investigation-option-card {
  position: relative;
  width: 100%;
  min-height: 78px;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  padding: 12px;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  text-align: left;
}

.smart-order-card.investigation-option-card:hover:not(:disabled) {
  transform: none;
  background: color-mix(in srgb, var(--accent) 3.5%, transparent);
}

.smart-order-card .icon-badge {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  min-width: 38px;
  border-radius: 13px;
  align-self: center;
}

.smart-order-card .icon-badge svg {
  width: 18px;
  height: 18px;
  stroke-width: 1.95;
}

.smart-order-copy {
  min-width: 0;
  display: grid;
  gap: 5px;
}

.smart-order-copy strong {
  display: block;
  color: var(--text-primary);
  font-size: 14.5px;
  font-weight: 780;
  line-height: 1.32;
  letter-spacing: -.012em;
  overflow-wrap: break-word;
  word-break: normal;
}

.order-card-subline {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.order-card-subline em {
  color: var(--text-muted);
  font-style: normal;
  font-size: 11px;
  font-weight: 760;
  line-height: 1.2;
  letter-spacing: .055em;
  text-transform: uppercase;
}

.smart-order-actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
  min-width: max-content;
}

.order-score-badge,
.inline-score-pill {
  min-height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 8px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--border-subtle) 84%, transparent);
  background: color-mix(in srgb, var(--surface-2) 72%, transparent);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 820;
  line-height: 1;
  white-space: nowrap;
}

.order-score-badge.positive,
.inline-score-pill.positive {
  color: var(--success);
  border-color: color-mix(in srgb, var(--success) 22%, transparent);
  background: color-mix(in srgb, var(--success) 8%, transparent);
}

.order-score-badge.negative,
.inline-score-pill.negative {
  color: var(--warning);
  border-color: color-mix(in srgb, var(--warning) 24%, transparent);
  background: color-mix(in srgb, var(--warning) 8%, transparent);
}

.smart-order-state {
  min-height: 30px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 780;
  white-space: nowrap;
  transition:
    background-color var(--duration-fast) var(--ease-standard),
    border-color var(--duration-fast) var(--ease-standard),
    color var(--duration-fast) var(--ease-standard);
}

.smart-order-card.selected .smart-order-state {
  color: var(--success);
}

.score-change-indicator {
  position: absolute;
  right: 14px;
  top: 8px;
  z-index: 2;
  min-width: 34px;
  height: 26px;
  display: grid;
  place-items: center;
  padding: 0 8px;
  border-radius: 999px;
  color: #fff;
  font-size: 12px;
  font-weight: 850;
  box-shadow: 0 10px 22px rgba(2,6,23,.18);
  pointer-events: none;
  animation: score-pop-v25 .9s var(--ease-standard) forwards;
}

.score-change-indicator.positive { background: var(--success); }
.score-change-indicator.negative { background: var(--warning); }
.score-change-indicator.neutral { background: var(--text-muted); }

@keyframes score-pop-v25 {
  0% { transform: translateY(6px) scale(.88); opacity: 0; }
  18% { transform: translateY(-5px) scale(1); opacity: 1; }
  70% { transform: translateY(-9px) scale(1); opacity: 1; }
  100% { transform: translateY(-14px) scale(.96); opacity: 0; }
}

.inline-order-result {
  display: grid;
