/* --------------------------------------------------------------------------
   V97 — Branch transition overlay: real looped SVG/CSS motion
   -------------------------------------------------------------------------- */
.branch-route-overlay {
  --route-accent: var(--accent);
  position: fixed;
  inset: 0;
  z-index: 90;
  display: grid;
  place-items: center;
  pointer-events: none;
  background:
    radial-gradient(circle at 50% 50%, color-mix(in srgb, var(--route-accent) 18%, transparent), transparent 31%),
    color-mix(in srgb, var(--bg) 48%, transparent);
  backdrop-filter: blur(10px) saturate(1.05);
  -webkit-backdrop-filter: blur(10px) saturate(1.05);
  animation: branch-overlay-in 220ms var(--ease-standard) both;
}

.branch-route-overlay.reveal { animation: branch-overlay-out 280ms var(--ease-standard) both; }
.branch-route-overlay.branch-route-cardiovascular { --route-accent: #ff5a5f; }
.branch-route-overlay.branch-route-internal-medicine { --route-accent: var(--accent-blue); }
.branch-route-overlay.branch-route-neurology { --route-accent: var(--violet); }
.branch-route-overlay.branch-route-pediatrics { --route-accent: var(--success); }
.branch-route-overlay.branch-route-general-surgery { --route-accent: var(--warning); }
.branch-route-overlay.branch-route-pulmonology { --route-accent: var(--accent); }
.branch-route-overlay.branch-route-infectious-diseases { --route-accent: var(--lime); }
.branch-route-overlay.branch-route-orthopedics { --route-accent: color-mix(in srgb, var(--text-muted) 82%, #a7b2c3 18%); }

.branch-route-stage {
  display: grid;
  justify-items: center;
  gap: 16px;
  width: min(330px, calc(100vw - 40px));
  animation: branch-stage-pop 330ms var(--ease-emphasized) both;
}

.branch-route-hero {
  position: relative;
  width: 184px;
  height: 184px;
  display: grid;
  place-items: center;
}

.branch-route-hero::before,
.branch-route-hero::after {
  content: '';
  position: absolute;
  border-radius: 999px;
  pointer-events: none;
}

.branch-route-hero::before {
  inset: 6px;
  border: 1px dashed color-mix(in srgb, var(--route-accent) 32%, transparent);
  opacity: .55;
  animation: branch-orbit-spin 2600ms linear infinite;
}

.branch-route-hero::after {
  width: 8px;
  height: 8px;
  top: 18px;
  left: 50%;
  background: color-mix(in srgb, var(--route-accent) 82%, white 18%);
  box-shadow: 0 0 14px color-mix(in srgb, var(--route-accent) 72%, transparent);
  transform-origin: 0 74px;
  animation: branch-dot-orbit 1500ms linear infinite;
}

.branch-route-glow {
  position: absolute;
  inset: 18px;
  border-radius: 999px;
  background: radial-gradient(circle, color-mix(in srgb, var(--route-accent) 30%, white 4%), transparent 70%);
  filter: blur(22px);
  opacity: .72;
  animation: branch-glow-breathe 1100ms cubic-bezier(.22,1,.36,1) infinite;
}

.branch-route-ring {
  position: absolute;
  inset: 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--route-accent) 28%, transparent);
  background: color-mix(in srgb, var(--route-accent) 2%, transparent);
  opacity: .58;
  animation: branch-ring-expand 1150ms cubic-bezier(.22,1,.36,1) infinite;
}

.branch-route-ring.ring-two {
  inset: 28px;
  opacity: .78;
  animation-delay: 180ms;
}

.branch-route-orb {
  position: relative;
  display: grid;
  place-items: center;
  width: 122px;
  height: 122px;
  border-radius: 36px;
  color: var(--route-accent);
  border: 1px solid color-mix(in srgb, var(--route-accent) 34%, var(--border-subtle));
  background:
    radial-gradient(circle at 34% 22%, color-mix(in srgb, white 26%, transparent), transparent 28%),
    radial-gradient(circle at 50% 18%, color-mix(in srgb, var(--route-accent) 20%, transparent), transparent 56%),
    linear-gradient(180deg, color-mix(in srgb, var(--surface-elevated) 95%, transparent), color-mix(in srgb, var(--surface-1) 98%, transparent));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, white 34%, transparent),
    0 22px 60px color-mix(in srgb, var(--route-accent) 16%, rgba(2, 8, 16, 0.2));
  overflow: hidden;
  animation: branch-orb-enter 340ms var(--ease-emphasized) both, branch-orb-breathe 1100ms ease-in-out 340ms infinite;
}

.branch-route-orb::before,
.branch-route-orb::after {
  content: '';
  position: absolute;
  inset: 10px;
  border-radius: 28px;
  border: 1px solid color-mix(in srgb, var(--route-accent) 18%, transparent);
}
.branch-route-orb::after { inset: -10px; border-radius: 44px; opacity: .4; }

.branch-transition-visual,
.branch-transition-svg {
  position: relative;
  z-index: 1;
  display: block;
  transform-box: fill-box;
  transform-origin: center;
}

.branch-transition-visual {
  width: 70px;
  height: 70px;
  display: grid;
  place-items: center;
}

.branch-transition-shine {
  position: absolute;
  inset: 3px;
  border-radius: 18px;
  background: linear-gradient(115deg, transparent 0%, rgba(255,255,255,.0) 36%, color-mix(in srgb, white 40%, transparent) 46%, transparent 58%);
  transform: translateX(-120%);
  animation: icon-shine-sweep 1150ms ease-in-out infinite;
}

.branch-transition-icon {
  width: 70px;
  height: 70px;
  stroke-width: 1.95;
  filter: drop-shadow(0 0 8px color-mix(in srgb, var(--route-accent) 22%, transparent));
  transform-box: fill-box;
  transform-origin: center;
}

.branch-transition-svg { width: 82px; height: 82px; overflow: visible; }
.branch-transition-svg-cardiovascular { filter: drop-shadow(0 0 16px color-mix(in srgb, var(--route-accent) 28%, transparent)); }
.cardio-heart-outline { stroke-width: 3.1; opacity: .5; }
.cardio-heart-glow { stroke-width: 4.4; opacity: 0; filter: blur(2px); }
.cardio-heart-trace { stroke-width: 4.1; stroke-dasharray: 84; stroke-dashoffset: 84; filter: drop-shadow(0 0 8px color-mix(in srgb, var(--route-accent) 48%, transparent)); }

.route-icon-cardiovascular .branch-transition-svg-cardiovascular { animation: cardio-icon-beat 920ms cubic-bezier(.22,1,.36,1) infinite; }
.route-icon-cardiovascular .cardio-heart-trace { animation: cardio-trace-loop 920ms cubic-bezier(.22,1,.36,1) infinite; }
.route-icon-cardiovascular .cardio-heart-glow { animation: cardio-heart-glow-loop 920ms ease-in-out infinite; }
.route-icon-internal-medicine .branch-transition-visual { animation: flask-sway-loop 900ms cubic-bezier(.22,1,.36,1) infinite; transform-origin: 50% 70%; }
.route-icon-neurology .branch-transition-icon { animation: neuro-glow-loop 980ms cubic-bezier(.22,1,.36,1) infinite; }
.route-icon-pediatrics .branch-transition-icon { animation: pediatrics-bounce-loop 860ms cubic-bezier(.22,1,.36,1) infinite; }
.route-icon-general-surgery .branch-transition-icon { animation: scalpel-slice-loop 820ms cubic-bezier(.22,1,.36,1) infinite; transform-origin: 52% 48%; }
.route-icon-pulmonology .branch-transition-icon { animation: lung-breathe-loop 1050ms cubic-bezier(.22,1,.36,1) infinite; }
.route-icon-infectious-diseases .branch-transition-icon { animation: shield-pop-loop 900ms cubic-bezier(.22,1,.36,1) infinite; }
.route-icon-orthopedics .branch-transition-icon { animation: bone-tilt-loop 900ms cubic-bezier(.22,1,.36,1) infinite; }

.flask-motion-bubble { position: absolute; width: 6px; height: 6px; border-radius: 999px; background: color-mix(in srgb, var(--route-accent) 74%, white 26%); opacity: .6; left: 50%; bottom: 18px; box-shadow: 0 0 10px color-mix(in srgb, var(--route-accent) 42%, transparent); }
.flask-motion-bubble.bubble-one { animation: flask-bubble-rise 900ms ease-in-out infinite; }
.flask-motion-bubble.bubble-two { width: 4px; height: 4px; animation: flask-bubble-rise 900ms ease-in-out 230ms infinite; }

.branch-accent-line {
  position: absolute;
  left: 50%;
  bottom: 16px;
  width: 28px;
  height: 6px;
  border-radius: 999px;
  transform: translateX(-50%);
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--route-accent) 55%, white 45%), transparent);
  opacity: .5;
}

.flask-liquid-line {
  animation: flask-liquid-shimmer 1200ms ease-in-out infinite;
}

.brain-node,
.sparkle-dot,
.bone-joint,
.shield-cross-glow,
.breath-wave,
.surgery-streak,
.shield-halo {
  position: absolute;
  pointer-events: none;
}

.brain-node {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--route-accent) 82%, white 18%);
  box-shadow: 0 0 10px color-mix(in srgb, var(--route-accent) 56%, transparent);
  opacity: .25;
}

.brain-node.node-one { top: 10px; left: 14px; animation: brain-node-pulse 980ms ease-in-out infinite; }
.brain-node.node-two { top: 16px; right: 10px; animation: brain-node-pulse 980ms ease-in-out 180ms infinite; }
.brain-node.node-three { bottom: 12px; left: 50%; transform: translateX(-50%); animation: brain-node-pulse 980ms ease-in-out 360ms infinite; }

.sparkle-dot {
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--route-accent) 70%, white 30%);
  box-shadow: 0 0 12px color-mix(in srgb, var(--route-accent) 48%, transparent);
  opacity: .2;
}

.sparkle-dot::before,
.sparkle-dot::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 50%;
  background: currentColor;
  transform: translate(-50%, -50%);
  border-radius: 999px;
}

.sparkle-dot::before { width: 10px; height: 2px; }
.sparkle-dot::after { width: 2px; height: 10px; }
.sparkle-one { top: 8px; left: 12px; color: color-mix(in srgb, var(--route-accent) 76%, white 24%); animation: sparkle-twinkle 860ms ease-in-out infinite; }
.sparkle-two { top: 12px; right: 10px; color: color-mix(in srgb, var(--route-accent) 76%, white 24%); animation: sparkle-twinkle 860ms ease-in-out 240ms infinite; }
.sparkle-three { bottom: 10px; right: 16px; color: color-mix(in srgb, var(--route-accent) 76%, white 24%); animation: sparkle-twinkle 860ms ease-in-out 420ms infinite; }

.surgery-streak {
  left: 50%;
  top: 50%;
  width: 36px;
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--route-accent) 74%, white 26%), transparent);
  opacity: 0;
  transform: translate(-50%, -50%) rotate(-35deg);
  box-shadow: 0 0 12px color-mix(in srgb, var(--route-accent) 38%, transparent);
}

.surgery-streak.streak-one { animation: surgery-streak-pass 820ms ease-out infinite; }
.surgery-streak.streak-two { animation: surgery-streak-pass 820ms ease-out 180ms infinite; }

.breath-wave {
  left: 50%;
  top: 50%;
  width: 30px;
  height: 18px;
  border: 1px solid color-mix(in srgb, var(--route-accent) 42%, transparent);
  border-radius: 999px;
  transform: translate(-50%, -50%);
  opacity: 0;
}

.breath-wave.wave-one { animation: breath-wave-expand 1050ms ease-out infinite; }
.breath-wave.wave-two { animation: breath-wave-expand 1050ms ease-out 240ms infinite; }

.shield-halo {
  inset: 8px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--route-accent) 36%, transparent);
  opacity: 0;
}

.shield-halo.halo-one { animation: shield-halo-pulse 900ms ease-out infinite; }
.shield-halo.halo-two { animation: shield-halo-pulse 900ms ease-out 240ms infinite; }

.shield-cross-glow {
  width: 18px;
  height: 18px;
  left: 50%;
  top: 50%;
  border-radius: 999px;
  transform: translate(-50%, -42%);
  background: radial-gradient(circle, color-mix(in srgb, var(--route-accent) 46%, white 54%), transparent 70%);
  opacity: 0;
  filter: blur(1px);
  animation: shield-cross-pulse 900ms ease-in-out infinite;
}

.bone-joint {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--route-accent) 78%, white 22%);
  box-shadow: 0 0 10px color-mix(in srgb, var(--route-accent) 34%, transparent);
  opacity: .58;
}

.bone-joint.joint-one { top: 17px; left: 14px; animation: bone-joint-pulse 900ms ease-in-out infinite; }
.bone-joint.joint-two { top: 17px; right: 14px; animation: bone-joint-pulse 900ms ease-in-out 180ms infinite; }
.bone-joint.joint-three { bottom: 17px; left: 14px; animation: bone-joint-pulse 900ms ease-in-out 360ms infinite; }
.bone-joint.joint-four { bottom: 17px; right: 14px; animation: bone-joint-pulse 900ms ease-in-out 540ms infinite; }

.branch-route-copy { display: grid; justify-items: center; min-width: 0; text-align: center; }
.branch-route-copy.solo strong { color: var(--text-primary); font-size: clamp(24px, 2vw, 29px); font-weight: 820; line-height: 1.08; letter-spacing: -0.04em; overflow-wrap: break-word; text-shadow: 0 1px 0 rgba(255,255,255,0.04); }
.branch-route-reveal { animation: branch-page-reveal 420ms var(--ease-emphasized) both !important; }

@keyframes branch-overlay-in { from { opacity: 0; backdrop-filter: blur(0px); -webkit-backdrop-filter: blur(0px); } to { opacity: 1; backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); } }
@keyframes branch-overlay-out { from { opacity: 1; } to { opacity: 0; } }
@keyframes branch-stage-pop { 0% { opacity: 0; transform: translateY(12px) scale(.96); } 100% { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes branch-ring-expand { 0% { transform: scale(.68); opacity: 0; } 28% { opacity: .58; } 100% { transform: scale(1.28); opacity: 0; } }
@keyframes branch-glow-breathe { 0%, 100% { transform: scale(.94); opacity: .42; } 50% { transform: scale(1.16); opacity: .86; } }
@keyframes branch-orb-enter { 0% { opacity: 0; transform: translateY(12px) scale(.88); } 60% { opacity: 1; transform: translateY(0) scale(1.02); } 100% { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes branch-orb-breathe { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.035); } }
@keyframes branch-orbit-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
@keyframes branch-dot-orbit { from { transform: rotate(0deg) translateX(-50%); } to { transform: rotate(360deg) translateX(-50%); } }
@keyframes icon-shine-sweep { 0%, 28% { transform: translateX(-140%); opacity: 0; } 46% { opacity: .85; } 70%, 100% { transform: translateX(140%); opacity: 0; } }
@keyframes cardio-icon-beat { 0%, 100% { transform: scale(1); } 16% { transform: scale(1.12); } 30% { transform: scale(.97); } 46% { transform: scale(1.18); } 62% { transform: scale(.99); } }
@keyframes cardio-trace-loop { 0% { stroke-dashoffset: 84; opacity: .1; } 14% { opacity: 1; } 72% { stroke-dashoffset: 0; opacity: 1; } 100% { stroke-dashoffset: -20; opacity: 0; } }
@keyframes cardio-heart-glow-loop { 0%, 100% { opacity: 0; } 26% { opacity: .22; } 46% { opacity: .86; } 64% { opacity: .18; } }
@keyframes flask-sway-loop { 0%, 100% { transform: rotate(0deg) translateY(0); } 25% { transform: rotate(-11deg) translateY(-2px); } 50% { transform: rotate(9deg) translateY(1px); } 76% { transform: rotate(-4deg) translateY(0); } }
@keyframes flask-bubble-rise { 0% { transform: translate(-50%, 8px) scale(.6); opacity: 0; } 35% { opacity: .78; } 100% { transform: translate(-50%, -28px) scale(1); opacity: 0; } }
@keyframes flask-liquid-shimmer { 0%, 100% { opacity: .36; transform: translateX(-50%) scaleX(.8); } 50% { opacity: .82; transform: translateX(-50%) scaleX(1.06); } }
@keyframes brain-node-pulse { 0%, 100% { opacity: .18; transform: scale(.85); } 48% { opacity: 1; transform: scale(1.28); } }
@keyframes sparkle-twinkle { 0%, 100% { opacity: .18; transform: scale(.7); } 40% { opacity: .95; transform: scale(1.25); } 65% { opacity: .42; transform: scale(.9); } }
@keyframes surgery-streak-pass { 0%, 100% { opacity: 0; transform: translate(-50%, -50%) rotate(-35deg) scaleX(.2); } 28% { opacity: .9; transform: translate(-50%, -50%) rotate(-35deg) scaleX(1); } 60% { opacity: .24; } }
@keyframes breath-wave-expand { 0% { opacity: 0; transform: translate(-50%, -50%) scale(.72); } 26% { opacity: .75; } 100% { opacity: 0; transform: translate(-50%, -50%) scale(1.52); } }
@keyframes shield-halo-pulse { 0% { opacity: 0; transform: scale(.74); } 28% { opacity: .6; } 100% { opacity: 0; transform: scale(1.28); } }
@keyframes shield-cross-pulse { 0%, 100% { opacity: 0; transform: translate(-50%, -42%) scale(.85); } 42% { opacity: .82; transform: translate(-50%, -42%) scale(1.18); } }
@keyframes bone-joint-pulse { 0%, 100% { opacity: .42; transform: scale(1); } 42% { opacity: .96; transform: scale(1.24); } }
@keyframes neuro-glow-loop { 0%, 100% { transform: scale(1); filter: drop-shadow(0 0 0 transparent); } 45% { transform: scale(1.1); filter: drop-shadow(0 0 15px color-mix(in srgb, currentColor 36%, transparent)); } }
@keyframes pediatrics-bounce-loop { 0%, 100% { transform: translateY(0) scale(1); } 28% { transform: translateY(-8px) scale(1.04); } 56% { transform: translateY(0) scale(.98); } }
@keyframes scalpel-slice-loop { 0%, 100% { transform: translateX(0) rotate(0deg); } 28% { transform: translateX(8px) rotate(-18deg); } 54% { transform: translateX(-3px) rotate(10deg); } }
@keyframes lung-breathe-loop { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.17); } }
@keyframes shield-pop-loop { 0%, 100% { transform: scale(1); } 28% { transform: scale(1.16); } 52% { transform: scale(.95); } 76% { transform: scale(1.04); } }
@keyframes bone-tilt-loop { 0%, 100% { transform: rotate(0deg) scale(1); } 26% { transform: rotate(-12deg) scale(1.06); } 52% { transform: rotate(8deg) scale(.99); } 76% { transform: rotate(-3deg) scale(1.02); } }
@keyframes branch-page-reveal { 0% { opacity: 0; transform: translateY(16px) scale(.992); filter: blur(5px); } 60% { opacity: 1; transform: translateY(0) scale(1.002); filter: blur(0); } 100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); } }

html[data-theme="dark"] .branch-route-overlay,
.app-shell[data-theme="dark"] .branch-route-overlay {
  background:
    radial-gradient(circle at 50% 50%, color-mix(in srgb, var(--route-accent) 20%, transparent), transparent 32%),
    rgba(2, 8, 16, 0.48);
}

html[data-theme="dark"] .branch-route-orb,
.app-shell[data-theme="dark"] .branch-route-orb {
  background:
    radial-gradient(circle at 34% 22%, rgba(255,255,255,0.12), transparent 26%),
    radial-gradient(circle at 50% 18%, color-mix(in srgb, var(--route-accent) 22%, transparent), transparent 56%),
    linear-gradient(180deg, color-mix(in srgb, var(--surface-elevated) 88%, #07111b 12%), color-mix(in srgb, var(--surface-1) 94%, #050d16 6%));
  border-color: color-mix(in srgb, var(--route-accent) 34%, rgba(255,255,255,0.06));
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.08),
    0 22px 62px color-mix(in srgb, var(--route-accent) 16%, rgba(0, 0, 0, 0.36));
}

@media (max-width: 680px) {
  .branch-route-stage { width: min(270px, calc(100vw - 32px)); }
  .branch-route-hero { width: 154px; height: 154px; }
  .branch-route-orb { width: 104px; height: 104px; border-radius: 30px; }
  .branch-transition-visual, .branch-transition-icon { width: 58px; height: 58px; }
  .branch-transition-svg { width: 68px; height: 68px; }
  .branch-route-copy.solo strong { font-size: 22px; }
}

@media (prefers-reduced-motion: reduce) {
  .branch-route-overlay .branch-route-hero,
  .branch-route-overlay .branch-route-ring,
  .branch-route-overlay .branch-route-glow,
  .branch-route-overlay .branch-route-orb,
  .branch-route-overlay .branch-transition-visual,
  .branch-route-overlay .branch-transition-icon,
  .branch-route-overlay .branch-transition-svg,
  .branch-route-overlay .cardio-heart-trace,
  .branch-route-overlay .cardio-heart-glow {
    animation-play-state: running !important;
  }
}

