/* Branch-specific micro animations: compact, modern, and intentionally subtle. */
.branch-card[data-branch] .branch-card-head .icon-badge {
  position: relative;
  isolation: isolate;
  overflow: visible;
  transform-origin: 50% 62%;
  will-change: transform, box-shadow, filter;
}

.branch-card[data-branch] .branch-card-head .icon-badge::after {
  content: "";
  position: absolute;
  inset: -5px;
  z-index: -1;
  border-radius: inherit;
  border: 1px solid currentColor;
  opacity: 0;
  transform: scale(.92);
  pointer-events: none;
}

.branch-card[data-branch="internal-medicine"] .branch-card-head .icon-badge {
  animation: branchSway 3.8s ease-in-out infinite;
}

.branch-card[data-branch="neurology"] .branch-card-head .icon-badge {
  animation: branchPulseGlow 2.8s ease-in-out infinite;
}
.branch-card[data-branch="neurology"] .branch-card-head .icon-badge::after {
  animation: branchSoftRing 2.8s ease-in-out infinite;
}

.branch-card[data-branch="pediatrics"] .branch-card-head .icon-badge {
  animation: branchSoftBounce 3.2s cubic-bezier(.2, .8, .2, 1) infinite;
}

.branch-card[data-branch="general-surgery"] .branch-card-head .icon-badge {
  animation: branchSharpMotion 3s cubic-bezier(.2, 0, .1, 1) infinite;
}

.branch-card[data-branch="pulmonology"] .branch-card-head .icon-badge {
  animation: branchBreathe 4s ease-in-out infinite;
}
.branch-card[data-branch="pulmonology"] .branch-card-head .icon-badge svg {
  animation: branchLungFloat 4s ease-in-out infinite;
}

.branch-card[data-branch="infectious-diseases"] .branch-card-head .icon-badge {
  animation: branchShieldPop 3.4s cubic-bezier(.16, 1, .3, 1) infinite;
}
.branch-card[data-branch="infectious-diseases"] .branch-card-head .icon-badge::after {
  animation: branchShieldRing 3.4s cubic-bezier(.16, 1, .3, 1) infinite;
}

.branch-card[data-branch="orthopedics"] .branch-card-head .icon-badge {
  animation: branchSettleTilt 4.2s cubic-bezier(.2, .8, .2, 1) infinite;
}

.branch-card[data-branch]:hover .branch-card-head .icon-badge {
  animation-duration: 1.7s;
}

@keyframes branchSway {
  0%, 100% { transform: translateX(0) rotate(0deg); }
  35% { transform: translateX(-2px) rotate(-2.4deg); }
  70% { transform: translateX(2px) rotate(2deg); }
}

@keyframes branchPulseGlow {
  0%, 100% { transform: scale(1); box-shadow: 0 0 0 color-mix(in srgb, currentColor 0%, transparent); filter: saturate(1); }
  50% { transform: scale(1.045); box-shadow: 0 0 24px color-mix(in srgb, currentColor 26%, transparent); filter: saturate(1.18); }
}

@keyframes branchSoftRing {
  0%, 100% { opacity: 0; transform: scale(.9); }
  46% { opacity: .22; transform: scale(1.16); }
}

@keyframes branchSoftBounce {
  0%, 100% { transform: translateY(0) scale(1); }
  46% { transform: translateY(-4px) scale(1.025); }
  62% { transform: translateY(1px) scale(.995); }
}

@keyframes branchSharpMotion {
  0%, 78%, 100% { transform: translate(0, 0) rotate(0deg); }
  82% { transform: translate(3px, -1px) rotate(2deg); }
  86% { transform: translate(-2px, 1px) rotate(-1.2deg); }
  90% { transform: translate(1px, 0) rotate(.6deg); }
}

@keyframes branchBreathe {
  0%, 100% { transform: scale(1); box-shadow: 0 0 0 color-mix(in srgb, currentColor 0%, transparent); }
  50% { transform: scale(1.06); box-shadow: 0 0 20px color-mix(in srgb, currentColor 18%, transparent); }
}

@keyframes branchLungFloat {
  0%, 100% { transform: scaleY(1); }
  50% { transform: scaleY(1.08); }
}

@keyframes branchShieldPop {
  0%, 72%, 100% { transform: scale(1); }
  78% { transform: scale(1.12); }
  84% { transform: scale(.98); }
  90% { transform: scale(1.03); }
}

@keyframes branchShieldRing {
  0%, 72%, 100% { opacity: 0; transform: scale(.86); }
  79% { opacity: .24; transform: scale(1.22); }
  92% { opacity: 0; transform: scale(1.34); }
}

@keyframes branchSettleTilt {
  0%, 100% { transform: rotate(0deg) translateY(0); }
  22% { transform: rotate(-3deg) translateY(-1px); }
  42% { transform: rotate(1.6deg) translateY(0); }
  58% { transform: rotate(-.7deg); }
  72% { transform: rotate(0deg); }
}

@media (prefers-reduced-motion: reduce) {
  .branch-card[data-branch] .branch-card-head .icon-badge,
  .branch-card[data-branch] .branch-card-head .icon-badge svg,
  .branch-card[data-branch] .branch-card-head .icon-badge::after {
    animation: none !important;
  }
}


