  .branch-card.is-launching .branch-card-footer svg { animation-duration: 1ms !important; animation-iteration-count: 1 !important; }
}

/* ===== v92 Reliable branch click micro-animations =====
   The branch route waits 920ms in BranchSelector.jsx, so these animations have
   enough time to play before the case screen replaces the branch grid. */
.branch-card {
  position: relative;
  overflow: hidden;
  transform-origin: center;
}

.branch-launch-wave {
  position: absolute;
  inset: 10px;
  z-index: 0;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0;
  transform: scale(.985);
  background: radial-gradient(circle at 22% 22%, color-mix(in srgb, var(--accent) 20%, transparent), transparent 42%);
}

.branch-card > *:not(.branch-launch-wave) {
  position: relative;
  z-index: 1;
}

.branch-card.is-launching {
  pointer-events: none;
  transform: translateY(-3px) scale(1.012) !important;
  border-color: color-mix(in srgb, var(--accent) 42%, var(--border-subtle)) !important;
  box-shadow: 0 20px 58px color-mix(in srgb, var(--accent) 18%, transparent), var(--shadow-card) !important;
  transition: transform 220ms cubic-bezier(.22, 1, .36, 1), box-shadow 220ms cubic-bezier(.22, 1, .36, 1), border-color 220ms cubic-bezier(.22, 1, .36, 1) !important;
}

.branch-card.is-launching .branch-launch-wave {
  animation: branchLaunchSurfacePulse 920ms cubic-bezier(.22, 1, .36, 1) 1 both !important;
}

.branch-card.is-launching .branch-count {
  color: var(--accent) !important;
  border-color: color-mix(in srgb, var(--accent) 28%, var(--border-subtle)) !important;
  background: color-mix(in srgb, var(--accent) 11%, var(--surface-2)) !important;
}

.branch-card.is-launching .branch-card-head .icon-badge {
  position: relative;
  overflow: visible !important;
  animation: branchLaunchBadgeBeat 920ms cubic-bezier(.22, 1, .36, 1) 1 both !important;
  box-shadow: 0 0 0 0 color-mix(in srgb, currentColor 0%, transparent);
}

.branch-card.is-launching .branch-card-head .icon-badge::before,
.branch-card.is-launching .branch-card-head .icon-badge::after {
  content: '';
  position: absolute;
  inset: -8px;
  z-index: -1;
  border-radius: inherit;
  pointer-events: none;
  border: 1px solid currentColor;
  opacity: 0;
  transform: scale(.78);
}

.branch-card.is-launching .branch-card-head .icon-badge::before {
  animation: branchLaunchRingStrong 920ms cubic-bezier(.22, 1, .36, 1) 1 both !important;
}

.branch-card.is-launching .branch-card-head .icon-badge::after {
  animation: branchLaunchRingSoft 920ms cubic-bezier(.22, 1, .36, 1) 1 both !important;
}

.branch-card.is-launching .branch-card-head .icon-badge svg {
  transform-origin: center !important;
  animation-duration: 920ms !important;
  animation-timing-function: cubic-bezier(.22, 1, .36, 1) !important;
  animation-iteration-count: 1 !important;
  animation-fill-mode: both !important;
}

.branch-card.is-launching[data-branch='cardiovascular'] .branch-card-head .icon-badge svg {
  animation-name: branchLaunchCardioPulse !important;
}

.branch-card.is-launching[data-branch='internal-medicine'] .branch-card-head .icon-badge svg {
  animation-name: branchLaunchSway !important;
}

.branch-card.is-launching[data-branch='neurology'] .branch-card-head .icon-badge svg {
  animation-name: branchLaunchNeuroGlow !important;
}

.branch-card.is-launching[data-branch='pediatrics'] .branch-card-head .icon-badge svg {
  animation-name: branchLaunchPedsBounce !important;
}

.branch-card.is-launching[data-branch='general-surgery'] .branch-card-head .icon-badge svg {
  animation-name: branchLaunchSurgerySlice !important;
}

.branch-card.is-launching[data-branch='pulmonology'] .branch-card-head .icon-badge svg {
  animation-name: branchLaunchLungBreathe !important;
}

.branch-card.is-launching[data-branch='infectious-diseases'] .branch-card-head .icon-badge svg {
  animation-name: branchLaunchShieldPop !important;
}

.branch-card.is-launching[data-branch='orthopedics'] .branch-card-head .icon-badge svg {
  animation-name: branchLaunchBoneTilt !important;
}

.branch-card.is-launching .branch-progress span {
  animation: branchLaunchProgressShine 920ms cubic-bezier(.22, 1, .36, 1) 1 both !important;
}

.branch-card.is-launching .branch-card-footer svg {
  animation: branchLaunchArrowNudge 920ms cubic-bezier(.22, 1, .36, 1) 1 both !important;
}

@keyframes branchLaunchSurfacePulse {
  0% { opacity: 0; transform: scale(.985); }
  20% { opacity: .9; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.06); }
}

@keyframes branchLaunchBadgeBeat {
  0%, 100% { transform: scale(1); filter: saturate(1); box-shadow: 0 0 0 0 color-mix(in srgb, currentColor 0%, transparent); }
  16% { transform: scale(1.18); filter: saturate(1.25); box-shadow: 0 0 0 7px color-mix(in srgb, currentColor 12%, transparent); }
  31% { transform: scale(.96); }
  47% { transform: scale(1.105); box-shadow: 0 0 0 10px color-mix(in srgb, currentColor 7%, transparent); }
  68% { transform: scale(1.01); }
}

@keyframes branchLaunchRingStrong {
  0% { opacity: 0; transform: scale(.72); }
  18% { opacity: .32; transform: scale(1); }
  72%, 100% { opacity: 0; transform: scale(1.55); }
}

@keyframes branchLaunchRingSoft {
  0%, 18% { opacity: 0; transform: scale(.78); }
  36% { opacity: .18; transform: scale(1.16); }
  100% { opacity: 0; transform: scale(1.85); }
}

@keyframes branchLaunchCardioPulse {
  0%, 100% { transform: scale(1); filter: drop-shadow(0 0 0 transparent); }
  15% { transform: scale(1.30); filter: drop-shadow(0 0 11px color-mix(in srgb, currentColor 34%, transparent)); }
  29% { transform: scale(.88); }
  46% { transform: scale(1.20); filter: drop-shadow(0 0 8px color-mix(in srgb, currentColor 24%, transparent)); }
  66% { transform: scale(.98); }
}

@keyframes branchLaunchSway {
  0%, 100% { transform: rotate(0deg) translateY(0); }
  20% { transform: rotate(-10deg) translateY(-1px); }
  44% { transform: rotate(8deg) translateY(0); }
  66% { transform: rotate(-3deg); }
}

@keyframes branchLaunchNeuroGlow {
  0%, 100% { transform: scale(1); filter: drop-shadow(0 0 0 transparent); }
  30% { transform: scale(1.16); filter: drop-shadow(0 0 12px color-mix(in srgb, currentColor 42%, transparent)); }
  58% { transform: scale(.98); filter: drop-shadow(0 0 6px color-mix(in srgb, currentColor 22%, transparent)); }
}

@keyframes branchLaunchPedsBounce {
  0%, 100% { transform: translateY(0) scale(1); }
  22% { transform: translateY(-7px) scale(1.06); }
  45% { transform: translateY(2px) scale(.97); }
  68% { transform: translateY(-3px) scale(1.02); }
}

@keyframes branchLaunchSurgerySlice {
  0%, 100% { transform: translateX(0) rotate(0deg); }
  20% { transform: translateX(4px) rotate(-15deg); }
  42% { transform: translateX(-3px) rotate(9deg); }
  68% { transform: translateX(1px) rotate(-3deg); }
}

@keyframes branchLaunchLungBreathe {
  0%, 100% { transform: scale(1); }
  34% { transform: scale(1.22); }
  64% { transform: scale(.96); }
}

@keyframes branchLaunchShieldPop {
  0%, 100% { transform: scale(1); }
  22% { transform: scale(1.24); }
  47% { transform: scale(.92); }
  70% { transform: scale(1.06); }
}

@keyframes branchLaunchBoneTilt {
  0%, 100% { transform: rotate(0deg) scale(1); }
  20% { transform: rotate(-10deg) scale(1.08); }
  44% { transform: rotate(7deg) scale(.97); }
  70% { transform: rotate(-2deg) scale(1.02); }
}

@keyframes branchLaunchProgressShine {
  0%, 100% { filter: brightness(1); transform: scaleX(1); }
  44% { filter: brightness(1.55); transform: scaleX(1.03); }
}

@keyframes branchLaunchArrowNudge {
  0%, 100% { transform: translateX(0); opacity: 1; }
  40% { transform: translateX(6px); opacity: .92; }
}

@media (prefers-reduced-motion: reduce) {
  .branch-card.is-launching,
  .branch-card.is-launching .branch-launch-wave,
  .branch-card.is-launching .branch-card-head .icon-badge,
  .branch-card.is-launching .branch-card-head .icon-badge::before,
  .branch-card.is-launching .branch-card-head .icon-badge::after,
  .branch-card.is-launching .branch-card-head .icon-badge svg,
  .branch-card.is-launching .branch-progress span,
  .branch-card.is-launching .branch-card-footer svg {
    animation-duration: 720ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 180ms !important;
  }
}

