.auth-minimal-logo-copy {
  color: var(--auth-teal);
  font-size: 14px;
  font-weight: 860;
  letter-spacing: .22em;
}

.auth-minimal-hero {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 18px;
  max-width: 690px;
}
.auth-minimal-hero h1 {
  margin: 0;
  color: var(--auth-ink);
  font-size: clamp(44px, 5.45vw, 76px);
  line-height: .96;
  letter-spacing: -.064em;
  font-weight: 850;
}
.auth-minimal-hero p {
  margin: 0;
  max-width: 460px;
  color: var(--auth-muted);
  font-size: clamp(16px, 1.3vw, 20px);
  line-height: 1.58;
  font-weight: 520;
}

.auth-minimal-features {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(14px, 2vw, 24px);
  padding-top: 10px;
}
.auth-minimal-feature {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  min-width: 0;
}
.auth-minimal-feature > svg {
  width: 24px;
  height: 24px;
  color: var(--auth-teal);
  margin-top: 1px;
}
.auth-minimal-feature div { display: grid; gap: 5px; min-width: 0; }
.auth-minimal-feature strong {
  color: var(--auth-ink);
  font-size: 15px;
  letter-spacing: -.01em;
  line-height: 1.12;
}
.auth-minimal-feature span {
  color: var(--auth-muted);
  font-size: 13.2px;
  line-height: 1.42;
}

.auth-minimal-card {
  display: grid;
  gap: 18px;
  padding: clamp(28px, 3.6vw, 46px);
  border: 1px solid rgba(15, 23, 42, .08);
  border-radius: 34px;
  background: rgba(255,255,255,.94);
  box-shadow: 0 30px 78px rgba(15, 23, 42, .10), inset 0 1px 0 rgba(255,255,255,.92);
  backdrop-filter: blur(16px);
}

.auth-minimal-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 16px;
}
.auth-minimal-head p {
  margin: 0 0 10px;
  color: var(--auth-teal);
  font-size: 12px;
  font-weight: 850;
  letter-spacing: .18em;
}
.auth-minimal-head h2 {
  margin: 0 0 9px;
  color: var(--auth-ink);
  font-size: clamp(38px, 3.4vw, 56px);
  line-height: .95;
  letter-spacing: -.055em;
  font-weight: 850;
}
.auth-minimal-head span {
  display: block;
  max-width: 340px;
  color: var(--auth-muted);
  font-size: 15px;
  line-height: 1.52;
}
.auth-minimal-theme {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 999px;
  color: #334155;
  border: 1px solid var(--auth-line);
  background: #fff;
  box-shadow: 0 10px 22px rgba(15, 23, 42, .06);
  transition: transform .18s ease, border-color .18s ease, color .18s ease;
}
.auth-minimal-theme:hover { transform: translateY(-1px); border-color: rgba(15,118,110,.3); color: var(--auth-teal); }
.auth-minimal-theme svg { width: 21px; height: 21px; }

.auth-minimal-tabs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.auth-minimal-tabs button,
.auth-minimal-google,
.auth-minimal-demo,
.auth-minimal-submit {
  min-height: 56px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border-radius: 17px;
  font-weight: 800;
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease, background .18s ease, color .18s ease;
}
.auth-minimal-tabs button {
  color: #64748b;
  border: 1px solid var(--auth-line);
  background: #fff;
}
.auth-minimal-tabs button svg { width: 19px; height: 19px; }
.auth-minimal-tabs button.active {
  color: #fff;
  border-color: transparent;
  background: linear-gradient(135deg, var(--auth-teal), var(--auth-teal-2));
  box-shadow: 0 16px 34px rgba(15, 118, 110, .18);
}

.auth-minimal-quick-actions { display: grid; gap: 11px; }
.auth-minimal-google {
  width: 100%;
  color: #0f172a;
  border: 1px solid var(--auth-line);
  background: #fff;
  box-shadow: 0 12px 28px rgba(15, 23, 42, .055);
}
.auth-minimal-google:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: rgba(15,118,110,.22);
  box-shadow: 0 18px 34px rgba(15, 23, 42, .08);
}
.auth-minimal-google-mark {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 999px;
  background: #fff;
  box-shadow: inset 0 0 0 1px rgba(15,23,42,.06);
}
.auth-minimal-demo {
  width: 100%;
  color: var(--auth-teal);
  border: 1px solid rgba(15,118,110,.18);
  background: linear-gradient(135deg, rgba(240,253,250,.94), rgba(255,255,255,.94));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.88);
}
.auth-minimal-demo:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: rgba(15,118,110,.32);
  background: linear-gradient(135deg, #e7f8f5, #ffffff);
}
.auth-minimal-demo svg { width: 20px; height: 20px; }

.auth-minimal-divider {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 14px;
  color: #94a3b8;
  font-size: 13px;
  font-weight: 720;
}
.auth-minimal-divider::before,
.auth-minimal-divider::after {
  content: '';
  height: 1px;
  background: #e5eef0;
}

.auth-minimal-form-stack { display: grid; gap: 12px; }
.auth-minimal-field { display: grid; gap: 7px; }
.auth-minimal-field > span {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}
.auth-minimal-input {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  min-height: 58px;
  border-radius: 17px;
  border: 1px solid var(--auth-line);
  background: #fbfdfd;
  transition: border-color .18s ease, box-shadow .18s ease, background .18s ease;
}
.auth-minimal-input:focus-within {
  border-color: rgba(15, 118, 110, .48);
  background: #fff;
  box-shadow: 0 0 0 4px rgba(20, 184, 166, .12);
}
.auth-minimal-input > svg {
  width: 21px;
  height: 21px;
  color: #94a3b8;
  margin-left: 17px;
}
.auth-minimal-input input {
  min-height: 56px;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--auth-ink);
  padding: 0 13px;
  font-size: 15.5px;
  font-weight: 560;
}
.auth-minimal-input input::placeholder { color: #94a3b8; opacity: .95; }
.auth-minimal-eye {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  margin-right: 8px;
  border-radius: 13px;
  color: #94a3b8;
  background: transparent;
}
.auth-minimal-eye:hover { color: var(--auth-teal); background: rgba(20,184,166,.08); }
.auth-minimal-eye svg { width: 20px; height: 20px; }

.auth-minimal-options {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: var(--auth-muted);
  font-size: 13.5px;
  font-weight: 650;
}
.auth-minimal-options label {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  user-select: none;
}
.auth-minimal-options input {
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 7px;
  border: 1px solid #cbd5e1;
  background: #fff;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.9);
}
.auth-minimal-options input:checked {
  border-color: var(--auth-teal);
  background: linear-gradient(135deg, var(--auth-teal), var(--auth-teal-2));
  box-shadow: inset 0 0 0 5px rgba(255,255,255,.28);
}
.auth-minimal-options button {
  padding: 0;
  color: var(--auth-teal);
  background: transparent;
  font-weight: 800;
}

.auth-minimal-message {
  padding: 12px 14px;
  border-radius: 16px;
  font-size: 13px;
  font-weight: 720;
  border: 1px solid #e2e8f0;
}
.auth-minimal-message.error {
  color: #dc2626;
  background: #fff5f5;
  border-color: #fecaca;
}
.auth-minimal-message.success {
  color: #047857;
  background: #ecfdf5;
  border-color: #bbf7d0;
}

.auth-minimal-submit {
  width: 100%;
  color: #fff;
  border: 1px solid transparent;
  background: linear-gradient(135deg, var(--auth-teal), var(--auth-teal-2));
  box-shadow: 0 18px 36px rgba(15, 118, 110, .22), inset 0 1px 0 rgba(255,255,255,.28);
  font-size: 16px;
}
.auth-minimal-submit:hover:not(:disabled) {
  transform: translateY(-1px);
  background: linear-gradient(135deg, #0b6b63, #0f988b);
  box-shadow: 0 22px 44px rgba(15, 118, 110, .26), inset 0 1px 0 rgba(255,255,255,.25);
}
.auth-minimal-submit svg { width: 20px; height: 20px; }
.auth-minimal-note {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  margin: 0;
  color: #738399;
  font-size: 13px;
  font-weight: 650;
  text-align: center;
}
.auth-minimal-note svg { width: 19px; height: 19px; color: #8796aa; }

@media (max-width: 1080px) {
  .auth-minimal-shell {
    grid-template-columns: 1fr;
    width: min(760px, calc(100vw - 28px));
    gap: 22px;
    padding: 28px 0 44px;
  }
  .auth-minimal-brand { min-height: auto; }
  .auth-minimal-features { grid-template-columns: 1fr; gap: 14px; }
}

@media (max-width: 680px) {
  .auth-minimal-shell { width: min(100% - 20px, 520px); }
  .auth-minimal-brand,
  .auth-minimal-card {
    border-radius: 26px;
    padding: 24px;
  }
  .auth-minimal-hero h1 { font-size: 34px; letter-spacing: -.052em; }
  .auth-minimal-hero p { font-size: 15px; }
  .auth-minimal-logo-mark { width: 48px; height: 48px; border-radius: 16px; }
  .auth-minimal-logo-copy { font-size: 12px; letter-spacing: .18em; }
  .auth-minimal-head h2 { font-size: 36px; }
  .auth-minimal-theme { width: 44px; height: 44px; }
  .auth-minimal-tabs button,
  .auth-minimal-google,
  .auth-minimal-demo,
  .auth-minimal-submit,
  .auth-minimal-input { min-height: 54px; }
  .auth-minimal-options { align-items: flex-start; flex-direction: column; }
}

/* ===== Auth screen alignment + elegant input focus fix ===== */

/* Sol ve sağ panelin üst hizasını eşitle */
.auth-page-shell.auth-premium-login {
  align-items: start !important;
  padding-top: clamp(48px, 6vh, 72px) !important;
  padding-bottom: clamp(48px, 6vh, 72px) !important;
}

/* İki ana panel aynı dikey ritimde başlasın */
.auth-showcase-panel,
.auth-form-panel {
  align-self: start !important;
}

/* Sol panel sağ panele göre aşağıda kalmasın */
.auth-showcase-panel {
  min-height: 720px !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: space-between !important;
}

/* Sağ panel fazla aşağı taşmasın, daha dengeli dursun */
.auth-form-panel {
  min-height: 720px !important;
}

/* Input kutularındaki sert/çirkin focus highlight'ı kaldır */
.auth-input-wrap {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, 0.28) !important;
  background: rgba(255, 255, 255, 0.78) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    0 8px 22px rgba(15, 23, 42, 0.025) !important;
  transition:
    border-color 180ms ease,
    box-shadow 180ms ease,
    background-color 180ms ease,
    transform 180ms ease;
}

/* Eski kalın turquoise highlight yerine soft focus */
.auth-input-wrap:focus-within {
  border-color: rgba(13, 148, 136, 0.42) !important;
  background: rgba(255, 255, 255, 0.96) !important;
  box-shadow:
    0 0 0 4px rgba(13, 148, 136, 0.075),
    0 12px 26px rgba(15, 23, 42, 0.055),
    inset 0 1px 0 rgba(255, 255, 255, 0.9) !important;
  transform: translateY(-1px);
}

/* Input içindeki default browser outline tamamen kalksın */
.auth-input-wrap input,
.auth-input-wrap input:focus,
.auth-input-wrap input:focus-visible {
  outline: none !important;
  box-shadow: none !important;
  border: none !important;
}

/* İkon tarafında ayrı kutu/çizgi gibi görünüm oluşmasın */
.auth-input-wrap > svg {
  color: #8ea0b7 !important;
  transition: color 180ms ease;
}

.auth-input-wrap:focus-within > svg {
  color: #0f766e !important;
}

/* Şifre göz ikonu da daha soft olsun */
.auth-password-toggle,
.auth-password-toggle:focus,
.auth-password-toggle:focus-visible {
  outline: none !important;
  box-shadow: none !important;
  border: none !important;
}

.auth-password-toggle:hover {
  background: rgba(13, 148, 136, 0.07) !important;
}

/* Checkbox focus sert görünmesin */
.auth-checkbox-row input:focus,
.auth-checkbox-row input:focus-visible {
  outline: none !important;
  box-shadow: 0 0 0 4px rgba(13, 148, 136, 0.09) !important;
}

/* Daha dengeli desktop görünüm */
@media (min-width: 1181px) {
  .auth-premium-login {
    grid-template-columns: minmax(600px, 1.05fr) minmax(420px, 0.7fr) !important;
    gap: clamp(44px, 5vw, 76px) !important;
  }

  .auth-showcase-panel,
  .auth-form-panel {
    margin-top: 0 !important;
  }
}

/* Mobilde hizalama bozulmasın */
@media (max-width: 1180px) {
  .auth-page-shell.auth-premium-login {
    align-items: center !important;
    padding-top: 28px !important;
  }

  .auth-showcase-panel,
  .auth-form-panel {
    min-height: auto !important;
  }
}



/* ===== v107 auth dark-mode optimization + premium micro interactions ===== */

/* Light/dark auth variables are scoped so the rest of KlinikIQ stays untouched. */
.app-shell:has(.auth-minimal-shell),
.app-shell[data-theme="light"]:has(.auth-minimal-shell),
html[data-theme="light"] .app-shell:has(.auth-minimal-shell),
body[data-theme="light"] .app-shell:has(.auth-minimal-shell) {
  --auth-page-bg: #f7fbfb;
  --auth-grid-line: rgba(15, 118, 110, .055);
  --auth-panel-solid: rgba(255,255,255,.94);
  --auth-panel-soft: rgba(255,255,255,.72);
  --auth-panel-border: rgba(15, 23, 42, .08);
  --auth-panel-shadow: 0 30px 78px rgba(15, 23, 42, .10);
  --auth-text-main: #0f172a;
  --auth-text-muted: #64748b;
  --auth-text-soft: #94a3b8;
  --auth-field-bg: rgba(255,255,255,.72);
  --auth-field-bg-focus: rgba(255,255,255,.96);
  --auth-line-soft: #dbe7e8;
  --auth-card-ambient: rgba(20, 184, 166, .16);
  background: var(--auth-page-bg) !important;
}

.app-shell[data-theme="dark"]:has(.auth-minimal-shell),
html[data-theme="dark"] .app-shell:has(.auth-minimal-shell),
body[data-theme="dark"] .app-shell:has(.auth-minimal-shell),
.app-shell.theme-dark:has(.auth-minimal-shell) {
  --auth-page-bg: #07111a;
  --auth-grid-line: rgba(45, 212, 191, .07);
  --auth-panel-solid: rgba(9, 22, 32, .86);
  --auth-panel-soft: rgba(13, 32, 45, .68);
  --auth-panel-border: rgba(125, 211, 252, .13);
  --auth-panel-shadow: 0 34px 100px rgba(0, 0, 0, .38);
  --auth-text-main: #f8fafc;
  --auth-text-muted: #a6b7c9;
  --auth-text-soft: #7f93a9;
  --auth-field-bg: rgba(8, 21, 31, .76);
  --auth-field-bg-focus: rgba(10, 27, 39, .96);
  --auth-line-soft: rgba(148, 163, 184, .20);
  --auth-card-ambient: rgba(20, 184, 166, .20);
  background:
    radial-gradient(circle at 12% 18%, rgba(20, 184, 166, .13), transparent 26%),
    radial-gradient(circle at 92% 82%, rgba(14, 165, 233, .11), transparent 28%),
    #07111a !important;
  color: var(--auth-text-main);
}

.app-shell[data-theme="dark"]:has(.auth-minimal-shell)::before,
html[data-theme="dark"] .app-shell:has(.auth-minimal-shell)::before,
body[data-theme="dark"] .app-shell:has(.auth-minimal-shell)::before,
.app-shell.theme-dark:has(.auth-minimal-shell)::before {
  opacity: 0 !important;
}

.auth-minimal-shell {
  perspective: 1400px;
}

.auth-minimal-grid {
  background:
    linear-gradient(var(--auth-grid-line, rgba(15, 118, 110, .055)) 1px, transparent 1px),
    linear-gradient(90deg, var(--auth-grid-line, rgba(15, 118, 110, .055)) 1px, transparent 1px),
    radial-gradient(circle at 70% 16%, rgba(20, 184, 166, .10), transparent 30%),
    linear-gradient(180deg, color-mix(in srgb, var(--auth-page-bg, #f7fbfb) 90%, white 10%) 0%, var(--auth-page-bg, #f7fbfb) 100%) !important;
  background-size: 38px 38px, 38px 38px, auto, auto !important;
}

.auth-minimal-glow {
  animation: authGlowFloat 8s ease-in-out infinite;
}
.auth-minimal-glow.glow-b {
  animation-delay: -3s;
}

.auth-minimal-brand,
.auth-minimal-card {
  transition:
    transform .28s cubic-bezier(.2,.8,.2,1),
    border-color .28s ease,
    box-shadow .28s ease,
    background .28s ease;
}

.auth-minimal-brand {
  color: var(--auth-text-main) !important;
  border-color: var(--auth-panel-border) !important;
  background:
    radial-gradient(circle at 92% 48%, var(--auth-card-ambient), transparent 35%),
    linear-gradient(145deg, var(--auth-panel-solid), var(--auth-panel-soft)) !important;
  box-shadow:
    var(--auth-panel-shadow),
    inset 0 1px 0 rgba(255,255,255,.12) !important;
}

.auth-minimal-card {
  color: var(--auth-text-main) !important;
  border-color: var(--auth-panel-border) !important;
  background:
    linear-gradient(145deg, var(--auth-panel-solid), color-mix(in srgb, var(--auth-panel-soft) 86%, transparent)) !important;
  box-shadow:
    var(--auth-panel-shadow),
    inset 0 1px 0 rgba(255,255,255,.10) !important;
}

.auth-minimal-brand:hover,
.auth-minimal-card:hover {
  border-color: rgba(20, 184, 166, .26) !important;
}

.auth-minimal-logo-mark {
  position: relative;
  overflow: hidden;
  color: var(--auth-teal) !important;
  background: color-mix(in srgb, var(--auth-panel-solid) 78%, white 18%) !important;
  border-color: rgba(20, 184, 166, .24) !important;
  box-shadow:
    0 16px 34px rgba(15, 118, 110, .14),
    inset 0 1px 0 rgba(255,255,255,.22) !important;
}
.auth-minimal-logo-mark::after {
  content: "";
  position: absolute;
  inset: 9px;
  border-radius: 999px;
  border: 1px solid rgba(20, 184, 166, .28);
  opacity: 0;
  transform: scale(.82);
  animation: authLogoPulse 2.6s ease-out infinite;
}
.auth-minimal-logo-mark svg {
  animation: authPulseLine 2.6s ease-in-out infinite;
}

.auth-minimal-logo-copy,
.auth-minimal-head p,
.auth-minimal-demo,
.auth-minimal-options button {
  color: #0f766e !important;
}
.app-shell[data-theme="dark"] .auth-minimal-logo-copy,
html[data-theme="dark"] .auth-minimal-logo-copy,
.app-shell[data-theme="dark"] .auth-minimal-head p,
html[data-theme="dark"] .auth-minimal-head p,
.app-shell[data-theme="dark"] .auth-minimal-demo,
html[data-theme="dark"] .auth-minimal-demo,
.app-shell[data-theme="dark"] .auth-minimal-options button,
html[data-theme="dark"] .auth-minimal-options button {
  color: #5eead4 !important;
}

.auth-minimal-hero h1,
.auth-minimal-head h2,
.auth-minimal-feature strong {
  color: var(--auth-text-main) !important;
}
.auth-minimal-hero p,
.auth-minimal-head span,
.auth-minimal-feature span,
.auth-minimal-note,
.auth-minimal-options,
.auth-minimal-tabs button:not(.active) {
  color: var(--auth-text-muted) !important;
}

.auth-minimal-orbit span {
  border-color: rgba(20, 184, 166, .16) !important;
  animation: authOrbitDrift 9s ease-in-out infinite;
}
.auth-minimal-orbit span:nth-child(2) {
  animation-delay: -2.6s;
}
.auth-minimal-orbit span:nth-child(3) {
  background: rgba(20, 184, 166, .10) !important;
  box-shadow: 0 0 42px rgba(20, 184, 166, .16);
  animation: authOrbitCenter 4.8s ease-in-out infinite;
}

.auth-minimal-feature {
  position: relative;
  padding: 10px 8px;
  margin: -10px -8px;
  border-radius: 18px;
  transition: transform .2s ease, background .2s ease, box-shadow .2s ease;
}
.auth-minimal-feature:hover {
  transform: translateY(-2px);
  background: rgba(20, 184, 166, .055);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.08);
}
.auth-minimal-feature > svg {
  transition: transform .22s cubic-bezier(.2,.8,.2,1), color .22s ease, filter .22s ease;
}
.auth-minimal-feature:hover > svg {
  transform: translateY(-1px) scale(1.08);
  color: #14b8a6 !important;
  filter: drop-shadow(0 8px 14px rgba(20, 184, 166, .18));
}

.auth-minimal-theme {
  position: relative;
  overflow: hidden;
  color: var(--auth-text-main) !important;
  border-color: var(--auth-line-soft) !important;
  background: var(--auth-field-bg) !important;
  box-shadow: 0 12px 28px rgba(15, 23, 42, .08), inset 0 1px 0 rgba(255,255,255,.12) !important;
}
.auth-minimal-theme::before {
  content: "";
  position: absolute;
  inset: -50%;
  background: conic-gradient(from 180deg, transparent, rgba(20, 184, 166, .18), transparent 28%);
  opacity: 0;
  transition: opacity .2s ease;
  animation: authSpin 4s linear infinite;
}
.auth-minimal-theme:hover::before {
  opacity: 1;
}
.auth-minimal-theme svg {
  position: relative;
  z-index: 1;
  transition: transform .22s ease;
}
.auth-minimal-theme:hover svg {
  transform: rotate(-18deg) scale(1.06);
}

.auth-minimal-tabs button,
.auth-minimal-google,
.auth-minimal-demo,
.auth-minimal-submit {
  position: relative;
  overflow: hidden;
  will-change: transform;
}
.auth-minimal-tabs button:not(.active),
.auth-minimal-google {
  border-color: var(--auth-line-soft) !important;
  background: var(--auth-field-bg) !important;
  color: var(--auth-text-main) !important;
  box-shadow: 0 12px 28px rgba(15, 23, 42, .055), inset 0 1px 0 rgba(255,255,255,.10) !important;
}
.auth-minimal-tabs button:not(.active):hover,
.auth-minimal-google:hover:not(:disabled),
.auth-minimal-demo:hover:not(:disabled) {
  transform: translateY(-2px);
  border-color: rgba(20, 184, 166, .34) !important;
  box-shadow: 0 20px 38px rgba(15, 118, 110, .12), inset 0 1px 0 rgba(255,255,255,.13) !important;
}

.auth-minimal-tabs button.active,
.auth-minimal-submit {
  background: linear-gradient(135deg, #0f766e, #14b8a6) !important;
  color: #fff !important;
  border-color: transparent !important;
}
.auth-minimal-tabs button.active::after,
.auth-minimal-submit::after,
.auth-minimal-demo::after {
  content: "";
  position: absolute;
  inset: 0;
  translate: -130% 0;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.26), transparent);
  transition: translate .55s ease;
}
.auth-minimal-tabs button.active:hover::after,
.auth-minimal-submit:hover::after,
.auth-minimal-demo:hover::after {
  translate: 130% 0;
}

.auth-minimal-google .auth-minimal-google-mark {
  transition: transform .22s ease, box-shadow .22s ease;
}
.auth-minimal-google:hover:not(:disabled) .auth-minimal-google-mark {
  transform: scale(1.08) rotate(-4deg);
  box-shadow: 0 10px 24px rgba(66, 133, 244, .14), inset 0 0 0 1px rgba(15,23,42,.06);
}

.auth-minimal-demo {
  border-color: rgba(20, 184, 166, .24) !important;
  background:
    linear-gradient(135deg, rgba(20, 184, 166, .10), rgba(255,255,255,.02)) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.12) !important;
}
.auth-minimal-demo svg {
  transition: transform .22s ease, filter .22s ease;
}
.auth-minimal-demo:hover:not(:disabled) svg {
  transform: rotate(12deg) scale(1.08);
  filter: drop-shadow(0 8px 14px rgba(20, 184, 166, .28));
}

.auth-minimal-divider {
  color: var(--auth-text-soft) !important;
}
.auth-minimal-divider::before,
.auth-minimal-divider::after {
  background: var(--auth-line-soft) !important;
}

.auth-minimal-input {
  border-color: var(--auth-line-soft) !important;
  background: var(--auth-field-bg) !important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.10),
    0 8px 22px rgba(15, 23, 42, .035) !important;
  transition:
    transform .2s ease,
    border-color .2s ease,
    box-shadow .2s ease,
    background .2s ease;
}
.auth-minimal-input:hover {
  border-color: rgba(20, 184, 166, .24) !important;
}
.auth-minimal-input:focus-within {
  transform: translateY(-1px);
  border-color: rgba(20, 184, 166, .48) !important;
  background: var(--auth-field-bg-focus) !important;
  box-shadow:
    0 0 0 4px rgba(20, 184, 166, .10),
    0 16px 30px rgba(15, 23, 42, .07),
    inset 0 1px 0 rgba(255,255,255,.16) !important;
}
.auth-minimal-input > svg {
  color: var(--auth-text-soft) !important;
  transition: color .2s ease, transform .2s ease;
}
.auth-minimal-input:focus-within > svg {
  color: #14b8a6 !important;
  transform: scale(1.04);
}
.auth-minimal-input input {
  color: var(--auth-text-main) !important;
  caret-color: #14b8a6;
}
.auth-minimal-input input::placeholder {
  color: var(--auth-text-soft) !important;
  opacity: .9;
}
.auth-minimal-input input:focus,
.auth-minimal-input input:focus-visible,
.auth-minimal-eye:focus,
.auth-minimal-eye:focus-visible {
  outline: none !important;
  box-shadow: none !important;
}

.auth-minimal-eye {
  color: var(--auth-text-soft) !important;
  transition: color .18s ease, transform .18s ease, background .18s ease;
}
.auth-minimal-eye:hover {
  color: #14b8a6 !important;
  transform: scale(1.04);
  background: rgba(20, 184, 166, .08) !important;
}

.auth-minimal-options label {
  color: var(--auth-text-muted) !important;
}
.auth-minimal-options input {
  border-color: var(--auth-line-soft) !important;
  background: var(--auth-field-bg) !important;
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease, background .18s ease;
}
.auth-minimal-options input:hover {
  transform: scale(1.04);
  border-color: rgba(20, 184, 166, .42) !important;
}
.auth-minimal-options input:checked {
  border-color: #14b8a6 !important;
  background: linear-gradient(135deg, #0f766e, #14b8a6) !important;
}
.auth-minimal-options input:focus-visible {
  outline: none !important;
  box-shadow: 0 0 0 4px rgba(20, 184, 166, .12) !important;
}
.auth-minimal-options button:hover {
  color: #14b8a6 !important;
  text-decoration: none;
}

.auth-minimal-message {
  color: var(--auth-text-main) !important;
  border-color: var(--auth-line-soft) !important;
}
.auth-minimal-message.success {
  color: #0f766e !important;
  background: rgba(20, 184, 166, .10) !important;
  border-color: rgba(20, 184, 166, .28) !important;
}
.app-shell[data-theme="dark"] .auth-minimal-message.success,
html[data-theme="dark"] .auth-minimal-message.success {
  color: #5eead4 !important;
}
.auth-minimal-message.error {
  color: #dc2626 !important;
  background: rgba(239, 68, 68, .09) !important;
  border-color: rgba(239, 68, 68, .25) !important;
}
.app-shell[data-theme="dark"] .auth-minimal-message.error,
html[data-theme="dark"] .auth-minimal-message.error {
  color: #fca5a5 !important;
}

.auth-minimal-submit:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow:
    0 24px 50px rgba(15, 118, 110, .30),
    inset 0 1px 0 rgba(255,255,255,.25) !important;
}
.auth-minimal-submit:active:not(:disabled),
.auth-minimal-google:active:not(:disabled),
.auth-minimal-demo:active:not(:disabled),
.auth-minimal-tabs button:active {
  transform: translateY(0) scale(.99);
}

.auth-minimal-note {
  color: var(--auth-text-soft) !important;
}
.auth-minimal-note svg {
  color: var(--auth-text-soft) !important;
}

.app-shell[data-theme="dark"] .auth-minimal-google-mark,
html[data-theme="dark"] .auth-minimal-google-mark {
  background: rgba(255,255,255,.96) !important;
  box-shadow: inset 0 0 0 1px rgba(15,23,42,.08), 0 8px 18px rgba(0,0,0,.16) !important;
}

@keyframes authGlowFloat {
  0%, 100% { transform: translate3d(0, 0, 0) scale(1); }
  50% { transform: translate3d(18px, -12px, 0) scale(1.05); }
}
@keyframes authLogoPulse {
  0% { opacity: 0; transform: scale(.74); }
  28% { opacity: .72; }
  100% { opacity: 0; transform: scale(1.75); }
}
@keyframes authPulseLine {
  0%, 100% { transform: scaleX(1); filter: drop-shadow(0 0 0 rgba(20,184,166,0)); }
  42% { transform: scaleX(1.12); filter: drop-shadow(0 0 10px rgba(20,184,166,.36)); }
  58% { transform: scaleX(.96); }
}
@keyframes authOrbitDrift {
  0%, 100% { transform: rotate(-18deg) translate3d(0,0,0); }
  50% { transform: rotate(-14deg) translate3d(-10px, 8px, 0); }
}
@keyframes authOrbitCenter {
  0%, 100% { transform: translate3d(0,0,0) scale(1); opacity: .75; }
  50% { transform: translate3d(-4px, 3px, 0) scale(1.05); opacity: 1; }
}
@keyframes authSpin {
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  .auth-minimal-glow,
  .auth-minimal-logo-mark::after,
  .auth-minimal-logo-mark svg,
  .auth-minimal-orbit span,
  .auth-minimal-theme::before {
    animation: none !important;
  }
  .auth-minimal-brand,
  .auth-minimal-card,
  .auth-minimal-feature,
  .auth-minimal-tabs button,
  .auth-minimal-google,
  .auth-minimal-demo,
  .auth-minimal-submit,
  .auth-minimal-input,
  .auth-minimal-theme svg {
    transition: none !important;
  }
}

@media (max-width: 680px) {
  .auth-minimal-brand:hover,
  .auth-minimal-card:hover,
  .auth-minimal-feature:hover,
  .auth-minimal-tabs button:not(.active):hover,
  .auth-minimal-google:hover:not(:disabled),
  .auth-minimal-demo:hover:not(:disabled),
  .auth-minimal-submit:hover:not(:disabled) {
    transform: none;
  }
}

