/* ===== v109 project-wide design-system normalization + auth layout fix =====
   This final layer is intentionally placed at the end of the stylesheet so the
   login screen, home screen and case screens share the same colors, focus
   states, button language and theme toggle behavior. */
:root {
  --ds-accent: #0f766e;
  --ds-accent-hover: #14b8a6;
  --ds-accent-soft: rgba(20, 184, 166, .11);
  --ds-radius-control: 16px;
  --ds-radius-card: 28px;
  --ds-control-height: 52px;
  --ds-focus-ring: 0 0 0 4px color-mix(in srgb, var(--accent) 16%, transparent);
  --ds-ease: cubic-bezier(.2,.8,.2,1);
}

html[data-theme="light"],
.app-shell[data-theme="light"] {
  --bg: #f6faf9;
  --bg-soft: #edf7f5;
  --surface-1: #ffffff;
  --surface-2: #f8fbfb;
  --surface-3: #eef7f5;
  --surface-elevated: #ffffff;
  --border-subtle: rgba(15, 23, 42, .10);
  --border-medium: rgba(15, 23, 42, .16);
  --border-accent: rgba(15, 118, 110, .30);
  --text-primary: #0f172a;
  --text-secondary: #41516a;
  --text-muted: #66758e;
  --text-faint: #95a3b8;
  --accent: #0f766e;
  --accent-strong: #115e59;
  --accent-blue: #0284c7;
  --button-primary-bg: #0f766e;
  --button-primary-bg-hover: #14b8a6;
  --button-primary-bg-active: #115e59;
  --button-primary-text: #ffffff;
  --button-secondary-bg: #ffffff;
  --button-secondary-bg-hover: #f3fbf9;
  --button-secondary-border: rgba(15, 23, 42, .12);
  --button-secondary-text: #0f172a;
  --button-ghost-bg: rgba(255, 255, 255, .78);
  --button-ghost-bg-hover: rgba(240, 253, 250, .94);
  --button-ghost-text: #0f766e;
  --shadow-card: 0 16px 40px rgba(15, 23, 42, .08);
  --shadow-elevated: 0 26px 70px rgba(15, 23, 42, .11);
}

html[data-theme="dark"],
.app-shell[data-theme="dark"] {
  --bg: #07111a;
  --bg-soft: #0a1721;
  --surface-1: #0d1b27;
  --surface-2: #102433;
  --surface-3: #152f42;
  --surface-elevated: #102231;
  --border-subtle: rgba(148, 163, 184, .18);
  --border-medium: rgba(148, 163, 184, .28);
  --border-accent: rgba(45, 212, 191, .35);
  --text-primary: #f8fafc;
  --text-secondary: #c9d6e4;
  --text-muted: #9dafc2;
  --text-faint: #7f90a4;
  --accent: #2dd4bf;
  --accent-strong: #5eead4;
  --accent-blue: #38bdf8;
  --button-primary-bg: #0f766e;
  --button-primary-bg-hover: #14b8a6;
  --button-primary-bg-active: #0d9488;
  --button-primary-text: #ffffff;
  --button-secondary-bg: rgba(16, 36, 51, .90);
  --button-secondary-bg-hover: rgba(21, 47, 66, .96);
  --button-secondary-border: rgba(148, 163, 184, .24);
  --button-secondary-text: #f8fafc;
  --button-ghost-bg: rgba(16, 36, 51, .72);
  --button-ghost-bg-hover: rgba(21, 47, 66, .94);
  --button-ghost-text: #5eead4;
  --shadow-card: 0 20px 56px rgba(0, 0, 0, .28);
  --shadow-elevated: 0 32px 90px rgba(0, 0, 0, .38);
}

:where(button, a, input, textarea, select):focus-visible {
  outline: none !important;
  box-shadow: var(--ds-focus-ring) !important;
}

:where(.btn, .primary-action, .secondary-action, .ghost-link, .nav-cta, .branch-back-v8, .smart-order-button, .requested-test-action, .sequence-add-btn, .sequence-remove-btn, .sequence-move-btn, .quick-note-chip, .auth-minimal-tabs button, .auth-minimal-google, .auth-minimal-demo, .auth-minimal-submit) {
  min-height: var(--ds-control-height);
  border-radius: var(--ds-radius-control) !important;
  transition: transform .18s var(--ds-ease), box-shadow .18s var(--ds-ease), background .18s var(--ds-ease), border-color .18s var(--ds-ease), color .18s var(--ds-ease) !important;
}

:where(.btn-primary, .primary-action, .nav-cta, .auth-minimal-tabs button.active, .auth-minimal-submit) {
  color: var(--button-primary-text) !important;
  background: linear-gradient(135deg, var(--button-primary-bg), var(--button-primary-bg-hover)) !important;
  border-color: transparent !important;
  box-shadow: 0 16px 34px color-mix(in srgb, var(--button-primary-bg-hover) 24%, transparent) !important;
}

:where(.btn-primary, .primary-action, .nav-cta, .auth-minimal-tabs button.active, .auth-minimal-submit):hover:not(:disabled) {
  transform: translateY(-1px);
  background: linear-gradient(135deg, var(--button-primary-bg-hover), var(--button-primary-bg-active)) !important;
  box-shadow: 0 20px 42px color-mix(in srgb, var(--button-primary-bg-hover) 30%, transparent) !important;
}

:where(.btn-secondary, .secondary-action, .branch-back-v8, .auth-minimal-tabs button:not(.active), .auth-minimal-google) {
  color: var(--button-secondary-text) !important;
  background: var(--button-secondary-bg) !important;
  border: 1px solid var(--button-secondary-border) !important;
}

:where(.btn-icon, .btn-ghost, .ghost-link, .quick-note-chip, .smart-order-button, .requested-test-action, .sequence-add-btn, .sequence-remove-btn, .sequence-move-btn) {
  color: var(--button-ghost-text) !important;
  background: var(--button-ghost-bg) !important;
  border: 1px solid color-mix(in srgb, var(--accent) 20%, var(--border-subtle)) !important;
}

:where(.btn-secondary, .secondary-action, .branch-back-v8, .auth-minimal-tabs button:not(.active), .auth-minimal-google, .btn-icon, .btn-ghost, .ghost-link, .quick-note-chip, .smart-order-button, .requested-test-action):hover:not(:disabled) {
  transform: translateY(-1px);
  color: color-mix(in srgb, var(--accent) 78%, var(--text-primary)) !important;
  background: var(--button-ghost-bg-hover) !important;
  border-color: color-mix(in srgb, var(--accent) 34%, var(--border-subtle)) !important;
}

/* Single shared light/dark control used on login, top nav and any future header. */
.klinikiq-theme-toggle,
.theme-toggle.klinikiq-theme-toggle,
.auth-minimal-theme {
  position: relative !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 46px !important;
  min-width: 46px !important;
  height: 46px !important;
  min-height: 46px !important;
  padding: 0 !important;
  border-radius: 999px !important;
  color: var(--button-ghost-text) !important;
  background: var(--button-ghost-bg) !important;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--border-subtle)) !important;
  box-shadow: 0 12px 26px rgba(15, 23, 42, .08), inset 0 1px 0 rgba(255, 255, 255, .10) !important;
  overflow: hidden !important;
  isolation: isolate !important;
}

.theme-toggle.klinikiq-theme-toggle span,
.klinikiq-theme-toggle span {
  display: inline-flex !important;
}

.klinikiq-theme-toggle::before,
.auth-minimal-theme::before {
  content: "" !important;
  position: absolute !important;
  inset: -60% !important;
  background: conic-gradient(from 180deg, transparent 0deg, color-mix(in srgb, var(--accent) 24%, transparent) 72deg, transparent 132deg) !important;
  opacity: 0 !important;
  transition: opacity .22s var(--ds-ease) !important;
  animation: klinikiqThemeSpin 4.2s linear infinite !important;
}

.klinikiq-theme-toggle:hover:not(:disabled)::before,
.auth-minimal-theme:hover:not(:disabled)::before {
  opacity: 1 !important;
}

.klinikiq-theme-toggle:hover:not(:disabled),
.auth-minimal-theme:hover:not(:disabled) {
  transform: translateY(-1px) !important;
  color: var(--accent-strong) !important;
  border-color: color-mix(in srgb, var(--accent) 38%, var(--border-subtle)) !important;
  background: var(--button-ghost-bg-hover) !important;
}

.theme-toggle-track {
  position: relative !important;
  z-index: 1 !important;
  display: grid !important;
  place-items: center !important;
  width: 100% !important;
  height: 100% !important;
}

.theme-toggle-orb {
  display: grid !important;
  place-items: center !important;
  width: 28px !important;
  height: 28px !important;
  border-radius: 999px !important;
  background: color-mix(in srgb, var(--surface-1) 86%, var(--accent) 6%) !important;
  transition: transform .24s var(--ds-ease), background .24s var(--ds-ease), color .24s var(--ds-ease) !important;
}

.klinikiq-theme-toggle:hover:not(:disabled) .theme-toggle-orb {
  transform: rotate(-18deg) scale(1.05) !important;
}

.klinikiq-theme-toggle svg,
.auth-minimal-theme svg {
  width: 19px !important;
  height: 19px !important;
  margin: 0 !important;
  color: currentColor !important;
}

.theme-toggle-label {
  position: relative !important;
  z-index: 1 !important;
  margin-left: 8px !important;
  font-size: 13px !important;
  font-weight: 750 !important;
  color: currentColor !important;
  white-space: nowrap !important;
}

.klinikiq-theme-toggle:has(.theme-toggle-label) {
  width: auto !important;
  min-width: 46px !important;
  padding: 0 13px 0 8px !important;
}

@keyframes klinikiqThemeSpin { to { transform: rotate(360deg); } }

/* Login screen: remove large side gutters and keep both cards optically aligned. */
.app-shell:has(.auth-minimal-shell) {
  padding-top: 0 !important;
  overflow-x: hidden !important;
}

.auth-minimal-shell {
  width: min(1640px, calc(100vw - clamp(32px, 4.2vw, 76px))) !important;
  min-height: 100svh !important;
  grid-template-columns: minmax(620px, 1fr) minmax(420px, 540px) !important;
  gap: clamp(38px, 5vw, 84px) !important;
  padding: clamp(22px, 3.4vh, 44px) 0 !important;
  overflow: visible !important;
  align-items: center !important;
}

.auth-minimal-brand {
  min-height: clamp(560px, 72vh, 680px) !important;
  border-radius: var(--ds-radius-card) !important;
  padding: clamp(36px, 4.6vw, 66px) !important;
}

.auth-minimal-card {
  align-self: center !important;
  border-radius: var(--ds-radius-card) !important;
  padding: clamp(28px, 3vw, 42px) !important;
  gap: 14px !important;
}

.auth-minimal-hero h1 {
  max-width: 820px !important;
  font-size: clamp(48px, 5.2vw, 84px) !important;
  line-height: .95 !important;
  letter-spacing: -.066em !important;
}

.auth-minimal-hero p {
  max-width: 560px !important;
}

.auth-minimal-features {
  max-width: 760px !important;
}

.auth-minimal-input {
  min-height: 56px !important;
  border-radius: var(--ds-radius-control) !important;
  border-color: var(--button-secondary-border) !important;
  background: var(--button-ghost-bg) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.10), 0 8px 22px rgba(15, 23, 42, .035) !important;
}

.auth-minimal-input:hover {
  border-color: color-mix(in srgb, var(--accent) 24%, var(--border-subtle)) !important;
}

.auth-minimal-input:focus-within {
  transform: none !important;
  border-color: color-mix(in srgb, var(--accent) 48%, var(--border-subtle)) !important;
  background: color-mix(in srgb, var(--surface-1) 94%, var(--accent) 4%) !important;
  box-shadow: var(--ds-focus-ring), 0 12px 26px rgba(15, 23, 42, .055) !important;
}

.auth-minimal-input input:focus,
.auth-minimal-input input:focus-visible {
  box-shadow: none !important;
}

