@keyframes kiqOrbitForward { from { transform: translate(-50%, -50%) rotate(0deg); } to { transform: translate(-50%, -50%) rotate(360deg); } }
@keyframes kiqOrbitReverse { from { transform: translate(-50%, -50%) rotate(0deg); } to { transform: translate(-50%, -50%) rotate(-360deg); } }
@keyframes kiqCounterForward { from { transform: rotate(0deg); } to { transform: rotate(-360deg); } }
@keyframes kiqCounterReverse { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
@keyframes kiqSweepForward { from { transform: translate(-50%, -50%) rotate(0deg); } to { transform: translate(-50%, -50%) rotate(360deg); } }
@keyframes kiqSweepReverse { from { transform: translate(-50%, -50%) rotate(0deg); } to { transform: translate(-50%, -50%) rotate(-360deg); } }
@keyframes kiqAuraBreathe { 0%,100% { opacity: .72; transform: translate(-50%, -50%) scale(.98); } 50% { opacity: .92; transform: translate(-50%, -50%) scale(1.04); } }
@keyframes kiqCoreBreathe { 0%,100% { transform: translate(-50%, -50%) scale(1); } 50% { transform: translate(-50%, -50%) scale(1.025); } }

