body:not(.klinikiq-auth-lock) .top-shell-nav {
  width: min(1780px, calc(100% - 28px));
  min-height: 90px;
  display: grid;
  grid-template-columns: minmax(260px, 340px) minmax(320px, 460px) minmax(540px, 1fr);
  align-items: center;
  gap: 16px;
  padding: 14px 18px;
  border-radius: 28px;
  border: 1px solid color-mix(in srgb, var(--accent) 10%, var(--border-subtle));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--surface-1) 94%, transparent), color-mix(in srgb, var(--surface-2) 90%, transparent));
  box-shadow: 0 16px 40px rgba(15, 23, 42, 0.08);
  backdrop-filter: blur(18px);
}

body:not(.klinikiq-auth-lock) .nav-brand {
  flex: 0 0 64px !important;
  width: 64px !important;
  min-width: 64px !important;
  max-width: 64px !important;
  height: 64px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 0 !important;
  padding: 0 !important;
  border-radius: 20px !important;
  position: relative !important;
}

body:not(.klinikiq-auth-lock) .nav-brand::before {
  content: "";
  position: absolute;
  inset: -10px;
  border-radius: 26px;
  background: radial-gradient(circle, color-mix(in srgb, var(--accent) 18%, transparent) 0%, transparent 68%);
  opacity: 0.28;
  pointer-events: none;
}

body:not(.klinikiq-auth-lock) .nav-brand-mark {
  width: 52px !important;
  height: 52px !important;
  border-radius: 18px !important;
  padding: 7px !important;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--surface-1) 94%, transparent), color-mix(in srgb, var(--accent) 7%, var(--surface-2))) !important;
  border: 1px solid color-mix(in srgb, var(--accent) 14%, var(--border-subtle)) !important;
  box-shadow:
    0 10px 24px color-mix(in srgb, var(--accent) 12%, transparent),
    inset 0 1px 0 rgba(255,255,255,0.55) !important;
}

body:not(.klinikiq-auth-lock) .nav-brand-mark svg {
  width: 23px !important;
  height: 23px !important;
}

