body:not(.klinikiq-auth-lock) .nav-brand-mark-pulse {
  animation: klinikiqNavBrandPulse 4.2s ease-in-out infinite !important;
}

@keyframes klinikiqNavBrandPulse {
  0%, 100% {
    transform: translateY(0) scale(1);
    box-shadow:
      0 10px 24px color-mix(in srgb, var(--accent) 12%, transparent),
      inset 0 1px 0 rgba(255,255,255,0.55);
    filter: saturate(1);
  }
  50% {
    transform: translateY(-1px) scale(1.035);
    box-shadow:
      0 14px 30px color-mix(in srgb, var(--accent) 18%, transparent),
      0 0 0 6px color-mix(in srgb, var(--accent) 5%, transparent),
      inset 0 1px 0 rgba(255,255,255,0.62);
    filter: saturate(1.06);
  }
}

body:not(.klinikiq-auth-lock) .nav-mode-switch {
