  border-color: color-mix(in srgb, var(--accent) 36%, transparent);
}
.branch-card[data-branch="tus-spot-olgular"] .branch-progress span {
  background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 72%, white 12%), color-mix(in srgb, var(--accent-blue) 62%, white 8%));
}
.branch-card.is-launching[data-branch="tus-spot-olgular"] .icon-badge svg {
  animation: branch-spot-tick 420ms cubic-bezier(.22,1,.36,1) 1 both;
}
@keyframes branch-spot-tick {
  0%, 100% { transform: rotate(0deg) scale(1); filter: drop-shadow(0 0 0 transparent); }
  30% { transform: rotate(-12deg) scale(1.16); filter: drop-shadow(0 0 9px color-mix(in srgb, currentColor 28%, transparent)); }
  62% { transform: rotate(10deg) scale(1.05); }
}
.tus-spot-olgular-question-callout {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 13px;
  margin: 2px 0 12px;
