  border-radius: 16px;
  color: var(--text-primary);
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 10%, transparent), color-mix(in srgb, var(--surface-1) 92%, transparent));
  box-shadow: inset 0 1px 0 color-mix(in srgb, white 38%, transparent);
}
