.branch-card:is([data-branch="tus-spot-olgular"], [data-branch="medical-microbiology"], [data-branch="medical-pharmacology"], [data-branch="pediatrics"]) .branch-card-head .branch-icon-badge {
  display: grid !important;
  place-items: center !important;
  position: relative !important;
  width: 52px !important;
  height: 52px !important;
  min-width: 52px !important;
  border-radius: 18px !important;
  overflow: visible !important;
  isolation: isolate !important;
  transform-origin: 50% 50% !important;
}

.branch-card:is([data-branch="tus-spot-olgular"], [data-branch="medical-microbiology"], [data-branch="medical-pharmacology"], [data-branch="pediatrics"]) .branch-card-head .branch-icon-badge::before {
  content: '';
  position: absolute;
  inset: 7px;
  z-index: -1;
  border-radius: 15px;
  background: radial-gradient(circle, color-mix(in srgb, var(--branch-motion-accent) 18%, transparent), transparent 70%);
  opacity: .42;
  filter: blur(7px);
  transform: translateZ(0);
}

.branch-icon-glyph {
  display: block !important;
  width: 31px !important;
  height: 31px !important;
  overflow: visible !important;
  color: currentColor !important;
  transform-box: fill-box !important;
  transform-origin: 50% 50% !important;
  backface-visibility: hidden !important;
}
.branch-icon-glyph-card { stroke-width: 1.72 !important; }
.branch-icon-glyph-transition { width: 82px !important; height: 82px !important; stroke-width: 1.62 !important; }
.branch-icon-glyph * { vector-effect: non-scaling-stroke; transform-box: fill-box; transform-origin: center; }

.branch-icon-badge-tus-spot-olgular .branch-icon-glyph-card { transform: translate(.15px, .15px) scale(1.02) !important; }
.branch-icon-badge-medical-microbiology .branch-icon-glyph-card { transform: translate(.1px, .1px) scale(1.01) !important; }
