/* =========================================================
   KLINIKIQ V176 — AI Spot single-flow layout, no nested scroll
   The AI generated TUS Spot screen must not inherit the sticky,
   viewport-bound right workspace from the classic case player.
   Narrative, options and feedback now live inside one natural-height
   panel; only the page/body scrolls when feedback expands.
   ========================================================= */
.ai-spot-player-shell {
  width: 100%;
}

.ai-spot-unified-panel.card-surface {
  display: grid !important;
  gap: 0 !important;
  width: 100% !important;
  min-height: 0 !important;
  height: auto !important;
  max-height: none !important;
  overflow: visible !important;
  padding: clamp(22px, 3.2vw, 36px) !important;
  border-radius: 30px !important;
  background:
    radial-gradient(circle at 14% 0%, rgba(20, 184, 166, 0.10), transparent 34%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 253, 252, 0.94)) !important;
  border: 1px solid rgba(15, 118, 110, 0.11) !important;
  box-shadow: 0 24px 62px rgba(15, 23, 42, 0.09) !important;
}

.ai-spot-unified-panel,
.ai-spot-unified-panel * {
  scrollbar-gutter: auto;
}

.ai-spot-narrative-card.is-embedded {
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  overflow: visible !important;
}

.ai-spot-narrative-card.is-embedded::after {
  display: none !important;
}

.ai-spot-answer-flow {
  position: relative;
  display: grid;
  gap: 16px;
  min-height: 0 !important;
  height: auto !important;
  max-height: none !important;
  margin-top: clamp(22px, 3vw, 32px);
  padding-top: clamp(20px, 2.4vw, 28px);
  border-top: 1px solid rgba(20, 184, 166, 0.18);
  overflow: visible !important;
