/* Komite dashboard refinement v45 */
.komite-hero {
  padding: clamp(1.5rem, 3vw, 2.15rem);
  border-radius: 1.9rem;
  background:
    radial-gradient(circle at top right, rgba(153, 246, 228, 0.16), transparent 38%),
    linear-gradient(180deg, rgba(255,255,255,0.96), rgba(248,250,252,0.94));
}

.komite-hero h1 {
  max-width: 760px;
  margin: 0;
  font-size: clamp(2.1rem, 4.4vw, 4rem);
  line-height: 0.98;
  letter-spacing: -0.04em;
}

.komite-hero p {
  max-width: 760px;
  margin: .9rem 0 0;
  color: #475569;
  font-size: clamp(1rem, 1.8vw, 1.18rem);
  line-height: 1.6;
}

.komite-hero-actions {
  margin-top: 1.35rem;
}

.komite-hero-actions .btn.btn-primary {
  min-height: 50px;
  padding-inline: 1rem 1.1rem;
  border-radius: 1rem;
  font-weight: 850;
}

.komite-dashboard-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.komite-dashboard-card {
  min-height: 168px;
  grid-template-columns: auto 1fr;
  grid-template-rows: auto 1fr auto;
  align-items: start;
  gap: .9rem 1rem;
  padding: 1.15rem 1.15rem 1.05rem;
  border-radius: 1.45rem;
  background: linear-gradient(180deg, rgba(255,255,255,0.96), rgba(248,250,252,0.92));
  border: 1px solid rgba(15, 118, 110, 0.08);
  box-shadow: 0 16px 36px rgba(15, 23, 42, 0.06);
}

.komite-dashboard-card.primary {
  background: linear-gradient(135deg, rgba(236, 253, 245, 0.98), rgba(255,255,255,0.95));
  border-color: rgba(20, 184, 166, 0.16);
}

.komite-card-icon {
  width: 52px;
  height: 52px;
  border-radius: 16px;
  display: inline-grid;
  place-items: center;
  background: linear-gradient(135deg, rgba(204, 251, 241, 0.95), rgba(240, 253, 250, 0.95));
  color: #0f766e;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.72);
}

.komite-dashboard-card-copy {
  grid-column: 2;
  grid-row: 1 / span 2;
  align-self: stretch;
  display: grid;
  gap: .4rem;
}

.komite-dashboard-card strong {
  display: block;
  color: #0f172a;
  font-size: 1.18rem;
  line-height: 1.2;
}

.komite-dashboard-card p {
  margin: 0;
  color: #475569;
  font-size: .95rem;
  line-height: 1.58;
}

.komite-card-action {
  grid-column: 1 / -1;
  justify-self: start;
  margin-top: .15rem;
  padding: .68rem .9rem;
  border-radius: 999px;
  background: rgba(240, 253, 250, 0.9);
  border: 1px solid rgba(20, 184, 166, 0.14);
  font-size: .88rem;
  font-weight: 850;
}

@media (max-width: 780px) {
  .komite-dashboard-grid {
    grid-template-columns: 1fr;
  }

  .komite-dashboard-card {
    min-height: 0;
  }
}

html[data-theme='dark'] .komite-hero {
  background:
    radial-gradient(circle at top right, rgba(45, 212, 191, 0.12), transparent 40%),
    linear-gradient(180deg, rgba(15,23,42,0.92), rgba(15,23,42,0.88));
}

html[data-theme='dark'] .komite-hero p,
html[data-theme='dark'] .komite-dashboard-card p {
  color: #94a3b8;
}

html[data-theme='dark'] .komite-dashboard-card {
  background: linear-gradient(180deg, rgba(15,23,42,0.92), rgba(15,23,42,0.88));
  border-color: rgba(148, 163, 184, 0.12);
  box-shadow: none;
}

html[data-theme='dark'] .komite-dashboard-card.primary {
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.95), rgba(17, 94, 89, 0.28));
}

html[data-theme='dark'] .komite-card-icon {
  background: linear-gradient(135deg, rgba(15, 118, 110, 0.24), rgba(15, 23, 42, 0.9));
}

html[data-theme='dark'] .komite-card-action {
  background: rgba(15, 118, 110, 0.16);
  border-color: rgba(45, 212, 191, 0.14);
}


